import probabilityInference from './probability-inference';
import type { Bilingual } from '../../lib/lesson-types';

type Teaching = {
  application: Bilingual;
  formula: Bilingual;
  steps: Bilingual[];
  solution?: Bilingual[];
};

const b = (en: string, vi: string): Bilingual => ({ en, vi });
const f = (equation: string, enCondition: string, viCondition: string): Bilingual =>
  b(`${equation} (${enCondition})`, `${equation} (${viCondition})`);
const t = (application: Bilingual, formula: Bilingual, steps: Bilingual[], solution?: Bilingual[]): Teaching =>
  ({ application, formula, steps, ...(solution ? { solution } : {}) });

// Each row follows the exercise order in the canonical probability file.
const teachingByWeek: Record<number, Teaching[]> = {
  29: [
    t(b('Pool the masses of states that produce the same observed value: b and c both map to 0, while a maps to 1.', 'Cộng khối lượng các trạng thái cho cùng một giá trị quan sát: b và c cùng ánh xạ tới 0, còn a ánh xạ tới 1.'), f('P_X(A)=P(X∈A),  E[g(X)]=∫g dP_X', 'X measurable; A measurable; g integrable', 'X đo được; A đo được; g khả tích'), [b('The preimage of 1 is {a}, so P_X(1)=1/2; the preimage of 0 is {b,c}, so P_X(0)=1/2.', 'Ảnh ngược của 1 là {a}, nên P_X(1)=1/2; ảnh ngược của 0 là {b,c}, nên P_X(0)=1/2.'), b('Use the two-point law: E[X]=0·1/2+1·1/2=1/2.', 'Dùng luật hai điểm: E[X]=0·1/2+1·1/2=1/2.'), b('Then E[2X+1]=2E[X]+1=2; this agrees with summing 1 at X=0 and 3 at X=1.', 'Khi đó E[2X+1]=2E[X]+1=2; kết quả khớp với tổng các giá trị 1 khi X=0 và 3 khi X=1.')]),
    t(b('Prove the law-to-expectation rule first for events, then extend it to a general nonnegative measurable payoff.', 'Chứng minh quy tắc từ luật tới kỳ vọng trước cho biến cố, rồi mở rộng sang khoản trả không âm đo được.'), f('∫g dP_X=∫g(X)dP', 'X measurable; first g≥0, then integrable signed g', 'X đo được; trước hết g≥0, sau đó g có dấu khả tích'), [b('For g=1_A, both sides equal P(X∈A), by the definition P_X(A)=P(X∈A).', 'Với g=1_A, hai vế bằng P(X∈A) theo định nghĩa P_X(A)=P(X∈A).'), b('Linearity gives the identity for nonnegative simple functions, which are finite sums of indicators.', 'Tính tuyến tính cho đồng nhất thức với hàm đơn không âm, là tổng hữu hạn các hàm chỉ thị.'), b('Choose simple g_m increasing to g. Monotone convergence passes both integrals to the limit; for integrable signed g apply this to g⁺ and g⁻.', 'Chọn hàm đơn g_m tăng tới g. Hội tụ đơn điệu cho phép lấy giới hạn cả hai tích phân; với g có dấu khả tích, áp dụng lần lượt cho g⁺ và g⁻.')]),
    t(b('A uniform draw U is transformed to a nonnegative waiting-time variable Y=−log U.', 'Biến đều U được biến đổi thành biến thời gian chờ không âm Y=−log U.'), f('F_Y(y)=0 (y<0);  F_Y(y)=1−e^(−y) (y≥0);  E[Y]=1', 'U uniform on (0,1)', 'U phân phối đều trên (0,1)'), [b('Y≥0, so F_Y(y)=0 for y<0.', 'Y≥0, nên F_Y(y)=0 khi y<0.'), b('For y≥0, −log U≤y iff U≥e^(−y); uniformity gives F_Y(y)=1−e^(−y).', 'Với y≥0, −log U≤y khi và chỉ khi U≥e^(−y); tính đều cho F_Y(y)=1−e^(−y).'), b('The density is e^(−y) on y≥0; integration by parts gives ∫₀∞ye^(−y)dy=1.', 'Mật độ là e^(−y) trên y≥0; tích phân từng phần cho ∫₀∞ye^(−y)dy=1.')]),
    t(b('Check whether a set belongs to the stated event sigma-algebra before asking for its probability.', 'Kiểm tra tập có thuộc sigma-đại số biến cố đã cho hay không trước khi hỏi xác suất của nó.'), f('P(A) is defined only for A∈𝓕', 'A is an event in the chosen probability space', 'A là biến cố trong không gian xác suất đã chọn'), [b('In the countable-cocountable sigma-algebra, a set is measurable only if it or its complement is countable.', 'Trong sigma-đại số đếm được/bù đếm được, tập đo được khi nó hoặc phần bù của nó đếm được.'), b('A Vitali subset V and its complement are uncountable, so V is outside this sigma-algebra.', 'Tập Vitali V và phần bù đều không đếm được, nên V nằm ngoài sigma-đại số này.'), b('The given measure has no value P(V); “undefined” is different from assigning probability zero.', 'Độ đo đã cho không có giá trị P(V); “chưa định nghĩa” khác với gán xác suất bằng không.')]),
    t(b('Treat the vector Z=(X,Y) as one observation and map it through the measurable statistic T(x,y)=x+y.', 'Coi vector Z=(X,Y) là một quan sát và ánh xạ qua thống kê đo được T(x,y)=x+y.'), f('P(X+Y∈A)=μ(T⁻¹A);  E[φ(X+Y)]=∫φ(x+y)dμ', 'μ is the joint law; T is Borel measurable; φ≥0 Borel', 'μ là luật chung; T đo được Borel; φ≥0 đo được Borel'), [b('Addition is continuous, hence T is Borel measurable; its pushforward law is T#μ.', 'Phép cộng liên tục nên T đo được Borel; luật đẩy tới là T#μ.'), b('For Borel A, the event {X+Y∈A} is the preimage T⁻¹(A), giving probability μ(T⁻¹A).', 'Với A Borel, biến cố {X+Y∈A} là ảnh ngược T⁻¹(A), nên có xác suất μ(T⁻¹A).'), b('Apply the expectation identity to φ and the joint law μ; do not replace μ by a product unless X and Y are independent.', 'Áp dụng đồng nhất thức kỳ vọng cho φ và luật chung μ; không thay μ bằng tích luật nếu chưa biết X,Y độc lập.')]),
  ],
  30: [
    t(b('On a finite probability space, expectation is the mass-weighted sum of the displayed values.', 'Trên không gian xác suất hữu hạn, kỳ vọng là tổng các giá trị đã cho nhân với khối lượng.'), f('E[h(X)]=Σᵢ pᵢh(xᵢ)', 'pᵢ are atom masses summing to one', 'pᵢ là khối lượng nguyên tử có tổng bằng một'), [b('For X=(0,3,6), E[X]=0·1/2+3·1/3+6·1/6=2.', 'Với X=(0,3,6), E[X]=0·1/2+3·1/3+6·1/6=2.'), b('Square the values before weighting: E[X²]=0+9/3+36/6=9.', 'Bình phương giá trị trước khi nhân khối lượng: E[X²]=0+9/3+36/6=9.'), b('For |X−2|=(2,1,4), the weighted sum is 2/2+1/3+4/6=5/3.', 'Với |X−2|=(2,1,4), tổng có trọng số là 2/2+1/3+4/6=5/3.')]),
    t(b('Compare the simple-function minorants available below X and Y, even if their supremum is infinite.', 'So sánh các hàm đơn chặn dưới X và Y, kể cả khi supremum là vô hạn.'), f('0≤X≤Y ⇒ E[X]≤E[Y]', 'X,Y measurable and nonnegative; expectation may be extended-valued', 'X,Y đo được và không âm; kỳ vọng có thể nhận giá trị mở rộng'), [b('Any nonnegative simple s with s≤X also satisfies s≤Y.', 'Mọi hàm đơn không âm s≤X cũng thỏa s≤Y.'), b('Thus the candidate set in the supremum defining E[X] is contained in the one defining E[Y].', 'Vì vậy tập ứng viên trong supremum định nghĩa E[X] nằm trong tập định nghĩa E[Y].'), b('Taking suprema preserves the order; if E[Y]=∞ the inequality remains valid in the extended real numbers.', 'Lấy supremum bảo toàn thứ tự; nếu E[Y]=∞ thì bất đẳng thức vẫn đúng trong số thực mở rộng.')]),
    t(b('Approximate an unbounded nonnegative random variable by quantized truncations that increase pointwise.', 'Xấp xỉ biến ngẫu nhiên không âm không bị chặn bằng các phép cắt cụt lượng tử hóa tăng theo từng điểm.'), f('Xₙ=2⁻ⁿ⌊2ⁿ(X∧n)⌋ ↑ X;  E[Xₙ]↑E[X]', 'X measurable and nonnegative', 'X đo được và không âm'), [b('For fixed n, X∧n is bounded and the floor takes finitely many values in multiples of 2⁻ⁿ, so Xₙ is simple.', 'Với n cố định, X∧n bị chặn và phép lấy sàn chỉ nhận hữu hạn bội số của 2⁻ⁿ, nên Xₙ là hàm đơn.'), b('Finer grids and larger truncation levels make Xₙ nondecreasing; for every finite X(ω), the quantization error is below 2⁻ⁿ.', 'Lưới mịn hơn và mức cắt cụt lớn hơn khiến Xₙ tăng; với mọi X(ω) hữu hạn, sai số lượng tử hóa nhỏ hơn 2⁻ⁿ.'), b('Hence Xₙ↑X pointwise, and monotone convergence gives E[Xₙ]↑E[X], including an infinite limit.', 'Do đó Xₙ↑X từng điểm, và hội tụ đơn điệu cho E[Xₙ]↑E[X], kể cả giới hạn vô hạn.')]),
    t(b('A signed variable can have two infinite one-sided expectations, leaving their difference undefined.', 'Biến có dấu có thể có hai kỳ vọng một phía vô hạn, khiến hiệu của chúng chưa xác định.'), f('E[Z]=E[Z⁺]−E[Z⁻]', 'difference is defined only if at least one term is finite', 'hiệu chỉ xác định nếu ít nhất một số hạng hữu hạn'), [b('Here E[Z⁺]=Σₖ k·c/k²=cΣₖ1/k=∞; by symmetry E[Z⁻]=∞ too.', 'Ở đây E[Z⁺]=Σₖ k·c/k²=cΣₖ1/k=∞; do đối xứng E[Z⁻]=∞.'), b('Both positive and negative parts have infinite expectation, so ∞−∞ is undefined.', 'Cả phần dương lẫn phần âm đều có kỳ vọng vô hạn, nên ∞−∞ chưa xác định.'), b('Therefore E[Z] does not exist as an extended expectation; finite expectation would require E|Z|<∞.', 'Vì vậy E[Z] không tồn tại dưới dạng kỳ vọng mở rộng; kỳ vọng hữu hạn đòi hỏi E|Z|<∞.')]),
    t(b('Represent each nonnegative value X(ω) as the area under its threshold indicators, then average.', 'Biểu diễn mỗi giá trị không âm X(ω) thành diện tích dưới các hàm chỉ thị ngưỡng rồi lấy trung bình.'), f('X=∫₀∞1{X>t}dt;  E[X]=∫₀∞P(X>t)dt', 'X≥0 measurable; Tonelli permits the interchange', 'X≥0 đo được; Tonelli cho phép đổi thứ tự'), [b('For each outcome, the set of t with 0≤t<X(ω) has length X(ω).', 'Với mỗi kết quả, tập t thỏa 0≤t<X(ω) có độ dài X(ω).'), b('Tonelli interchanges expectation and the nonnegative t-integral, yielding the tail formula.', 'Tonelli đổi thứ tự kỳ vọng và tích phân không âm theo t, cho công thức đuôi.'), b('For Exp(1), P(X>t)=e^(−t), so E[X]=∫₀∞e^(−t)dt=1.', 'Với Exp(1), P(X>t)=e^(−t), nên E[X]=∫₀∞e^(−t)dt=1.')]),
  ],
  31: [
    t(b('The indicator of an increasing union is the increasing pointwise limit of the event indicators.', 'Hàm chỉ thị của hợp tăng là giới hạn điểm tăng của các hàm chỉ thị biến cố.'), f('Aₙ↑A ⇒ P(A)=limₙP(Aₙ)', 'probability measure; Aₙ measurable', 'độ đo xác suất; Aₙ đo được'), [b('Because Aₙ↑A, 1_Aₙ(ω) increases to 1_A(ω) for every ω.', 'Vì Aₙ↑A, 1_Aₙ(ω) tăng tới 1_A(ω) với mọi ω.'), b('Apply monotone convergence to obtain P(A)=limₙP(Aₙ).', 'Áp dụng hội tụ đơn điệu để được P(A)=limₙP(Aₙ).'), b('Thus P(A)=limₙ(1−2⁻ⁿ)=1.', 'Do đó P(A)=limₙ(1−2⁻ⁿ)=1.')]),
    t(b('Use the increasing tail infima Y_m to turn a liminf into a monotone limit.', 'Dùng các infimum đuôi tăng Y_m để biến liminf thành giới hạn đơn điệu.'), f('Y_m=infₙ≥m Xₙ ↑ liminfₙXₙ;  E[liminf Xₙ]≤liminf E[Xₙ]', 'Xₙ≥0 measurable', 'Xₙ≥0 đo được'), [b('As m grows, the tail {n≥m} shrinks, so its infimum Y_m cannot decrease.', 'Khi m tăng, đuôi {n≥m} nhỏ lại nên infimum Y_m không thể giảm.'), b('Every fixed term eventually leaves the tail; the increasing limit of Y_m is liminfₙXₙ.', 'Mỗi số hạng cố định cuối cùng rời khỏi đuôi; giới hạn tăng của Y_m là liminfₙXₙ.'), b('Since Y_m≤Xₙ for every n≥m, E[Y_m]≤infₙ≥mE[Xₙ]. Take m→∞ and use MCT.', 'Vì Y_m≤Xₙ với mọi n≥m, E[Y_m]≤infₙ≥mE[Xₙ]. Cho m→∞ và dùng MCT.')]),
    t(b('The spike moves toward zero: each fixed point is eventually outside the shrinking interval.', 'Đỉnh nhọn dịch về 0: mỗi điểm cố định cuối cùng nằm ngoài khoảng đang co lại.'), f('Xₙ=n1_(0,1/n):  Xₙ→0 a.e.;  E[Xₙ]=1', 'Lebesgue measure on (0,1)', 'độ đo Lebesgue trên (0,1)'), [b('For each fixed x>0, n>1/x implies x≥1/n, so Xₙ(x)=0 eventually; the a.e. limit is 0.', 'Với mỗi x>0 cố định, n>1/x suy ra x≥1/n, nên cuối cùng Xₙ(x)=0; giới hạn hầu khắp nơi là 0.'), b('The spike has height n and width 1/n, giving E[Xₙ]=n·(1/n)=1.', 'Đỉnh có chiều cao n và độ rộng 1/n, nên E[Xₙ]=n·(1/n)=1.'), b('Therefore E[liminf Xₙ]=0 but liminf E[Xₙ]=1, so Fatou is strict.', 'Vì vậy E[liminf Xₙ]=0 nhưng liminf E[Xₙ]=1, nên bất đẳng thức Fatou là nghiêm.')]),
    t(b('Apply Fatou to the nonnegative difference between a common integrable ceiling and each variable.', 'Áp dụng Fatou cho hiệu không âm giữa một trần khả tích chung và từng biến.'), f('0≤Xₙ≤Y, E[Y]<∞ ⇒ E[limsup Xₙ]≥limsup E[Xₙ]', 'Y integrable and Xₙ measurable', 'Y khả tích và Xₙ đo được'), [b('Set Uₙ=Y−Xₙ≥0. Fatou gives E[liminf Uₙ]≤liminf E[Uₙ].', 'Đặt Uₙ=Y−Xₙ≥0. Fatou cho E[liminf Uₙ]≤liminf E[Uₙ].'), b('Pointwise, liminf(Y−Xₙ)=Y−limsup Xₙ; in expectation the left side is E[Y]−E[limsup Xₙ].', 'Theo từng điểm, liminf(Y−Xₙ)=Y−limsup Xₙ; trong kỳ vọng vế trái là E[Y]−E[limsup Xₙ].'), b('The right side is E[Y]−limsup E[Xₙ]. Cancel finite E[Y] and rearrange to get the reverse-Fatou inequality.', 'Vế phải là E[Y]−limsup E[Xₙ]. Khử E[Y] hữu hạn và chuyển vế để được bất đẳng thức Fatou đảo.')]),
    t(b('Continuity from above requires a finite-measure first set; without it, a decreasing sequence can retain infinite mass at every stage.', 'Tính liên tục từ trên cần tập đầu có độ đo hữu hạn; nếu không, dãy giảm có thể giữ khối lượng vô hạn ở mọi bước.'), f('Aₙ↓A, μ(A₁)<∞ ⇒ μ(Aₙ)↓μ(A)', 'measure μ; finite first-set measure', 'độ đo μ; tập đầu có độ đo hữu hạn'), [b('For probability, apply continuity from below to A₁\Aₙ, which increases to A₁\A.', 'Với xác suất, áp dụng liên tục từ dưới cho A₁\Aₙ, tăng tới A₁\A.'), b('Since P(A₁)<∞, subtracting from P(A₁) gives P(Aₙ)↓P(A).', 'Vì P(A₁)<∞, lấy hiệu với P(A₁) cho P(Aₙ)↓P(A).'), b('On Lebesgue R, Aₙ=(n,∞) decreases to ∅ but every measure is ∞; the finite-first-set condition fails.', 'Trên R với độ đo Lebesgue, Aₙ=(n,∞) giảm về ∅ nhưng mọi tập đều có độ đo ∞; điều kiện độ đo hữu hạn của tập đầu bị vi phạm.')]),
  ],
  32: [
    t(b('Check each sequence separately: pointwise convergence, integral convergence, and the availability of one integrable dominator.', 'Xét riêng từng dãy: hội tụ điểm, hội tụ tích phân và sự tồn tại của một hàm trội khả tích chung.'), f('|fₙ|≤g, ∫g<∞ ⇒ ∫fₙ→∫f', 'a.e. convergence plus one integrable dominator', 'hội tụ hầu khắp nơi và một hàm trội khả tích'), [b('For xⁿ, the a.e. limit on (0,1) is 0 and 0≤xⁿ≤1; DCT gives integral 1/(n+1)→0.', 'Với xⁿ, giới hạn hầu khắp nơi trên (0,1) là 0 và 0≤xⁿ≤1; DCT cho tích phân 1/(n+1)→0.'), b('For n1_(0,1/n), the pointwise limit is 0 and each integral is 1, but no integrable common bound can dominate the moving heights.', 'Với n1_(0,1/n), giới hạn điểm là 0 và mọi tích phân bằng 1, nhưng không có hàm trội khả tích chung chặn các đỉnh tăng.'), b('For sin(nx)/n, |fₙ|≤1 and fₙ→0; DCT applies and its integral is (1−cos n)/n²→0.', 'Với sin(nx)/n, |fₙ|≤1 và fₙ→0; DCT áp dụng và tích phân là (1−cos n)/n²→0.')]),
    t(b('A rectangle indicator separates into one factor for each coordinate, making it a basic Tonelli check.', 'Hàm chỉ thị hình chữ nhật tách thành một thừa số cho mỗi tọa độ, tạo phép kiểm tra Tonelli cơ bản.'), f('∫∫1_(A×B)d(μ×ν)=μ(A)ν(B)', 'measurable A,B; product measures; nonnegative integrand', 'A,B đo được; độ đo tích; hàm dưới tích phân không âm'), [b('Fix y∈B: integrating 1_(A×B)(x,y) over x gives μ(A); for y∉B it gives zero.', 'Cố định y∈B: tích phân 1_(A×B)(x,y) theo x cho μ(A); nếu y∉B thì bằng không.'), b('Integrating that result over y gives μ(A)ν(B); reversing the order gives the same product.', 'Tích phân kết quả theo y cho μ(A)ν(B); đổi thứ tự tích phân cũng cho cùng tích.'), b('This verifies the rectangle case only. General Tonelli needs measurable nonnegative functions on the stated sigma-finite product spaces.', 'Điều này chỉ xác minh trường hợp hình chữ nhật. Tonelli tổng quát cần hàm không âm đo được trên các không gian tích sigma-hữu hạn đã nêu.')]),
    t(b('A conditionally convergent double series can change value when rows and columns regroup terms.', 'Chuỗi kép hội tụ có điều kiện có thể đổi giá trị khi gom lại theo hàng hay cột.'), f('Σᵢⱼ|aᵢⱼ|<∞ ⇒ ΣᵢΣⱼaᵢⱼ=ΣⱼΣᵢaᵢⱼ', 'absolute summability; integral analogue: ∫|f|<∞', 'tổng tuyệt đối hội tụ; tương tự tích phân: ∫|f|<∞'), [b('In a conditionally convergent series, positive and negative terms can be rearranged to produce different sums; a double series permits analogous regrouping.', 'Trong chuỗi hội tụ có điều kiện, có thể sắp xếp lại các số hạng dương và âm để được tổng khác; chuỗi kép cho phép gom nhóm tương tự.'), b('Absolute summability makes all regroupings converge to the same value and licenses iterated summation.', 'Hội tụ tuyệt đối khiến mọi cách gom nhóm cho cùng giá trị và cho phép đổi thứ tự tổng.'), b('For integrals, Fubini requires ∫|f|<∞; Tonelli alone covers nonnegative f, not arbitrary signed rearrangements.', 'Với tích phân, Fubini cần ∫|f|<∞; riêng Tonelli áp dụng cho f không âm, không phải mọi phép đổi thứ tự hàm có dấu.')]),
    t(b('View the partial sums of nonnegative Xₖ as an increasing sequence and use monotone convergence.', 'Coi tổng riêng của các Xₖ không âm là một dãy tăng rồi dùng hội tụ đơn điệu.'), f('Xₖ≥0 ⇒ E[ΣₖXₖ]=ΣₖE[Xₖ]', 'nonnegative measurable terms; signed case needs absolute integrability', 'các số hạng đo được không âm; trường hợp có dấu cần khả tích tuyệt đối'), [b('Let S_N=Σₖ₌₁ᴺXₖ. Then S_N↑ΣₖXₖ pointwise.', 'Đặt S_N=Σₖ₌₁ᴺXₖ. Khi đó S_N↑ΣₖXₖ theo từng điểm.'), b('By MCT, E[ΣₖXₖ]=lim_NE[S_N]=lim_NΣₖ₌₁ᴺE[Xₖ].', 'Theo MCT, E[ΣₖXₖ]=lim_NE[S_N]=lim_NΣₖ₌₁ᴺE[Xₖ].'), b('The stated sum is 7/3. For signed Xₖ, ΣₖE|Xₖ|<∞ is sufficient for exchanging expectation and summation.', 'Tổng đã cho bằng 7/3. Với Xₖ có dấu, điều kiện ΣₖE|Xₖ|<∞ đủ để đổi kỳ vọng và tổng.')]),
    t(b('Use the decaying exponential as a common envelope while θₙ changes the oscillation frequency.', 'Dùng hàm mũ suy giảm làm hàm bao chung khi θₙ thay đổi tần số dao động.'), f('|e^(−x)cos(θₙx)|≤e^(−x);  ∫₀∞e^(−x)dx=1', 'θₙ→0; x≥0; dominated convergence', 'θₙ→0; x≥0; hội tụ bị chặn'), [b('For every x, cos(θₙx)→1, so fₙ(x)→e^(−x).', 'Với mọi x, cos(θₙx)→1, nên fₙ(x)→e^(−x).'), b('Since |cos(θₙx)|≤1, the integrable function e^(−x) dominates |fₙ(x)| for all n.', 'Vì |cos(θₙx)|≤1, hàm khả tích e^(−x) chặn |fₙ(x)| với mọi n.'), b('DCT gives ∫fₙ→∫₀∞e^(−x)dx=1.', 'DCT cho ∫fₙ→∫₀∞e^(−x)dx=1.')]),
  ],
  33: [
    t(b('Use the probability weights as the inner-product measure, then compare the inner product with the product of norms.', 'Dùng các trọng số xác suất làm độ đo tích vô hướng, rồi so tích vô hướng với tích hai chuẩn.'), f('E|XY|≤(E[X²])¹ᐟ²(E[Y²])¹ᐟ²', 'X,Y∈L²; equality iff |X| and |Y| are proportional a.s.', 'X,Y∈L²; đẳng thức khi |X| và |Y| tỷ lệ với nhau h.k.n.'), [b('E[X²]=1/2+4/3=11/6, so ||X||₂=√(11/6); likewise E[Y²]=1/3+9/6=11/6.', 'E[X²]=1/2+4/3=11/6, nên ||X||₂=√(11/6); tương tự E[Y²]=1/3+9/6=11/6.'), b('Only the second atom contributes to |XY|: E|XY|=2/3.', 'Chỉ nguyên tử thứ hai đóng góp vào |XY|: E|XY|=2/3.'), b('The norm product is 11/6, strictly larger than 2/3; equality fails because the absolute-value vectors are not proportional.', 'Tích chuẩn bằng 11/6, lớn hơn nghiêm ngặt 2/3; không có đẳng thức vì vector trị tuyệt đối không tỷ lệ với nhau.')]),
    t(b('Normalize the two functions, apply Young pointwise, and integrate the resulting product bound.', 'Chuẩn hóa hai hàm, áp dụng Young theo từng điểm rồi tích phân bất đẳng thức tích.'), f('E|XY|≤(E|X|ᵖ)¹ᐟᵖ(E|Y|ᵖ′)¹ᐟᵖ', 'p=3, p′=3/2 are conjugate; finite norms', 'p=3, p′=3/2 liên hợp; các chuẩn hữu hạn'), [b('If either norm is zero, its variable is zero a.s. and the inequality is immediate.', 'Nếu một chuẩn bằng không thì biến tương ứng bằng không h.k.n. và bất đẳng thức hiển nhiên.'), b('Otherwise divide by the two norms so E|X|³=E|Y|^(3/2)=1.', 'Nếu không, chia cho hai chuẩn để E|X|³=E|Y|^(3/2)=1.'), b('Young gives |XY|≤|X|³/3+2|Y|^(3/2)/3; integrate and rescale. Equality requires the normalized powers to match a.s.', 'Young cho |XY|≤|X|³/3+2|Y|^(3/2)/3; tích phân rồi khôi phục chuẩn. Đẳng thức đòi hỏi các lũy thừa đã chuẩn hóa bằng nhau h.k.n.')]),
    t(b('Compare the value of the convex function at the mean with the average function value.', 'So sánh giá trị hàm lồi tại trung bình với trung bình các giá trị hàm.'), f('φ(E[X])≤E[φ(X)]', 'φ convex; expectations exist', 'φ lồi; các kỳ vọng tồn tại'), [b('The two equally likely values 0 and 2 give E[X]=1.', 'Hai giá trị 0 và 2 đồng xác suất cho E[X]=1.'), b('Thus φ(E[X])=1, while Eφ(X)=(0²+2²)/2=2.', 'Do đó φ(E[X])=1, còn Eφ(X)=(0²+2²)/2=2.'), b('The supporting line x²≥1+2(x−1) holds for every x and is strict except at x=1; averaging at nonconstant X makes Jensen strict.', 'Đường đỡ x²≥1+2(x−1) đúng với mọi x và nghiêm trừ x=1; lấy trung bình tại X không hằng làm Jensen nghiêm.')]),
    t(b('A finite first moment does not imply a finite second moment; inspect the power-series tail for each moment.', 'Moment bậc nhất hữu hạn không kéo theo moment bậc hai hữu hạn; xét đuôi chuỗi lũy thừa cho từng moment.'), f('P(X=k)=k⁻³/ζ(3);  E[X]=ζ(2)/ζ(3)<∞;  E[X²]=∞', 'k≥1; ζ(s)=Σk⁻ˢ', 'k≥1; ζ(s)=Σk⁻ˢ'), [b('Normalize with c=1/ζ(3), since Σk⁻³=ζ(3).', 'Chuẩn hóa bằng c=1/ζ(3), vì Σk⁻³=ζ(3).'), b('Then E[X]=cΣk⁻²=ζ(2)/ζ(3), finite.', 'Khi đó E[X]=cΣk⁻²=ζ(2)/ζ(3), hữu hạn.'), b('E[X²]=cΣk⁻¹ diverges. Treating X as L² would wrongly license variance-based arguments such as finite-variance Chebyshev calculations.', 'E[X²]=cΣk⁻¹ phân kỳ. Coi X thuộc L² sẽ cho phép sai các lập luận dựa trên phương sai hữu hạn như tính Chebyshev.')]),
    t(b('Interpolate between the Lᵖ norm and the probability-space L⁰ mass using Hölder.', 'Nội suy giữa chuẩn Lᵖ và khối lượng L⁰ của không gian xác suất bằng Hölder.'), f('E|X|ʳ≤(E|X|ᵖ)ʳᐟᵖ', '0<r<p; P(Ω)=1; Hölder exponents p/r and p/(p−r)', '0<r<p; P(Ω)=1; số mũ Hölder p/r và p/(p−r)'), [b('Write |X|ʳ=(|X|ᵖ)ʳᐟᵖ·1.', 'Viết |X|ʳ=(|X|ᵖ)ʳᐟᵖ·1.'), b('Use conjugate exponents p/r and p/(p−r) to bound the expectation by (E|X|ᵖ)ʳᐟᵖ·(E1)¹⁻ʳᐟᵖ.', 'Dùng hai số mũ liên hợp p/r và p/(p−r) để chặn kỳ vọng bởi (E|X|ᵖ)ʳᐟᵖ·(E1)¹⁻ʳᐟᵖ.'), b('Because P(Ω)=1, E1=1. On a general measure space, that factor is μ(Ω)¹⁻ʳᐟᵖ and cannot be discarded.', 'Vì P(Ω)=1, E1=1. Trên không gian độ đo tổng quát, thừa số là μ(Ω)¹⁻ʳᐟᵖ và không thể bỏ đi.')]),
  ],
  34: [
    t(b('Independence lets the four outcomes factor into a product law for the two Bernoulli variables.', 'Tính độc lập cho phép bốn kết quả tách thành luật tích của hai biến Bernoulli.'), f('E[g(X,Y)]=Σₓ,ᵧg(x,y)P_X(x)P_Y(y)', 'X,Y independent; bounded g here', 'X,Y độc lập; g bị chặn trong bài này'), [b('Exactly one success has probability 2·(1/2)(1/2)=1/2.', 'Đúng một lần thành công có xác suất 2·(1/2)(1/2)=1/2.'), b('E[XY]=E[X]E[Y]=1/4 by independence.', 'E[XY]=E[X]E[Y]=1/4 do tính độc lập.'), b('E[(X+Y)²]=E[X²]+2E[XY]+E[Y²]=1/2+1/2+1/2=3/2; direct summation over (0,0),(1,0),(0,1),(1,1) agrees.', 'E[(X+Y)²]=E[X²]+2E[XY]+E[Y²]=1/2+1/2+1/2=3/2; cộng trực tiếp trên bốn khả năng cũng cho kết quả này.')]),
    t(b('Bound the probability of any event occurring after index m, then let m grow.', 'Chặn xác suất có ít nhất một biến cố xảy ra sau chỉ số m, rồi cho m tăng.'), f('ΣₙP(Aₙ)<∞ ⇒ P(Aₙ i.o.)=0', 'no independence required; Aₙ i.o.=∩ₘ∪ₙ≥ₘAₙ', 'không cần độc lập; Aₙ i.o.=∩ₘ∪ₙ≥ₘAₙ'), [b('The event of infinitely many occurrences is ∩ₘ∪ₙ≥ₘAₙ.', 'Biến cố xảy ra vô hạn lần là ∩ₘ∪ₙ≥ₘAₙ.'), b('By the union bound, P(∪ₙ≥ₘAₙ)≤Σₙ≥ₘP(Aₙ), whose tail tends to zero.', 'Theo chặn hợp, P(∪ₙ≥ₘAₙ)≤Σₙ≥ₘP(Aₙ), và đuôi tổng tiến về không.'), b('Continuity from above gives probability zero for the intersection; independence was never used.', 'Tính liên tục từ trên cho xác suất giao bằng không; không cần dùng tính độc lập.')]),
    t(b('For independent events, bound the probability of avoiding every event in a finite tail.', 'Với các biến cố độc lập, chặn xác suất tránh mọi biến cố trong một đuôi hữu hạn.'), f('P(∩ₙ₌ₘᴺAₙᶜ)=∏ₙ₌ₘᴺ(1−P(Aₙ))≤exp(−Σₙ₌ₘᴺP(Aₙ))', 'independent Aₙ; ΣP(Aₙ)=∞', 'Aₙ độc lập; ΣP(Aₙ)=∞'), [b('Independence factors the probability that no Aₙ occurs from m through N into the product.', 'Tính độc lập phân tích xác suất không có Aₙ nào xảy ra từ m tới N thành tích.'), b('Apply 1−u≤e^(−u); since the probability sum diverges, this product tends to zero as N→∞.', 'Áp dụng 1−u≤e^(−u); vì tổng xác suất phân kỳ, tích tiến về không khi N→∞.'), b('Thus the probability of no event after m is zero. Taking the union over m shows occurrences happen infinitely often a.s.; independence is used in the product.', 'Vậy xác suất không có biến cố nào sau m bằng không. Lấy hợp theo m cho thấy biến cố xảy ra vô hạn lần h.k.n.; tính độc lập được dùng trong tích.')]),
    t(b('Repeated copies of one event have a divergent probability sum without repeated independent chances.', 'Lặp lại cùng một biến cố tạo tổng xác suất phân kỳ nhưng không tạo các cơ hội độc lập.'), f('Aₙ=A:  ΣP(Aₙ)=∞;  P(Aₙ i.o.)=P(A)=1/2', 'the events are perfectly dependent', 'các biến cố phụ thuộc hoàn toàn'), [b('Each term is 1/2, so the series ΣₙP(Aₙ) diverges.', 'Mỗi số hạng bằng 1/2, nên chuỗi ΣₙP(Aₙ) phân kỳ.'), b('Aₙ occurs infinitely often exactly when A occurs, so the probability is 1/2.', 'Aₙ xảy ra vô hạn lần đúng khi A xảy ra, nên xác suất là 1/2.'), b('Borel–Cantelli II cannot be applied: its independence assumption fails.', 'Không thể áp dụng Borel–Cantelli II: giả thiết độc lập bị vi phạm.')]),
    t(b('Control every rational error threshold with a summable tail and intersect the resulting probability-one events.', 'Khống chế mọi ngưỡng sai số hữu tỷ bằng đuôi tổng hữu hạn rồi giao các biến cố xác suất một.'), f('∀q∈ℚ₊, ΣₙP(|Xₙ−X|>q)<∞ ⇒ Xₙ→X a.s.', 'countably many positive rational thresholds', 'có đếm được ngưỡng hữu tỷ dương'), [b('For each positive rational q, Borel–Cantelli I says |Xₙ−X|>q occurs only finitely often a.s.', 'Với mỗi q hữu tỷ dương, Borel–Cantelli I cho biết |Xₙ−X|>q chỉ xảy ra hữu hạn lần h.k.n.'), b('Intersect these probability-one conclusions over the countable set ℚ₊; the intersection still has probability one.', 'Giao các kết luận xác suất một trên tập ℚ₊ đếm được vẫn có xác suất một.'), b('For any ε>0 choose rational q<ε; eventually |Xₙ−X|≤q<ε. Control only q=1 would not rule out infinitely many errors of size 1/2.', 'Với mọi ε>0, chọn q hữu tỷ q<ε; cuối cùng |Xₙ−X|≤q<ε. Chỉ khống chế q=1 không loại trừ sai số cỡ 1/2 xảy ra vô hạn lần.')]),
  ],
  35: [
    t(b('Conditional expectation on a finite partition is the average inside each block, repeated as a block-constant value.', 'Kỳ vọng có điều kiện trên phân hoạch hữu hạn là trung bình trong mỗi khối, lặp lại thành giá trị hằng trên khối.'), f('E[X|𝓖]|_B=E[X1_B]/P(B)', 'finite partition blocks B with P(B)>0', 'các khối B của phân hoạch hữu hạn có P(B)>0'), [b('On {1,2}, the average of 0 and 2 is 1; on {3,4}, the average of 4 and 6 is 5.', 'Trên {1,2}, trung bình của 0 và 2 là 1; trên {3,4}, trung bình của 4 và 6 là 5.'), b('Thus Z=(1,1,5,5). Each block has probability 1/2 and E[X1_B] equals E[Z1_B].', 'Vậy Z=(1,1,5,5). Mỗi khối có xác suất 1/2 và E[X1_B]=E[Z1_B].'), b('Adding the two block identities gives E[Z]=E[X]=3, verifying the identity on Ω as well.', 'Cộng hai đồng nhất thức khối cho E[Z]=E[X]=3, cũng xác minh đồng nhất thức trên Ω.')]),
    t(b('If two candidate conditional expectations differ, one signed difference is bounded away from zero on some measurable level set.', 'Nếu hai kỳ vọng có điều kiện ứng viên khác nhau, một hiệu có dấu bị chặn cách không trên một tập mức đo được.'), f('E[Z|𝓖]=E[W|𝓖]=E[X|𝓖] ⇒ Z=W a.s.', 'both integrable and satisfy the defining 𝓖-integrals', 'cả hai khả tích và thỏa các tích phân 𝓖 định nghĩa'), [b('Let D=Z−W. The defining identities imply E[1_A D]=0 for every A∈𝓖.', 'Đặt D=Z−W. Các đồng nhất thức định nghĩa suy ra E[1_A D]=0 với mọi A∈𝓖.'), b('For each k, A_k={D≥1/k}∈𝓖 gives 0=E[1_AkD]≥P(A_k)/k, so P(A_k)=0.', 'Với mỗi k, A_k={D≥1/k}∈𝓖 cho 0=E[1_AkD]≥P(A_k)/k, nên P(A_k)=0.'), b('The union over k shows P(D>0)=0; apply the same argument to −D to conclude D=0 a.s.', 'Hợp theo k cho P(D>0)=0; áp dụng tương tự với −D để kết luận D=0 h.k.n.')]),
    t(b('A two-block sigma-algebra forces the conditional expectation to be constant on A and Aᶜ.', 'Sigma-đại số hai khối buộc kỳ vọng có điều kiện là hằng trên A và Aᶜ.'), f('E[X|σ(A,Aᶜ)]=E[X|A]1_A+E[X|Aᶜ]1_Aᶜ', '0<P(A)<1 and X integrable', '0<P(A)<1 và X khả tích'), [b('Write Z=u1_A+v1_Aᶜ because Z is measurable with respect to the two-block sigma-algebra.', 'Viết Z=u1_A+v1_Aᶜ vì Z đo được theo sigma-đại số hai khối.'), b('Testing the defining identity on A gives uP(A)=E[X1_A], hence u=E[X1_A]/P(A); test Aᶜ for v.', 'Thử đồng nhất thức định nghĩa trên A cho uP(A)=E[X1_A], nên u=E[X1_A]/P(A); thử trên Aᶜ để tìm v.'), b('These two equalities imply the identity on every union of blocks, proving sufficiency.', 'Hai đẳng thức này suy ra đồng nhất thức trên mọi hợp khối, chứng minh tính đủ.')]),
    t(b('Conditional expectations are identified only up to null sets, so pointwise changes on a null set are allowed.', 'Kỳ vọng có điều kiện chỉ được xác định tới tập xác suất không, nên có thể đổi giá trị tại điểm không.'), f('Z=W a.s., not necessarily pointwise', 'conditional-expectation identities are tested in expectation', 'các đồng nhất thức kỳ vọng có điều kiện được kiểm tra qua tích phân'), [b('The trivial sigma-algebra contains only ∅ and Ω; Z and W both have integral zero because changing one point does not change a Lebesgue integral.', 'Sigma-đại số tầm thường chỉ chứa ∅ và Ω; Z và W đều có tích phân bằng không vì đổi tại một điểm không đổi tích phân Lebesgue.'), b('Since X=0, both candidate functions satisfy E[1_AZ]=E[1_AX]=0 and E[1_AW]=E[1_AX]=0 for A∈𝓖.', 'Vì X=0, cả hai hàm ứng viên đều thỏa E[1_AZ]=E[1_AX]=0 và E[1_AW]=E[1_AX]=0 với A∈𝓖.'), b('W(0)=1 while Z(0)=0, so they differ pointwise but agree almost surely.', 'W(0)=1 còn Z(0)=0, nên chúng khác nhau từng điểm nhưng bằng nhau hầu khắp nơi.')]),
    t(b('Approximate a bounded measurable test function by simple functions whose level sets lie in 𝓖.', 'Xấp xỉ hàm thử đo được bị chặn bằng hàm đơn có các tập mức thuộc 𝓖.'), f('E[HZ]=E[HX]', 'H bounded and 𝓖-measurable; defining identity holds for every A∈𝓖', 'H bị chặn và đo được theo 𝓖; đồng nhất thức định nghĩa đúng với mọi A∈𝓖'), [b('For a simple H=Σⱼcⱼ1_Aⱼ with Aⱼ∈𝓖, sum the given event identities after multiplying each by cⱼ.', 'Với H đơn giản H=Σⱼcⱼ1_Aⱼ, Aⱼ∈𝓖, cộng các đồng nhất thức biến cố sau khi nhân từng vế với cⱼ.'), b('Choose bounded simple H_m converging pointwise to bounded H; dominated convergence applies since X,Z∈L¹ and |H_m| is uniformly bounded.', 'Chọn H_m đơn giản bị chặn hội tụ điểm tới H; hội tụ bị chặn áp dụng vì X,Z∈L¹ và |H_m| bị chặn đều.'), b('An unbounded H may make HX or HZ nonintegrable, so extra integrability is needed before exchanging the limit.', 'H không bị chặn có thể làm HX hoặc HZ không khả tích, nên cần thêm điều kiện khả tích trước khi đổi giới hạn.')]),
  ],
  36: [
    t(b('Average within each partition block, then average the resulting block means over the trivial sigma-algebra.', 'Lấy trung bình trong từng khối phân hoạch, rồi lấy trung bình các giá trị khối theo sigma-đại số tầm thường.'), f('E[E[X|𝓖]|𝓗]=E[X|𝓗]', '𝓗⊆𝓖; X∈L¹', '𝓗⊆𝓖; X∈L¹'), [b('The 𝓖-block means are (1,1,5,5), as each block contains two equally likely states.', 'Trung bình khối 𝓖 là (1,1,5,5), vì mỗi khối chứa hai trạng thái đồng xác suất.'), b('Conditioning these values on trivial 𝓗 gives their overall mean 3.', 'Điều kiện các giá trị này theo 𝓗 tầm thường cho trung bình chung bằng 3.'), b('Directly E[X]=(0+2+4+6)/4=3, so both sides agree.', 'Tính trực tiếp E[X]=(0+2+4+6)/4=3, nên hai vế bằng nhau.')]),
    t(b('Test both sides on every event in the smaller sigma-algebra, then use uniqueness.', 'Thử hai vế trên mọi biến cố của sigma-đại số nhỏ hơn rồi dùng tính duy nhất.'), f('E[E[X|𝓖]|𝓗]=E[X|𝓗]', '𝓗⊆𝓖⊆𝓕 and X∈L¹', '𝓗⊆𝓖⊆𝓕 và X∈L¹'), [b('For every A∈𝓗, the definition for E[X|𝓖] gives E[1_AE[X|𝓖]]=E[1_AX], since A∈𝓖.', 'Với mọi A∈𝓗, định nghĩa của E[X|𝓖] cho E[1_AE[X|𝓖]]=E[1_AX], vì A∈𝓖.'), b('This is exactly the defining integral identity for E[X|𝓗] when the candidate is E[X|𝓖] conditioned again on 𝓗.', 'Đây chính là đồng nhất thức tích phân định nghĩa E[X|𝓗] khi ứng viên E[X|𝓖] được điều kiện lại theo 𝓗.'), b('Both candidates are 𝓗-measurable and integrable, so uniqueness yields equality almost surely.', 'Cả hai ứng viên 𝓗-đo được và khả tích, nên tính duy nhất cho đẳng thức hầu khắp nơi.')]),
    t(b('Show the residual is orthogonal to every square-integrable 𝓖-measurable test function.', 'Chứng minh phần dư trực giao với mọi hàm thử 𝓖-đo được bình phương khả tích.'), f('E[(X−Z)H]=0', 'Z=E[X|𝓖]; X∈L²; H∈L²(𝓖)', 'Z=E[X|𝓖]; X∈L²; H∈L²(𝓖)'), [b('For simple H=Σcⱼ1_Aⱼ with Aⱼ∈𝓖, each term E[1_Aⱼ(X−Z)] is zero by the defining identity.', 'Với H đơn giản H=Σcⱼ1_Aⱼ, Aⱼ∈𝓖, mỗi số hạng E[1_Aⱼ(X−Z)] bằng không theo đồng nhất thức định nghĩa.'), b('Approximate a general H∈L²(𝓖) by 𝓖-measurable simple H_m in L².', 'Xấp xỉ H∈L²(𝓖) tổng quát bằng hàm đơn 𝓖-đo được H_m trong L².'), b('Cauchy–Schwarz gives |E[(X−Z)(H−H_m)]|≤||X−Z||₂||H−H_m||₂→0, proving orthogonality.', 'Cauchy–Schwarz cho |E[(X−Z)(H−H_m)]|≤||X−Z||₂||H−H_m||₂→0, chứng minh trực giao.')]),
    t(b('Complete the square separately for the two block-constant fitted values a and b.', 'Hoàn thành bình phương riêng cho hai giá trị khớp hằng theo khối a và b.'), f('E[(X−H)²]=1+((a−1)²+(b−5)²)/2', 'four equiprobable states; H=(a,a,b,b)', 'bốn trạng thái đồng xác suất; H=(a,a,b,b)'), [b('On the first block, the average is 1 and its within-block variance is ((0−1)²+(2−1)²)/2=1.', 'Trên khối thứ nhất, trung bình là 1 và phương sai trong khối là ((0−1)²+(2−1)²)/2=1.'), b('The average squared error on that block is 1+(a−1)²; on the second it is 1+(b−5)².', 'Sai số bình phương trung bình trên khối đó là 1+(a−1)²; trên khối thứ hai là 1+(b−5)².'), b('Average the two blocks, each with probability 1/2: the total is 1+((a−1)²+(b−5)²)/2, minimized at a=1,b=5.', 'Lấy trung bình hai khối, mỗi khối xác suất 1/2: tổng là 1+((a−1)²+(b−5)²)/2, nhỏ nhất tại a=1,b=5.')]),
    t(b('Pull a bounded known multiplier through conditional expectation by testing both candidates on each G-event.', 'Đưa thừa số bị chặn đã biết ra khỏi kỳ vọng có điều kiện bằng cách thử hai ứng viên trên từng biến cố G.'), f('E[HX|𝓖]=H E[X|𝓖]', 'H bounded and 𝓖-measurable; X∈L¹', 'H bị chặn và đo được theo 𝓖; X∈L¹'), [b('For simple H, split H into 𝓖-measurable level sets and use the defining integral identity on each set.', 'Với H đơn giản, phân hoạch theo các tập mức 𝓖-đo được rồi dùng đồng nhất thức định nghĩa trên từng tập.'), b('Approximate bounded H by bounded 𝓖-measurable simple functions; boundedness keeps HX integrable.', 'Xấp xỉ H bị chặn bằng hàm đơn 𝓖-đo được bị chặn; tính bị chặn giữ HX khả tích.'), b('Pass to the limit in the tested integrals. Both sides are 𝓖-measurable and have the same integrals on all A∈𝓖, so uniqueness proves the identity.', 'Lấy giới hạn trong các tích phân đã thử. Hai vế 𝓖-đo được và có cùng tích phân trên mọi A∈𝓖, nên tính duy nhất chứng minh đồng nhất thức.')]),
  ],
  37: [
    t(b('Classify each sequence by checking pointwise behavior, tail probabilities, first moments, and distribution functions separately.', 'Phân loại từng dãy bằng cách xét riêng hành vi từng điểm, xác suất đuôi, moment bậc nhất và hàm phân phối.'), f('a.s. ⇒ P ⇒ distribution;  Lᵖ ⇒ P', 'implications hold on probability spaces; reverse implications need not', 'các kéo theo đúng trên không gian xác suất; chiều ngược có thể sai'), [b('For 1_[0,1/n](U), each fixed U>0 eventually leaves the interval: a.s. and probability convergence hold; its mean 1/n also gives L¹ convergence.', 'Với 1_[0,1/n](U), mỗi U>0 cố định cuối cùng rời khoảng: hội tụ h.k.n. và theo xác suất; kỳ vọng 1/n cũng cho hội tụ L¹.'), b('For independent 1_Aₙ with probability 1/n, P(Xₙ=1)=1/n→0, so probability and distribution convergence hold, but ΣP(Aₙ)=∞ and Borel–Cantelli II rules out a.s. convergence.', 'Với 1_Aₙ độc lập có xác suất 1/n, P(Xₙ=1)=1/n→0 nên hội tụ theo xác suất và phân phối, nhưng ΣP(Aₙ)=∞ và Borel–Cantelli II loại trừ hội tụ h.k.n.'), b('The constants 1/n converge a.s., in probability, in L¹, and in distribution to zero.', 'Các hằng số 1/n hội tụ h.k.n., theo xác suất, trong L¹ và theo phân phối về không.')]),
    t(b('Turn eventual pointwise closeness into a decreasing tail-event sequence and use continuity of probability.', 'Chuyển sự gần nhau cuối cùng từng điểm thành dãy biến cố đuôi giảm rồi dùng tính liên tục của xác suất.'), f('Xₙ→X a.s. ⇒ P(|Xₙ−X|>ε)→0', 'fixed ε>0; probability measure is finite', 'ε>0 cố định; độ đo xác suất hữu hạn'), [b('Let Bₙ={|Xₙ−X|>ε}. Almost surely only finitely many Bₙ occur.', 'Đặt Bₙ={|Xₙ−X|>ε}. Hầu chắc chắn chỉ hữu hạn Bₙ xảy ra.'), b('The tail unions C_m=∪ₙ≥ₘBₙ decrease to the event that Bₙ occurs infinitely often, which has probability zero.', 'Các hợp đuôi C_m=∪ₙ≥ₘBₙ giảm về biến cố Bₙ xảy ra vô hạn lần, có xác suất không.'), b('Continuity from above gives P(C_m)→0; since P(Bₘ)≤P(C_m), the desired probabilities tend to zero.', 'Tính liên tục từ trên cho P(C_m)→0; vì P(Bₘ)≤P(C_m), các xác suất cần tìm tiến về không.')]),
    t(b('Use rare independent events: their indicators are usually zero, but infinitely many ones still occur almost surely.', 'Dùng các biến cố độc lập hiếm: hàm chỉ thị thường bằng không nhưng vẫn có vô hạn số một hầu chắc chắn.'), f('P(Xₙ=1)=1/n→0;  ΣP(Aₙ)=∞ ⇒ Aₙ i.o. a.s.', 'Aₙ independent; Xₙ=1_Aₙ', 'Aₙ độc lập; Xₙ=1_Aₙ'), [b('For ε>0, P(|Xₙ|>ε)=1/n once ε<1, so Xₙ→P0.', 'Với ε>0, P(|Xₙ|>ε)=1/n khi ε<1, nên Xₙ→P0.'), b('The independent probabilities sum to infinity, so Borel–Cantelli II gives infinitely many Aₙ almost surely.', 'Tổng xác suất độc lập phân kỳ, nên Borel–Cantelli II cho Aₙ xảy ra vô hạn lần hầu chắc chắn.'), b('Thus the sequence cannot converge to zero a.s.; an indicator sequence can only converge pointwise to zero if its ones eventually stop.', 'Vì vậy dãy không thể hội tụ về không h.k.n.; dãy hàm chỉ thị chỉ hội tụ điểm về không nếu các giá trị một cuối cùng chấm dứt.')]),
    t(b('Apply Markov’s inequality to the nonnegative error raised to power p.', 'Áp dụng bất đẳng thức Markov cho sai số không âm lũy thừa p.'), f('P(|Xₙ−X|>ε)≤E|Xₙ−X|ᵖ/εᵖ', 'p>0; E|Xₙ−X|ᵖ finite', 'p>0; E|Xₙ−X|ᵖ hữu hạn'), [b('Set W=|Xₙ−X|ᵖ≥0 and threshold a=εᵖ.', 'Đặt W=|Xₙ−X|ᵖ≥0 và ngưỡng a=εᵖ.'), b('Markov gives P(W>a)≤E[W]/a, which is the claimed bound.', 'Markov cho P(W>a)≤E[W]/a, chính là chặn đã nêu.'), b('If the p-th moment of the error tends to zero, the bound tends to zero for every fixed ε, proving convergence in probability.', 'Nếu moment bậc p của sai số tiến về không, chặn tiến về không với mọi ε cố định, chứng minh hội tụ theo xác suất.')]),
    t(b('Two probability limits of the same sequence must agree except on a null set.', 'Hai giới hạn theo xác suất của cùng một dãy phải bằng nhau ngoài một tập không.'), f('P(|X−Y|>ε)≤P(|X−Xₙ|>ε/2)+P(|Xₙ−Y|>ε/2)', 'Xₙ→P X and Xₙ→P Y', 'Xₙ→P X và Xₙ→P Y'), [b('The triangle inequality implies that |X−Y|>ε forces at least one of |X−Xₙ| or |Xₙ−Y| to exceed ε/2.', 'Bất đẳng thức tam giác cho thấy |X−Y|>ε buộc ít nhất một trong |X−Xₙ|, |Xₙ−Y| vượt ε/2.'), b('Both probabilities on the right tend to zero, so P(|X−Y|>ε)=0.', 'Hai xác suất ở vế phải đều tiến về không, nên P(|X−Y|>ε)=0.'), b('Apply this for ε=1/k, k≥1; their countable union is {X≠Y}, hence X=Y a.s.', 'Áp dụng với ε=1/k, k≥1; hợp đếm được là {X≠Y}, nên X=Y h.k.n.')]),
  ],
  38: [
    t(b('Uniform integrability asks whether expected mass in the tails vanishes uniformly over the family.', 'Tính khả tích đều hỏi liệu khối lượng kỳ vọng ở đuôi có tiến về không đồng đều theo họ hay không.'), f('supₙE[|Xₙ|1{|Xₙ|>K}]→0', 'K→∞', 'K→∞'), [b('If |Xₙ|≤3, the tail term is zero for K≥3, so the bounded family is UI.', 'Nếu |Xₙ|≤3 thì số hạng đuôi bằng không khi K≥3, nên họ bị chặn là UI.'), b('For Xₙ=n1_(0,1/n), when n>K the tail expectation is n·(1/n)=1; for n≤K it is zero.', 'Với Xₙ=n1_(0,1/n), khi n>K thì kỳ vọng đuôi bằng n·(1/n)=1; khi n≤K thì bằng không.'), b('The supremum remains 1 for every K, so the spike family is not UI.', 'Supremum vẫn bằng 1 với mọi K, nên họ đỉnh nhọn không UI.')]),
    t(b('Split the absolute error into the event where it is small and the event where convergence in probability controls it.', 'Tách sai số tuyệt đối thành biến cố sai số nhỏ và biến cố được hội tụ theo xác suất khống chế.'), f('E|Uₙ−U|≤ε+2K·P(|Uₙ−U|>ε)', '|Uₙ|,|U|≤K and Uₙ→P U', '|Uₙ|,|U|≤K và Uₙ→P U'), [b('On {|Uₙ−U|≤ε}, the contribution to expectation is at most ε.', 'Trên {|Uₙ−U|≤ε}, phần đóng góp vào kỳ vọng nhiều nhất là ε.'), b('On the complement, |Uₙ−U|≤2K, so the contribution is at most 2K times its probability.', 'Trên phần bù, |Uₙ−U|≤2K, nên đóng góp nhiều nhất bằng 2K nhân xác suất của phần bù.'), b('For fixed ε the probability term tends to zero; then let ε↓0 to conclude L¹ convergence.', 'Với ε cố định, số hạng xác suất tiến về không; sau đó cho ε↓0 để kết luận hội tụ L¹.')]),
    t(b('The moving spike vanishes in probability while retaining all of its expected mass.', 'Đỉnh nhọn dịch chuyển biến mất theo xác suất nhưng giữ nguyên toàn bộ kỳ vọng.'), f('Xₙ=n1_(0,1/n):  Xₙ→P0;  E|Xₙ|=1;  UI fails', 'on (0,1) with Lebesgue probability', 'trên (0,1) với xác suất Lebesgue'), [b('For ε>0 and n>ε, P(Xₙ>ε)=1/n→0.', 'Với ε>0 và n>ε, P(Xₙ>ε)=1/n→0.'), b('Its L¹ norm is n·(1/n)=1 for every n, so it does not converge to zero in L¹.', 'Chuẩn L¹ là n·(1/n)=1 với mọi n, nên không hội tụ L¹ về không.'), b('For K fixed and n>K, E[Xₙ1{Xₙ>K}]=1; the tail expectation does not vanish uniformly, exactly violating UI.', 'Với K cố định và n>K, E[Xₙ1{Xₙ>K}]=1; kỳ vọng đuôi không tiến về không đồng đều, vi phạm đúng điều kiện UI.')]),
    t(b('Truncate each variable into a bounded core plus two tails, then control the two parts with probability convergence and UI.', 'Cắt cụt mỗi biến thành phần lõi bị chặn và hai đuôi, rồi khống chế các phần bằng hội tụ xác suất và UI.'), f('E|Xₙ−X|≤E|φ_K(Xₙ)−φ_K(X)|+E|Xₙ−φ_K(Xₙ)|+E|X−φ_K(X)|', 'Xₙ→P X and {Xₙ} UI; φ_K clips values to [−K,K]', 'Xₙ→P X và {Xₙ} UI; φ_K cắt giá trị vào [−K,K]'), [b('Clip values to [−K,K]. The bounded clipped variables still converge in probability, and the bounded-to-L¹ lemma makes the core expectation small as n grows.', 'Cắt giá trị vào [−K,K]. Các biến đã cắt vẫn hội tụ theo xác suất, và bổ đề bị chặn sang L¹ làm kỳ vọng phần lõi nhỏ khi n tăng.'), b('The difference |Xₙ−φ_K(Xₙ)| is at most |Xₙ|1{|Xₙ|>K}; UI makes its expected value uniformly small for large K.', 'Hiệu |Xₙ−φ_K(Xₙ)| không vượt |Xₙ|1{|Xₙ|>K}; UI làm kỳ vọng của nó nhỏ đồng đều khi K lớn.'), b('Convergence in probability implies X is integrable with controlled tails under the Vitali hypotheses; its truncation tail is small too. Let n grow, then K grow.', 'Theo các giả thiết Vitali, hội tụ xác suất suy ra X khả tích với đuôi được khống chế; đuôi cắt cụt của X cũng nhỏ. Cho n tăng rồi cho K tăng.')]),
    t(b('Use the p-th moment to bound the first-moment mass beyond threshold K.', 'Dùng moment bậc p để chặn khối lượng moment bậc nhất phía ngoài ngưỡng K.'), f('E[|Xₙ|1{|Xₙ|>K}]≤E|Xₙ|ᵖ/K^(p−1)', 'p>1 and supₙE|Xₙ|ᵖ≤C', 'p>1 và supₙE|Xₙ|ᵖ≤C'), [b('On {|Xₙ|>K}, |Xₙ|≤|Xₙ|ᵖ/K^(p−1).', 'Trên {|Xₙ|>K}, |Xₙ|≤|Xₙ|ᵖ/K^(p−1).'), b('Taking expectations bounds every tail by C/K^(p−1).', 'Lấy kỳ vọng chặn mọi đuôi bởi C/K^(p−1).'), b('Since p−1>0, the bound tends to zero as K→∞ uniformly in n, proving UI.', 'Vì p−1>0, chặn tiến về không khi K→∞ đồng đều theo n, chứng minh UI.')]),
  ],
  39: [
    t(b('Center the sample mean, compute its variance under independence, and apply Chebyshev at ε.', 'Trừ trung bình mẫu, tính phương sai nhờ độc lập rồi áp dụng Chebyshev tại ε.'), f('P(|X̄ₙ−μ|≥ε)≤σ²/(nε²)', 'iid; E[X]=μ; Var(X)=σ²<∞', 'iid; E[X]=μ; Var(X)=σ²<∞'), [b('Independence gives Var(X̄ₙ)=Var(ΣXᵢ)/n²=nσ²/n²=σ²/n.', 'Tính độc lập cho Var(X̄ₙ)=Var(ΣXᵢ)/n²=nσ²/n²=σ²/n.'), b('Chebyshev bounds the deviation probability by Var(X̄ₙ)/ε²=σ²/(nε²).', 'Chebyshev chặn xác suất lệch bởi Var(X̄ₙ)/ε²=σ²/(nε²).'), b('The bound tends to zero, proving X̄ₙ→Pμ. This argument does not by itself establish almost-sure convergence.', 'Chặn tiến về không, chứng minh X̄ₙ→Pμ. Lập luận này tự nó chưa chứng minh hội tụ hầu chắc chắn.')]),
    t(b('For a Bernoulli sample, count successes and distinguish the variance bound from the stronger almost-sure theorem.', 'Với mẫu Bernoulli, đếm số lần thành công và phân biệt chặn phương sai với định lý hầu chắc chắn mạnh hơn.'), f('E[X̄ₙ]=p; Var(X̄ₙ)=p(1−p)/n;  X̄ₙ→a.s.p', 'iid Bernoulli(p); the last conclusion is SLLN', 'Bernoulli(p) iid; kết luận cuối là SLLN'), [b('Linearity gives E[X̄ₙ]=p and independence gives Var(X̄ₙ)=p(1−p)/n.', 'Tính tuyến tính cho E[X̄ₙ]=p và độc lập cho Var(X̄ₙ)=p(1−p)/n.'), b('Chebyshev yields P(|X̄ₙ−p|≥ε)≤p(1−p)/(nε²), which proves convergence in probability.', 'Chebyshev cho P(|X̄ₙ−p|≥ε)≤p(1−p)/(nε²), chứng minh hội tụ theo xác suất.'), b('The strong law says X̄ₙ→p almost surely; that is the a.s. result and is stronger than the Chebyshev conclusion.', 'Luật mạnh nói X̄ₙ→p hầu chắc chắn; đó là kết quả h.k.n. và mạnh hơn kết luận Chebyshev.')]),
    t(b('Apply Borel–Cantelli separately at every rational accuracy so that all tolerances hold on one probability-one event.', 'Áp dụng Borel–Cantelli riêng cho mọi độ chính xác hữu tỷ để mọi ngưỡng cùng đúng trên một biến cố xác suất một.'), f('∀q∈ℚ₊, ΣₙP(|Yₙ−y|>q)<∞ ⇒ Yₙ→y a.s.', 'countably many summable thresholds', 'có đếm được ngưỡng có tổng hữu hạn'), [b('For each rational q>0, Borel–Cantelli I makes |Yₙ−y|>q occur only finitely often a.s.', 'Với mỗi q hữu tỷ dương, Borel–Cantelli I cho |Yₙ−y|>q chỉ xảy ra hữu hạn lần h.k.n.'), b('Intersect over the countable rational set; outside one null set every such threshold is eventually respected.', 'Giao trên tập hữu tỷ đếm được; ngoài một tập không, mọi ngưỡng đều được thỏa từ một lúc nào đó.'), b('For arbitrary ε>0 choose q<ε. A summable bound only at q=1 still allows repeated deviations of size 1/2.', 'Với ε>0 tùy ý, chọn q<ε. Chặn tổng hữu hạn chỉ tại q=1 vẫn cho phép sai lệch cỡ 1/2 lặp lại.')]),
    t(b('Perfect dependence makes every sample average equal the same nonvanishing random variable.', 'Phụ thuộc hoàn toàn khiến mọi trung bình mẫu bằng cùng một biến ngẫu nhiên không triệt tiêu.'), f('Xᵢ=Z ⇒ X̄ₙ=Z;  Var(X̄ₙ)=Var(Z)', 'Var(Z)>0; observations are not independent', 'Var(Z)>0; các quan sát không độc lập'), [b('Since every observation equals Z, their average is Z for every n.', 'Vì mọi quan sát đều bằng Z, trung bình luôn bằng Z với mọi n.'), b('Thus P(|X̄ₙ−μ|>ε)=P(|Z−μ|>ε), which need not tend to zero.', 'Do đó P(|X̄ₙ−μ|>ε)=P(|Z−μ|>ε), không nhất thiết tiến về không.'), b('The iid variance calculation fails because covariance terms do not vanish: Var(ΣXᵢ)=n²Var(Z), not nVar(Z).', 'Phép tính phương sai iid thất bại vì hiệp phương sai không triệt tiêu: Var(ΣXᵢ)=n²Var(Z), không phải nVar(Z).')]),
    t(b('Separate the theorem proved from the stronger law being cited, and check bounded observations meet its moment assumption.', 'Tách định lý đã chứng minh khỏi luật mạnh hơn được viện dẫn, rồi kiểm tra quan sát bị chặn thỏa giả thiết moment.'), f('WLLN: X̄ₙ→Pμ; SLLN: X̄ₙ→a.s.μ', 'iid and E|X₁|<∞ for the SLLN; boundedness implies this', 'iid và E|X₁|<∞ cho SLLN; tính bị chặn suy ra điều này'), [b('Because −M≤Xᵢ≤M, the mean exists and Var(Xᵢ)≤M², so the finite-variance WLLN applies.', 'Vì −M≤Xᵢ≤M, trung bình tồn tại và Var(Xᵢ)≤M², nên WLLN phương sai hữu hạn áp dụng.'), b('The proved result is convergence in probability from Chebyshev and independence.', 'Kết quả đã chứng minh là hội tụ theo xác suất từ Chebyshev và tính độc lập.'), b('The SLLN is the sourced theorem: iid plus E|X₁|<∞ yields a.s. convergence. Boundedness supplies that finite first moment.', 'SLLN là định lý được viện dẫn: iid cùng E|X₁|<∞ suy ra hội tụ h.k.n. Tính bị chặn cho moment bậc nhất hữu hạn.')]),
  ],
  40: [
    t(b('Average the complex exponential over the two Rademacher outcomes.', 'Lấy trung bình hàm mũ phức trên hai kết quả Rademacher.'), f('φ_X(t)=E[e^(itX)]=cos(t)', 'P(X=−1)=P(X=1)=1/2', 'P(X=−1)=P(X=1)=1/2'), [b('Expand: φ_X(t)=(e^(it)+e^(−it))/2=cos t.', 'Khai triển: φ_X(t)=(e^(it)+e^(−it))/2=cos t.'), b('At t=0, φ_X(0)=cos 0=1, as any characteristic function must.', 'Tại t=0, φ_X(0)=cos 0=1, đúng như mọi hàm đặc trưng.'), b('Cosine is continuous at zero, so the required continuity condition holds.', 'Hàm cosine liên tục tại không, nên điều kiện liên tục cần thiết được thỏa.')]),
    t(b('Treat Yₙ as a perturbation converging to a constant; Slutsky does not require independence.', 'Coi Yₙ là nhiễu tiến tới hằng số; định lý Slutsky không cần tính độc lập.'), f('Xₙ⇒X, Yₙ→P c ⇒ Xₙ+Yₙ⇒X+c; XₙYₙ⇒cX', 'c is constant; continuous operations', 'c là hằng số; các phép toán liên tục'), [b('Here Xₙ⇒N(0,4), Yₙ→P−1, so Xₙ+Yₙ⇒N(−1,4).', 'Ở đây Xₙ⇒N(0,4), Yₙ→P−1, nên Xₙ+Yₙ⇒N(−1,4).'), b('Since −1 is nonzero, 3Xₙ/Yₙ⇒−3X where X∼N(0,4), giving N(0,36).', 'Vì −1 khác không, 3Xₙ/Yₙ⇒−3X với X∼N(0,4), cho N(0,36).'), b('The probability limit is constant; Slutsky handles arbitrary dependence between Xₙ and Yₙ.', 'Giới hạn theo xác suất là hằng số; Slutsky xử lý được mọi phụ thuộc giữa Xₙ và Yₙ.')]),
    t(b('Rare values escape to infinity while their probability vanishes, preserving a nonzero mean.', 'Giá trị hiếm thoát ra vô hạn khi xác suất của chúng biến mất, nhưng vẫn giữ kỳ vọng khác không.'), f('P(Xₙ=n)=1/n;  Xₙ⇒0;  E[Xₙ]=1', 'n→∞', 'n→∞'), [b('For any bounded continuous g, E[g(Xₙ)]=(1−1/n)g(0)+(1/n)g(n); the rare term vanishes because g is bounded.', 'Với g liên tục bị chặn, E[g(Xₙ)]=(1−1/n)g(0)+(1/n)g(n); số hạng hiếm biến mất vì g bị chặn.'), b('Thus Xₙ converges in distribution to zero.', 'Vì vậy Xₙ hội tụ phân phối về không.'), b('The mean is n·(1/n)=1 for every n. The missing control is uniform integrability, which would prevent mean mass escaping.', 'Kỳ vọng là n·(1/n)=1 với mọi n. Điều kiện thiếu là khả tích đều, vốn ngăn khối lượng kỳ vọng thoát đi.')]),
    t(b('For a monotone transform, express the transformed event by applying the inverse map to the threshold.', 'Với phép biến đổi đơn điệu, biểu diễn biến cố sau biến đổi bằng cách áp dụng hàm ngược vào ngưỡng.'), f('F_{g(Xₙ)}(y)=F_{Xₙ}(g⁻¹(y))', 'g continuous strictly increasing; convergence points are continuity points of F_X∘g⁻¹', 'g liên tục tăng nghiêm ngặt; các điểm hội tụ là điểm liên tục của F_X∘g⁻¹'), [b('For strictly increasing g, {g(Xₙ)≤y}={Xₙ≤g⁻¹(y)}.', 'Với g tăng nghiêm ngặt, {g(Xₙ)≤y}={Xₙ≤g⁻¹(y)}.'), b('At thresholds where the limiting transformed CDF is continuous, weak convergence gives Fₙ(g⁻¹(y))→F_X(g⁻¹(y)).', 'Tại ngưỡng mà CDF biến đổi giới hạn liên tục, hội tụ yếu cho Fₙ(g⁻¹(y))→F_X(g⁻¹(y)).'), b('Continuity of g ensures g⁻¹(y) tracks the threshold without jumps; discontinuous transforms need a separate continuity-set argument.', 'Tính liên tục của g bảo đảm g⁻¹(y) theo dõi ngưỡng không nhảy; phép biến đổi gián đoạn cần lập luận tập liên tục riêng.')]),
    t(b('Weak convergence controls bounded continuous probes, while equality of means needs tail control.', 'Hội tụ yếu khống chế các hàm thử liên tục bị chặn, còn đẳng thức moment cần khống chế đuôi.'), f('Xₙ⇒X plus UI of {Xₙ} ⇒ E[Xₙ]→E[X]', 'first moments are integrable; UI supplies tail control', 'moment bậc nhất khả tích; UI khống chế đuôi'), [b('Weak convergence alone does not force m=E[X]; the rare-spike example has limit 0 and means 1.', 'Chỉ hội tụ yếu không buộc m=E[X]; ví dụ đỉnh hiếm có giới hạn 0 và kỳ vọng 1.'), b('Uniform integrability lets one truncate x to a bounded continuous approximation, pass limits there, and then remove the truncation with uniformly small tails.', 'Tính khả tích đều cho phép cắt x thành xấp xỉ liên tục bị chặn, lấy giới hạn ở đó rồi bỏ cắt với đuôi nhỏ đồng đều.'), b('If |Xₙ|≤K, the family is UI, so the weak limit has matching expectations under the stated integrability.', 'Nếu |Xₙ|≤K thì họ UI, nên giới hạn yếu có kỳ vọng trùng với giới hạn kỳ vọng theo điều kiện khả tích đã nêu.')]),
  ],
  41: [
    t(b('Use the binomial mean and standard deviation, then standardize the sample proportion before applying the CLT.', 'Dùng trung bình và độ lệch chuẩn nhị thức, rồi chuẩn hóa tỷ lệ mẫu trước khi áp dụng CLT.'), f('E[X̄ₙ]=p;  SD(X̄ₙ)=√(p(1−p)/n)', 'iid Bernoulli(p); CLT approximation for large n', 'Bernoulli(p) iid; xấp xỉ CLT khi n lớn'), [b('For p=1/4 and n=400, E[X̄ₙ]=0.25 and SD=√(0.1875/400)=√(3/6400)≈0.02165.', 'Với p=1/4 và n=400, E[X̄ₙ]=0.25 và SD=√(0.1875/400)=√(3/6400)≈0.02165.'), b('Standardize 0.30: z=(0.30−0.25)/0.02165≈2.31, so P(X̄ₙ≥0.30)≈1−Φ(2.31).', 'Chuẩn hóa 0.30: z=(0.30−0.25)/0.02165≈2.31, nên P(X̄ₙ≥0.30)≈1−Φ(2.31).'), b('For the count S≥120, a continuity correction uses 119.5, giving z=(119.5−100)/√75≈2.25.', 'Với biến đếm S≥120, hiệu chỉnh liên tục dùng 119.5, cho z=(119.5−100)/√75≈2.25.')]),
    t(b('Expand the characteristic function to second order and control the remainder before taking expectation.', 'Khai triển hàm đặc trưng tới bậc hai rồi khống chế phần dư trước khi lấy kỳ vọng.'), f('φ_Z(u)=1−u²/2+o(u²)', 'E[Z]=0 and E[Z²]=1', 'E[Z]=0 và E[Z²]=1'), [b('Subtract 1+iuZ inside the expectation; its expectation is zero because E[Z]=0.', 'Trừ 1+iuZ bên trong kỳ vọng; kỳ vọng của nó bằng không vì E[Z]=0.'), b('For bounded |Z|≤M, Taylor gives e^(iuZ)=1+iuZ−u²Z²/2+o(u²Z²) uniformly.', 'Với |Z|≤M, Taylor cho e^(iuZ)=1+iuZ−u²Z²/2+o(u²Z²) đồng đều.'), b('Truncate to |Z|≤M, then use E[Z²1{|Z|>M}]→0 to control the tail and let M grow. This yields −u²E[Z²]/2=−u²/2 plus o(u²).', 'Cắt cụt tại |Z|≤M, rồi dùng E[Z²1{|Z|>M}]→0 để khống chế đuôi và cho M tăng. Ta được −u²E[Z²]/2=−u²/2 cộng o(u²).')]),
    t(b('Evaluate the one-step characteristic function at t/√n and raise it to the n-th power.', 'Tính hàm đặc trưng một bước tại t/√n rồi nâng lên lũy thừa n.'), f('[φ_Z(t/√n)]ⁿ→e^(−t²/2)', 'fixed t; iid centered variance-one summands', 't cố định; các số hạng iid, tâm hóa, phương sai một'), [b('Substitute u=t/√n into φ_Z(u)=1−u²/2+o(u²).', 'Thay u=t/√n vào φ_Z(u)=1−u²/2+o(u²).'), b('The bracket becomes 1−t²/(2n)+o(1/n).', 'Biểu thức trong ngoặc trở thành 1−t²/(2n)+o(1/n).'), b('Use (1+aₙ/n)ⁿ→eᵃ when aₙ→a; the limit is e^(−t²/2).', 'Dùng (1+aₙ/n)ⁿ→eᵃ khi aₙ→a; giới hạn là e^(−t²/2).')]),
    t(b('Check the finite-variance hypothesis before using the classical square-root-n normalization.', 'Kiểm tra giả thiết phương sai hữu hạn trước khi dùng chuẩn hóa căn bậc hai n cổ điển.'), f('Classical iid CLT requires E[X]=μ and 0<Var(X)=σ²<∞', 'symmetric tail P(|X|>t)=t^(−3/2), t≥1', 'đuôi đối xứng P(|X|>t)=t^(−3/2), t≥1'), [b('The symmetric tail gives E|X|=∫₀∞P(|X|>t)dt finite because the tail exponent exceeds 1.', 'Đuôi đối xứng cho E|X|=∫₀∞P(|X|>t)dt hữu hạn vì số mũ đuôi lớn hơn 1.'), b('The second moment uses 2∫₀∞tP(|X|>t)dt, whose tail behaves like t^(−1/2) and diverges.', 'Moment bậc hai dùng 2∫₀∞tP(|X|>t)dt, có đuôi dạng t^(−1/2) và phân kỳ.'), b('Thus the finite-variance CLT does not apply and σ/√n is unavailable; a different stable-law normalization may be needed.', 'Vì vậy CLT phương sai hữu hạn không áp dụng và không dùng được σ/√n; có thể cần chuẩn hóa theo luật ổn định khác.')]),
    t(b('Use the Bernoulli variance in the CLT and invert the approximate normal pivot for an interval.', 'Dùng phương sai Bernoulli trong CLT rồi đảo pivot chuẩn xấp xỉ để lập khoảng.'), f('p̂±1.96√(p̂(1−p̂)/n)', 'iid Bernoulli(p), p∈(0,1), and large n', 'Bernoulli(p) iid, p∈(0,1), và n lớn'), [b('The sample mean has asymptotic variance p(1−p)/n, so its standard error is √(p(1−p)/n).', 'Trung bình mẫu có phương sai tiệm cận p(1−p)/n, nên sai số chuẩn là √(p(1−p)/n).'), b('Replace unknown p with p̂ to form the nominal 95% Wald interval p̂±1.96√(p̂(1−p̂)/n).', 'Thay p chưa biết bằng p̂ để lập khoảng Wald 95% danh định p̂±1.96√(p̂(1−p̂)/n).'), b('Near 0 or 1 the normal approximation is skewed and p̂ can be on the boundary, so nominal coverage may be poor.', 'Gần 0 hoặc 1, xấp xỉ chuẩn bị lệch và p̂ có thể nằm biên, nên độ phủ danh định có thể kém.')]),
  ],
  42: [
    t(b('Solve the stationarity equations for a two-state chain and separately update the initial row distribution.', 'Giải phương trình dừng cho chuỗi hai trạng thái rồi cập nhật riêng phân phối hàng ban đầu.'), f('πP=π;  π₁+π₂=1', 'π is a probability row vector', 'π là vector xác suất dạng hàng'), [b('Write π₁=0.8π₁+0.3π₂; using π₂=1−π₁ gives 0.2π₁=0.3π₂.', 'Viết π₁=0.8π₁+0.3π₂; dùng π₂=1−π₁ được 0.2π₁=0.3π₂.'), b('Thus π=(0.6,0.4), which is nonnegative, sums to one, and direct multiplication verifies πP=π.', 'Vậy π=(0.6,0.4), không âm, tổng bằng một và nhân trực tiếp xác minh πP=π.'), b('From μ=(1,0), one step gives μP=(0.8,0.2); stationarity describes a different initial law.', 'Từ μ=(1,0), một bước cho μP=(0.8,0.2); tính dừng mô tả luật ban đầu khác.')]),
    t(b('Decompose each transition row into the same common part plus a residual stochastic row.', 'Phân rã mỗi hàng chuyển tiếp thành cùng một phần chung cộng với hàng dư xác suất.'), f('P(i,·)=εν+(1−ε)Q(i,·) ⇒ ||μP−ηP||TV≤(1−ε)||μ−η||TV', '0≤ε≤1; ν,Q are probability laws/kernel', '0≤ε≤1; ν,Q là luật xác suất/nhân Markov'), [b('The common εν term cancels in μP−ηP because both μ and η have total mass one.', 'Số hạng εν chung triệt tiêu trong μP−ηP vì μ và η đều có tổng khối lượng một.'), b('The difference is (1−ε)(μQ−ηQ); Markov kernels contract total variation.', 'Hiệu còn (1−ε)(μQ−ηQ); nhân Markov co chuẩn biến phân toàn phần.'), b('Taking norms gives the claimed factor 1−ε.', 'Lấy chuẩn cho hệ số 1−ε như yêu cầu.')]),
    t(b('Subtract the proposed common mass from each transition row and renormalize the residual.', 'Trừ khối lượng chung đề xuất khỏi từng hàng chuyển tiếp rồi chuẩn hóa phần dư.'), f('Q(i,·)=(P(i,·)−εν)/(1−ε)', 'P(i,·)≥εν componentwise; 0<ε<1', 'P(i,·)≥εν theo từng thành phần; 0<ε<1'), [b('For ν=(0.6,0.4), ε=0.5, row one leaves (0.8,0.2)−(0.3,0.2)=(0.5,0).', 'Với ν=(0.6,0.4), ε=0.5, hàng một còn (0.8,0.2)−(0.3,0.2)=(0.5,0).'), b('Divide by 0.5 to get Q row one=(1,0); row two leaves (0,0.5), so Q row two=(0,1).', 'Chia cho 0.5 được hàng Q thứ nhất=(1,0); hàng hai còn (0,0.5), nên hàng Q thứ hai=(0,1).'), b('Both rows are nonnegative and sum to one, confirming a valid stochastic kernel and the minorization.', 'Cả hai hàng không âm và tổng bằng một, xác nhận nhân xác suất hợp lệ và điều kiện minorization.')]),
    t(b('An invariant law can exist even when the chain cycles forever instead of converging from a point mass.', 'Luật bất biến có thể tồn tại dù chuỗi cứ luân phiên mãi và không hội tụ từ khối lượng tại một điểm.'), f('P=[[0,1],[1,0]];  π=(1/2,1/2);  μ₀Pⁿ alternates', 'deterministic two-cycle; no ε>0 common minorization', 'chu kỳ hai xác định; không có minorization chung với ε>0'), [b('Direct multiplication gives πP=(1/2,1/2), so π is invariant.', 'Nhân trực tiếp cho πP=(1/2,1/2), nên π bất biến.'), b('Starting at state 1 gives μ₀=(1,0), then (0,1), then (1,0), and so on.', 'Bắt đầu ở trạng thái 1 cho μ₀=(1,0), rồi (0,1), rồi (1,0), cứ thế.'), b('The rows have disjoint support, so they cannot both dominate ε times one probability vector for positive ε; the minorization condition fails.', 'Các hàng có giá đỡ rời nhau, nên không thể cùng trội ε lần một vector xác suất khi ε>0; điều kiện minorization thất bại.')]),
    t(b('Iterate the one-step contraction while π remains fixed under P.', 'Lặp chặn co một bước trong khi π bất biến qua P.'), f('||μPⁿ−π||TV≤(1−ε)ⁿ||μ−π||TV', 'minorization with ε=0.2 and π invariant', 'minorization với ε=0.2 và π bất biến'), [b('At n steps the bound is 0.4·0.8ⁿ.', 'Sau n bước, chặn là 0.4·0.8ⁿ.'), b('For n=16 it is about 0.01126; for n=17 it is about 0.00901.', 'Với n=16 chặn xấp xỉ 0.01126; với n=17 xấp xỉ 0.00901.'), b('The smallest integer n making the bound below .01 is 17.', 'Số nguyên n nhỏ nhất làm chặn nhỏ hơn .01 là 17.')]),
  ],
  43: [
    t(b('Check each martingale step by conditioning the next fair increment on the current information.', 'Kiểm tra từng bước martingale bằng cách lấy kỳ vọng có điều kiện của bước tăng công bằng tiếp theo theo thông tin hiện tại.'), f('E[Mₖ|𝓕ₖ₋₁]=Mₖ₋₁', 'adapted and integrable process; stated conditional fair increments', 'quá trình thích nghi và khả tích; các bước tăng công bằng có điều kiện như đã nêu'), [b('At time 0, E[M₁|𝓕₀]=(−1+1)/2=0=M₀.', 'Tại thời điểm 0, E[M₁|𝓕₀]=(−1+1)/2=0=M₀.'), b('Given 𝓕₁, the next increment is conditionally ±1 with equal probabilities, so its conditional mean is zero.', 'Cho trước 𝓕₁, bước tăng tiếp theo có điều kiện là ±1 với xác suất bằng nhau, nên trung bình có điều kiện bằng không.'), b('Therefore E[M₂|𝓕₁]=M₁+E[ΔM₂|𝓕₁]=M₁.', 'Do đó E[M₂|𝓕₁]=M₁+E[ΔM₂|𝓕₁]=M₁.')]),
    t(b('Write the stopped value as the initial value plus increments activated only while stopping has not yet occurred.', 'Viết giá trị dừng thành giá trị đầu cộng các bước tăng chỉ được kích hoạt khi chưa dừng.'), f('M_τ=M₀+Σₖ₌₁ᴺ1{τ≥k}ΔMₖ;  E[M_τ]=E[M₀]', 'martingale; stopping time τ≤N bounded', 'martingale; thời điểm dừng τ≤N bị chặn'), [b('The pathwise sum includes increment k exactly when τ≥k.', 'Tổng theo từng đường đi gồm bước tăng k đúng khi τ≥k.'), b('Because τ is a stopping time, {τ≥k}={τ>k−1}∈𝓕ₖ₋₁, so it is known before ΔMₖ.', 'Vì τ là thời điểm dừng, {τ≥k}={τ>k−1}∈𝓕ₖ₋₁, nên được biết trước ΔMₖ.'), b('Each expectation E[1{τ≥k}ΔMₖ] is zero by the martingale property; finite summation gives E[M_τ]=E[M₀].', 'Mỗi kỳ vọng E[1{τ≥k}ΔMₖ] bằng không theo tính chất martingale; cộng hữu hạn cho E[M_τ]=E[M₀].')]),
    t(b('Condition the later martingale increment on the information just before it occurs.', 'Lấy kỳ vọng có điều kiện của bước tăng martingale sau theo thông tin ngay trước khi nó xảy ra.'), f('E[ΔMⱼΔMₖ]=0', 'j<k; square-integrable martingale', 'j<k; martingale bình phương khả tích'), [b('For j<k, ΔMⱼ is 𝓕ₖ₋₁-measurable.', 'Với j<k, ΔMⱼ là 𝓕ₖ₋₁-đo được.'), b('Take conditional expectation: E[ΔMⱼΔMₖ]=E[ΔMⱼE(ΔMₖ|𝓕ₖ₋₁)].', 'Lấy kỳ vọng có điều kiện: E[ΔMⱼΔMₖ]=E[ΔMⱼE(ΔMₖ|𝓕ₖ₋₁)].'), b('The inner conditional mean is zero, so the cross expectation vanishes; square integrability ensures the product is integrable.', 'Trung bình có điều kiện bên trong bằng không nên tích kỳ vọng triệt tiêu; bình phương khả tích bảo đảm tích khả tích.')]),
    t(b('The hitting time is finite almost surely, but the stopped payoff is not an integrable-preserving bounded stop.', 'Thời điểm chạm là hữu hạn hầu chắc chắn, nhưng khoản trả dừng không bảo toàn kỳ vọng như thời điểm dừng bị chặn.'), f('τ=inf{n:Mₙ=1};  M_τ=1 a.s.;  E[M_τ]=1≠0', 'simple symmetric random walk; τ is unbounded', 'bước đi ngẫu nhiên đối xứng đơn giản; τ không bị chặn'), [b('A one-dimensional simple symmetric random walk hits +1 almost surely, so τ<∞ a.s.', 'Bước đi ngẫu nhiên đối xứng đơn giản một chiều chạm +1 hầu chắc chắn, nên τ<∞ h.k.n.'), b('At the hitting time, M_τ=1 on every path, giving E[M_τ]=1 while E[M₀]=0.', 'Tại thời điểm chạm, M_τ=1 trên mọi đường đi, cho E[M_τ]=1 trong khi E[M₀]=0.'), b('There is no deterministic N with τ≤N; boundedness in the optional-stopping argument fails, and almost-sure finiteness alone is insufficient.', 'Không có N xác định nào sao cho τ≤N; tính bị chặn trong lập luận dừng tùy chọn bị vi phạm, và chỉ hữu hạn h.k.n. là chưa đủ.')]),
    t(b('Verify the stopped-sum identity pathwise, then check that each activation indicator is predictable.', 'Xác minh đẳng thức tổng dừng theo từng đường đi rồi kiểm tra mỗi hàm chỉ thị kích hoạt đều biết trước.'), f('M_τ=M₀+Σₖ₌₁ᴺ1{τ≥k}ΔMₖ', 'τ is a stopping time bounded by N', 'τ là thời điểm dừng bị chặn bởi N'), [b('If τ=r on a path, the indicators equal one for k≤r and zero for k>r, so the sum telescopes to M_r−M₀.', 'Nếu τ=r trên một đường đi, các hàm chỉ thị bằng một khi k≤r và bằng không khi k>r, nên tổng rút gọn thành M_r−M₀.'), b('The stopping-time condition gives {τ≥k}∈𝓕ₖ₋₁, making the indicator independent of the future increment in the conditional-expectation calculation.', 'Điều kiện thời điểm dừng cho {τ≥k}∈𝓕ₖ₋₁, khiến hàm chỉ thị không phụ thuộc bước tăng tương lai trong phép tính kỳ vọng có điều kiện.'), b('An indicator chosen using ΔMₖ is not known at time k−1; E[indicator·ΔMₖ] need not be zero, so the martingale proof breaks.', 'Hàm chỉ thị chọn dựa vào ΔMₖ chưa được biết tại thời điểm k−1; E[hàm chỉ thị·ΔMₖ] có thể khác không, nên chứng minh martingale thất bại.')]),
  ],
  44: [
    t(b('The sequence xⁿ is dominated by one integrable function, while a moving spike shows what happens without it.', 'Dãy xⁿ bị chặn bởi một hàm khả tích chung, còn đỉnh nhọn dịch chuyển cho thấy điều xảy ra khi thiếu điều kiện đó.'), f('|fₙ|≤g, ∫g<∞ ⇒ ∫fₙ→∫f', 'a.e. convergence and an integrable dominator', 'hội tụ h.k.n. và hàm trội khả tích'), [b('On (0,1), xⁿ→0 a.e. and 0≤xⁿ≤1, so DCT gives ∫xⁿ=1/(n+1)→0.', 'Trên (0,1), xⁿ→0 h.k.n. và 0≤xⁿ≤1, nên DCT cho ∫xⁿ=1/(n+1)→0.'), b('Choose gₙ=n1_(0,1/n): it also tends to zero a.e., but its integral is always one.', 'Chọn gₙ=n1_(0,1/n): dãy cũng tiến về không h.k.n. nhưng tích phân luôn bằng một.'), b('The second sequence lacks a common integrable dominator; a.e. convergence alone does not license passing the limit through the integral.', 'Dãy thứ hai thiếu hàm trội khả tích chung; hội tụ h.k.n. đơn thuần không cho phép đổi giới hạn qua tích phân.')]),
    t(b('Verify the tower candidate by integrating it over each event of the smaller information set.', 'Xác minh ứng viên tháp bằng cách tích phân trên mỗi biến cố của tập thông tin nhỏ hơn.'), f('E[E[X|𝓖]|𝓗]=E[X|𝓗] a.s.', '𝓗⊆𝓖 and X∈L¹', '𝓗⊆𝓖 và X∈L¹'), [b('For A∈𝓗, A is also in 𝓖, so E[1_AE[X|𝓖]]=E[1_AX].', 'Với A∈𝓗, ta cũng có A∈𝓖, nên E[1_AE[X|𝓖]]=E[1_AX].'), b('Conditioning E[X|𝓖] again on 𝓗 preserves that same tested integral.', 'Điều kiện E[X|𝓖] lần nữa theo 𝓗 giữ nguyên tích phân đã thử.'), b('Uniqueness gives equality almost surely. Changing either version on a null set changes no tested integral.', 'Tính duy nhất cho đẳng thức hầu chắc chắn. Đổi một phiên bản trên tập không không làm thay đổi tích phân đã thử.')]),
    t(b('Prove the finite-variance weak law by Chebyshev, then state the stronger sourced almost-sure law with its own hypothesis.', 'Chứng minh luật yếu phương sai hữu hạn bằng Chebyshev, rồi nêu luật hầu chắc chắn mạnh hơn với giả thiết riêng.'), f('P(|X̄ₙ−μ|>ε)≤σ²/(nε²);  E|X₁|<∞ ⇒ X̄ₙ→a.s.μ', 'iid; finite variance for WLLN, finite first absolute moment for SLLN', 'iid; phương sai hữu hạn cho WLLN, moment tuyệt đối bậc nhất hữu hạn cho SLLN'), [b('Independence gives Var(X̄ₙ)=σ²/n; Chebyshev makes the probability of an ε-deviation tend to zero.', 'Độc lập cho Var(X̄ₙ)=σ²/n; Chebyshev làm xác suất lệch ε tiến về không.'), b('The sourced SLLN assumes only E|X₁|<∞ and concludes almost-sure convergence of the sample mean.', 'SLLN được viện dẫn chỉ cần E|X₁|<∞ và kết luận trung bình mẫu hội tụ hầu chắc chắn.'), b('The first proof controls one-n probability bounds; it does not establish summability across n, which is needed for a direct Borel–Cantelli upgrade.', 'Chứng minh đầu khống chế xác suất theo n; nó không chứng minh tổng theo n hữu hạn, vốn cần cho bước nâng trực tiếp bằng Borel–Cantelli.')]),
    t(b('Find the stationary law, then use its minorization as the common component in a contraction argument.', 'Tìm luật dừng rồi dùng minorization làm thành phần chung trong lập luận co.'), f('π=(0.6,0.4);  ||μPⁿ−π||TV≤(1−0.5)ⁿ||μ−π||TV', 'the displayed two-state transition matrix', 'ma trận chuyển hai trạng thái đã cho'), [b('Solving πP=π and π₁+π₂=1 yields π=(0.6,0.4).', 'Giải πP=π và π₁+π₂=1 được π=(0.6,0.4).'), b('Each row dominates 0.5π: the residuals divided by 0.5 are Q rows (1,0) and (0,1), so Q is stochastic.', 'Mỗi hàng trội 0.5π: phần dư chia 0.5 là các hàng Q=(1,0) và (0,1), nên Q là ma trận xác suất.'), b('The one-step contraction factor is 0.5; iterating gives ||μPⁿ−π||TV≤2⁻ⁿ||μ−π||TV.', 'Hệ số co một bước là 0.5; lặp lại cho ||μPⁿ−π||TV≤2⁻ⁿ||μ−π||TV.')]),
    t(b('Use bounded stopped increments for the theorem, then identify why the random-walk hitting time lies outside its scope.', 'Dùng các bước tăng dừng bị chặn cho định lý rồi chỉ ra vì sao thời điểm chạm của bước đi nằm ngoài phạm vi.'), f('τ≤N ⇒ E[M_τ]=E[M₀]', 'martingale and stopping time bounded by deterministic N', 'martingale và thời điểm dừng bị chặn bởi N xác định'), [b('Expand M_τ=M₀+Σₖ₌₁ᴺ1{τ≥k}ΔMₖ.', 'Khai triển M_τ=M₀+Σₖ₌₁ᴺ1{τ≥k}ΔMₖ.'), b('Each {τ≥k} is known at time k−1, so its product with the next mean-zero martingale increment has expectation zero.', 'Mỗi {τ≥k} được biết tại thời điểm k−1, nên tích với bước martingale tiếp theo có kỳ vọng không.'), b('For first hitting +1, τ is a.s. finite but not bounded and M_τ=1; this does not contradict the bounded-stopping theorem.', 'Với lần đầu chạm +1, τ hữu hạn h.k.n. nhưng không bị chặn và M_τ=1; điều này không mâu thuẫn định lý dừng bị chặn.')]),
    t(b('Use Tonelli for a nonnegative tail area and reserve Fubini for absolutely integrable signed functions.', 'Dùng Tonelli cho diện tích đuôi không âm và dành Fubini cho hàm có dấu khả tích tuyệt đối.'), f('E[X]=∫₀∞P(X>t)dt (X≥0);  ∫|f|<∞ for signed Fubini', 'X nonnegative; signed interchange requires absolute integrability', 'X không âm; đổi thứ tự hàm có dấu cần khả tích tuyệt đối'), [b('For each outcome, X=∫₀∞1{X>t}dt when X≥0.', 'Với mỗi kết quả, X=∫₀∞1{X>t}dt khi X≥0.'), b('Tonelli swaps expectation and integral because the indicator is nonnegative, yielding the tail formula.', 'Tonelli đổi kỳ vọng và tích phân vì hàm chỉ thị không âm, cho công thức đuôi.'), b('Signed Fubini requires ∫|f|<∞; conditionally convergent double series can have different row and column sums when that fails.', 'Fubini cho hàm có dấu cần ∫|f|<∞; chuỗi kép hội tụ có điều kiện có thể có tổng hàng và tổng cột khác nhau khi điều kiện này thất bại.')]),
    t(b('Use conditional-expectation orthogonality to make the cross term vanish when the square is expanded.', 'Dùng tính trực giao của kỳ vọng có điều kiện để làm số hạng chéo triệt tiêu khi khai triển bình phương.'), f('E[(X−H)²]=E[(X−Z)²]+E[(Z−H)²]', 'Z=E[X|𝓖]; X,H∈L² and H is 𝓖-measurable', 'Z=E[X|𝓖]; X,H∈L² và H đo được theo 𝓖'), [b('Write X−H=(X−Z)+(Z−H) and expand the square.', 'Viết X−H=(X−Z)+(Z−H) rồi khai triển bình phương.'), b('The cross expectation E[(X−Z)(Z−H)] is zero because Z−H is in L²(𝓖) and X−Z is orthogonal to every such function.', 'Kỳ vọng chéo E[(X−Z)(Z−H)] bằng không vì Z−H thuộc L²(𝓖), còn X−Z trực giao với mọi hàm như vậy.'), b('The remaining two squared terms give the identity; the second is nonnegative, proving Z minimizes squared risk.', 'Hai số hạng bình phương còn lại cho đồng nhất thức; số hạng thứ hai không âm, chứng minh Z tối thiểu hóa rủi ro bình phương.')]),
    t(b('Combine the weak limit of Xₙ with probability limits of two perturbations using continuous mappings.', 'Kết hợp giới hạn yếu của Xₙ với giới hạn theo xác suất của hai nhiễu bằng ánh xạ liên tục.'), f('(Xₙ+Rₙ, XₙRₙ+Sₙ)⇒(X+3,3X−2)', 'Xₙ⇒X; Rₙ→P3; Sₙ→P−2', 'Xₙ⇒X; Rₙ→P3; Sₙ→P−2'), [b('Slutsky gives (Xₙ,Rₙ,Sₙ)⇒(X,3,−2) without independence.', 'Slutsky cho (Xₙ,Rₙ,Sₙ)⇒(X,3,−2) mà không cần độc lập.'), b('Apply the continuous map (x,r,s)↦(x+r,xr+s).', 'Áp dụng ánh xạ liên tục (x,r,s)↦(x+r,xr+s).'), b('With X∼N(0,1), the limits are X+3∼N(3,1) and 3X−2∼N(−2,9).', 'Với X∼N(0,1), các giới hạn là X+3∼N(3,1) và 3X−2∼N(−2,9).')]),
    t(b('Find every invariant distribution for the alternating two-state chain and inspect the trajectory from one state.', 'Tìm mọi phân phối bất biến của chuỗi hai trạng thái luân phiên rồi xem quỹ đạo bắt đầu từ một trạng thái.'), f('πP=π ⇒ π=(1/2,1/2);  μ₀Pⁿ alternates', 'P=[[0,1],[1,0]]; μ₀=(1,0)', 'P=[[0,1],[1,0]]; μ₀=(1,0)'), [b('Write π=(q,1−q). The stationarity equation q=1−q gives q=1/2, so the invariant law is unique.', 'Viết π=(q,1−q). Phương trình dừng q=1−q cho q=1/2, nên luật bất biến duy nhất.'), b('Starting from μ₀=(1,0), the law alternates between (1,0) and (0,1).', 'Bắt đầu từ μ₀=(1,0), luật luân phiên giữa (1,0) và (0,1).'), b('The chain does not converge from this start despite invariant existence; its two rows have disjoint support and fail every positive common minorization.', 'Chuỗi không hội tụ từ điểm đầu này dù có luật bất biến; hai hàng có giá đỡ rời nhau và không thỏa minorization chung dương nào.')]),
    t(b('Check the predictable event needed in the stopped-sum proof and contrast it with a future-dependent choice.', 'Kiểm tra biến cố dự đoán được cần cho chứng minh tổng dừng và so sánh với lựa chọn phụ thuộc tương lai.'), f('{τ≥k}={τ>k−1}∈𝓕ₖ₋₁', 'τ is a stopping time; discrete-time filtration', 'τ là thời điểm dừng; filtration thời gian rời rạc'), [b('By definition, {τ≤k−1}∈𝓕ₖ₋₁.', 'Theo định nghĩa, {τ≤k−1}∈𝓕ₖ₋₁.'), b('Take the complement to obtain {τ≥k}={τ>k−1}∈𝓕ₖ₋₁.', 'Lấy phần bù được {τ≥k}={τ>k−1}∈𝓕ₖ₋₁.'), b('An event selected after seeing ΔMₖ is not measurable at k−1; multiplying the increment by it can create positive expected gain and destroys the zero-mean step.', 'Biến cố chọn sau khi thấy ΔMₖ không đo được tại k−1; nhân bước tăng với nó có thể tạo lợi thế kỳ vọng dương và phá bước trung bình không.')]),
  ],
  45: [
    t(b('Compare probability laws induced by parameter values; then test whether a non-injective reparameterization merges them.', 'So sánh các luật xác suất do giá trị tham số sinh ra; sau đó kiểm tra phép tham số hóa không đơn ánh có gộp chúng không.'), f('Identifiable: P_θ=P_η ⇒ θ=η', 'Bernoulli parameter family indexed by θ', 'họ Bernoulli được chỉ số hóa bởi θ'), [b('For Bernoulli(θ), Pθ(X=1)=θ; equality of laws forces equality of these success probabilities.', 'Với Bernoulli(θ), Pθ(X=1)=θ; hai luật bằng nhau buộc xác suất thành công bằng nhau.'), b('Hence θ=η and the model is identifiable.', 'Do đó θ=η và mô hình nhận dạng được.'), b('Under parameter η∈[−1,1] mapped to Bernoulli(η²), η and −η produce the same law, so that parameterization is not identifiable.', 'Với tham số η∈[−1,1] ánh xạ tới Bernoulli(η²), η và −η sinh cùng luật, nên tham số hóa đó không nhận dạng được.')]),
    t(b('On finite common support, sufficiency means the conditional distribution of the data given T is parameter-free.', 'Trên giá đỡ hữu hạn chung, tính đủ nghĩa là phân phối có điều kiện của dữ liệu khi biết T không phụ thuộc tham số.'), f('f_θ(x)=g_θ(T(x))h(x)', 'finite sample space; common support; nonnegative factors', 'không gian mẫu hữu hạn; giá đỡ chung; các thừa số không âm'), [b('If the factorization holds, summing over x with T(x)=t factors out gθ(t); it cancels between numerator and denominator in Pθ(X=x|T=t).', 'Nếu có phân tích, cộng theo x với T(x)=t đưa gθ(t) ra ngoài; nó triệt tiêu giữa tử và mẫu trong Pθ(X=x|T=t).'), b('Conversely, if the conditional law given T=t is parameter-free, write fθ(x)=Pθ(T=t)P(X=x|T=t); set gθ(t)=Pθ(T=t) and h(x)=P(X=x|T=T(x)).', 'Ngược lại, nếu luật có điều kiện khi biết T=t không phụ thuộc tham số, viết fθ(x)=Pθ(T=t)P(X=x|T=t); đặt gθ(t)=Pθ(T=t), h(x)=P(X=x|T=T(x)).'), b('Common support ensures the conditional comparison uses the same sample points for all θ; otherwise the criterion needs support qualifications.', 'Giá đỡ chung bảo đảm phép so sánh có điều kiện dùng cùng các điểm mẫu với mọi θ; nếu không, tiêu chuẩn cần điều kiện hóa về giá đỡ.')]),
    t(b('Group Bernoulli data by the number of successes, since the likelihood depends on the ordered sample only through that count.', 'Gom dữ liệu Bernoulli theo số lần thành công vì likelihood chỉ phụ thuộc thứ tự mẫu qua số đếm đó.'), f('L_θ(x)=θ^S(1−θ)^(n−S);  S=ΣXᵢ', 'iid Bernoulli(θ); θ∈[0,1]', 'Bernoulli(θ) iid; θ∈[0,1]'), [b('Multiply the n Bernoulli probabilities to get θ^(Σxᵢ)(1−θ)^(n−Σxᵢ).', 'Nhân n xác suất Bernoulli được θ^(Σxᵢ)(1−θ)^(n−Σxᵢ).'), b('Set S=Σxᵢ, gθ(S)=θ^S(1−θ)^(n−S), and h(x)=1; the factorization shows S is sufficient.', 'Đặt S=Σxᵢ, gθ(S)=θ^S(1−θ)^(n−S), h(x)=1; phân tích cho thấy S đủ.'), b('All ordered samples with the same S have equal likelihood, so their ordering retains no further information about θ.', 'Mọi mẫu có thứ tự cùng S có likelihood bằng nhau, nên thứ tự không giữ thêm thông tin về θ.')]),
    t(b('Compare the conditional distribution of X₂ after observing T=X₁=0 under two parameter values.', 'So sánh phân phối có điều kiện của X₂ sau khi quan sát T=X₁=0 tại hai giá trị tham số.'), f('P_θ(X₂=1|T=0)=θ', 'n≥2; iid Bernoulli(θ); 0<θ<1', 'n≥2; Bernoulli(θ) iid; 0<θ<1'), [b('T=0 fixes X₁=0 but leaves X₂ as an independent Bernoulli(θ) observation.', 'T=0 cố định X₁=0 nhưng X₂ vẫn là quan sát Bernoulli(θ) độc lập.'), b('Thus Pθ(X₂=1|T=0)=1/4 when θ=1/4, but equals 3/4 when θ=3/4.', 'Vậy Pθ(X₂=1|T=0)=1/4 khi θ=1/4, nhưng bằng 3/4 khi θ=3/4.'), b('The conditional law depends on θ, so T is not sufficient even though the full Bernoulli model is identifiable.', 'Luật có điều kiện phụ thuộc θ, nên T không đủ dù mô hình Bernoulli đầy đủ nhận dạng được.')]),
    t(b('Factor the joint Poisson probability into a term depending on the sample only through its sum and a parameter-free remainder.', 'Phân tích xác suất Poisson chung thành thừa số phụ thuộc mẫu chỉ qua tổng và phần dư không phụ thuộc tham số.'), f('L_λ(x)=e^(−nλ)λ^T/∏ᵢxᵢ!;  T=ΣXᵢ', 'iid Poisson(λ), λ>0', 'Poisson(λ) iid, λ>0'), [b('Multiply e^(−λ)λ^xᵢ/xᵢ! over i to obtain e^(−nλ)λ^(Σxᵢ)/∏xᵢ!.', 'Nhân e^(−λ)λ^xᵢ/xᵢ! theo i được e^(−nλ)λ^(Σxᵢ)/∏xᵢ!.'), b('The likelihood depends on x through T=Σxᵢ with h(x)=1/∏xᵢ!, so T is sufficient by factorization.', 'Likelihood phụ thuộc x qua T=Σxᵢ với h(x)=1/∏xᵢ!, nên T đủ theo tiêu chuẩn phân tích.'), b('The model is identifiable because Eλ[Xᵢ]=λ, so equality of laws forces equal means and equal λ.', 'Mô hình nhận dạng được vì Eλ[Xᵢ]=λ, nên hai luật bằng nhau buộc trung bình và λ bằng nhau.')]),
  ],
  46: [
    t(b('Given the total number of successes, exchangeability makes each position equally likely to contain one of them.', 'Khi biết tổng số lần thành công, tính hoán vị làm mỗi vị trí có cùng xác suất chứa một lần thành công.'), f('E[X₁|T=t]=t/n;  Var(T/n)=p(1−p)/n', 'iid Bernoulli(p), T=ΣXᵢ', 'Bernoulli(p) iid, T=ΣXᵢ'), [b('If T=t, exactly t of n positions equal one; symmetry gives P(X₁=1|T=t)=t/n.', 'Nếu T=t thì đúng t trong n vị trí bằng một; đối xứng cho P(X₁=1|T=t)=t/n.'), b('Therefore E[X₁|T]=T/n, an unbiased estimator of p.', 'Vì vậy E[X₁|T]=T/n, là ước lượng không chệch của p.'), b('Var(X₁)=p(1−p), while Var(T/n)=p(1−p)/n, so conditioning lowers variance for n>1.', 'Var(X₁)=p(1−p), còn Var(T/n)=p(1−p)/n, nên điều kiện hóa giảm phương sai khi n>1.')]),
    t(b('Expand the squared centered variable by adding and subtracting its conditional mean.', 'Khai triển biến bình phương tâm hóa bằng cách cộng trừ kỳ vọng có điều kiện.'), f('Var(U)=E[Var(U|T)]+Var(E[U|T])', 'U∈L²', 'U∈L²'), [b('Write U−EU=(U−E[U|T])+(E[U|T]−EU).', 'Viết U−EU=(U−E[U|T])+(E[U|T]−EU).'), b('The cross term has conditional expectation zero given T, so its expectation vanishes.', 'Số hạng chéo có kỳ vọng có điều kiện bằng không khi biết T, nên kỳ vọng của nó triệt tiêu.'), b('The two remaining squared terms are E Var(U|T) and Var(E[U|T]); the first is nonnegative, giving the variance improvement.', 'Hai số hạng bình phương còn lại là E Var(U|T) và Var(E[U|T]); số hạng đầu không âm, cho cải thiện phương sai.')]),
    t(b('Subtract two unbiased functions of a complete statistic and apply the definition of completeness.', 'Lấy hiệu hai hàm không chệch của thống kê đầy đủ rồi áp dụng định nghĩa tính đầy đủ.'), f('E_θ[g(T)]=0 for all θ ⇒ g(T)=0 a.s.', 'T complete; g(T)=a(T)−b(T) integrable', 'T đầy đủ; g(T)=a(T)−b(T) khả tích'), [b('Unbiasedness for the same τ(θ) gives Eθ[a(T)−b(T)]=0 for every θ.', 'Không chệch cùng τ(θ) cho Eθ[a(T)−b(T)]=0 với mọi θ.'), b('Set g=a−b. Completeness says any integrable zero-mean function of T must vanish almost surely for every θ.', 'Đặt g=a−b. Tính đầy đủ nói mọi hàm khả tích của T có trung bình không phải bằng không hầu chắc chắn với mọi θ.'), b('Hence a(T)=b(T) almost surely, proving uniqueness among unbiased functions of T.', 'Do đó a(T)=b(T) hầu chắc chắn, chứng minh tính duy nhất trong các hàm không chệch của T.')]),
    t(b('Construct a nonzero function on the three possible counts whose expectation vanishes at both restricted parameter values.', 'Dựng hàm khác không trên ba số đếm có kỳ vọng bằng không tại cả hai giá trị tham số hạn chế.'), f('g(0)=3, g(1)=−5, g(2)=3;  E_p[g(T)]=3−16p+16p²', 'T=X₁+X₂; p∈{1/4,3/4}', 'T=X₁+X₂; p∈{1/4,3/4}'), [b('Under Binomial(2,p), E[g(T)]=3(1−p)²−10p(1−p)+3p²=3−16p+16p².', 'Dưới Binomial(2,p), E[g(T)]=3(1−p)²−10p(1−p)+3p²=3−16p+16p².'), b('At p=1/4 this is 3−4+1=0; at p=3/4 it is 3−12+9=0.', 'Tại p=1/4 giá trị là 3−4+1=0; tại p=3/4 là 3−12+9=0.'), b('The function is not identically zero, so the sufficient statistic T is not complete in the restricted two-parameter model.', 'Hàm không đồng nhất bằng không, nên thống kê đủ T không đầy đủ trong mô hình tham số hai điểm này.')]),
    t(b('Use the two standard results in sequence, while marking which model theorem is being assumed.', 'Dùng hai kết quả chuẩn theo thứ tự, đồng thời nêu rõ định lý mô hình nào đang được giả sử.'), f('δ(T)=E[U|T] unbiased;  Var(δ)≤Var(U)', 'T sufficient for Rao–Blackwell; complete for uniqueness and UMVU', 'T đủ cho Rao–Blackwell; đầy đủ cho tính duy nhất và UMVU'), [b('T/n is unbiased for p because E[T/n]=p.', 'T/n không chệch cho p vì E[T/n]=p.'), b('For any unbiased U, Rao–Blackwellization E[U|T] remains unbiased and has no larger variance; completeness makes the unbiased function of T unique.', 'Với mọi U không chệch, E[U|T] vẫn không chệch và có phương sai không lớn hơn; tính đầy đủ làm hàm không chệch của T duy nhất.'), b('Thus T/n is the unique unbiased function of T and UMVU. This exercise invokes, rather than proves, completeness of the binomial total.', 'Vì vậy T/n là hàm không chệch duy nhất của T và UMVU. Bài này viện dẫn, không chứng minh, tính đầy đủ của tổng nhị thức.')]),
  ],
  47: [
    t(b('Spend the size budget on the outcome most likely under the alternative; randomize only at the boundary if needed.', 'Dùng ngân sách mức kiểm định cho kết quả có khả năng lớn nhất dưới đối thuyết; chỉ ngẫu nhiên hóa ở biên nếu cần.'), f('φ*=1{f₁>kf₀}, with boundary randomization to attain E₀φ*=α', 'simple H₀ versus simple H₁', 'H₀ đơn so với H₁ đơn'), [b('Under H₀, X=1 has probability .2; rejecting only at X=1 gives size .2 exactly.', 'Dưới H₀, X=1 có xác suất .2; chỉ bác bỏ khi X=1 cho mức .2 chính xác.'), b('The likelihood ratio at X=1 is .8/.2=4, while at X=0 it is .2/.8=1/4, so this is the likelihood-ratio ordering.', 'Tỷ số likelihood tại X=1 là .8/.2=4, còn tại X=0 là .2/.8=1/4, nên đây là thứ tự tỷ số likelihood.'), b('Its power is P₁(X=1)=.8, maximal among tests with size at most .2.', 'Lực kiểm định là P₁(X=1)=.8, lớn nhất trong các kiểm định có mức không quá .2.')]),
    t(b('Compare any competing test pointwise with the likelihood-ratio test and integrate under both models.', 'So sánh từng điểm kiểm định cạnh tranh với kiểm định tỷ số likelihood rồi tích phân theo cả hai mô hình.'), f('(φ*−φ)(f₁−kf₀)≥0 ⇒ E₁φ*−E₁φ≥k(E₀φ*−E₀φ)≥0', 'φ* has size α; E₀φ≤α; k≥0', 'φ* có mức α; E₀φ≤α; k≥0'), [b('On f₁−kf₀>0, φ*=1 and φ≤1; on f₁−kf₀<0, φ*=0 and φ≥0. The product is nonnegative in both regions.', 'Khi f₁−kf₀>0, φ*=1 và φ≤1; khi f₁−kf₀<0, φ*=0 và φ≥0. Tích không âm ở cả hai miền.'), b('Integrate: E₁φ*−E₁φ≥k(E₀φ*−E₀φ).', 'Tích phân cho E₁φ*−E₁φ≥k(E₀φ*−E₀φ).'), b('Because E₀φ* is α and E₀φ≤α, the right side is nonnegative, proving maximal power.', 'Vì E₀φ*=α và E₀φ≤α, vế phải không âm, chứng minh lực kiểm định tối đa.')]),
    t(b('Express the likelihood ratio as a function of the success count and check its one-step ratio.', 'Biểu diễn tỷ số likelihood theo số lần thành công rồi kiểm tra tỷ số khi tăng một đơn vị.'), f('Λ(S)=(p₁/p₀)^S((1−p₁)/(1−p₀))^(n−S)', 'Binomial(n,p); p₁>p₀', 'Binomial(n,p); p₁>p₀'), [b('Form the likelihood ratio from the two binomial pmfs; the combinatorial coefficient cancels.', 'Lập tỷ số từ hai khối xác suất nhị thức; hệ số tổ hợp triệt tiêu.'), b('Λ(S+1)/Λ(S)=p₁(1−p₀)/(p₀(1−p₁))>1, so Λ increases with S.', 'Λ(S+1)/Λ(S)=p₁(1−p₀)/(p₀(1−p₁))>1, nên Λ tăng theo S.'), b('Neyman–Pearson rejects for large S, randomizing at a boundary count if exact size requires it.', 'Neyman–Pearson bác bỏ khi S lớn, ngẫu nhiên hóa tại số đếm biên nếu cần đạt đúng mức.')]),
    t(b('Separate a simple alternative, which fixes one likelihood, from a composite alternative containing many distributions.', 'Phân biệt đối thuyết đơn cố định một likelihood với đối thuyết phức hợp chứa nhiều phân phối.'), f('NP lemma compares one f₁ against one f₀', 'simple-vs-simple hypotheses', 'giả thuyết đơn-đơn'), [b('The lemma optimizes power for one specified alternative density f₁.', 'Bổ đề tối ưu lực kiểm định cho một mật độ đối thuyết f₁ đã xác định.'), b('The alternative θ≠θ₀ contains many possible θ values and therefore many likelihood ratios.', 'Đối thuyết θ≠θ₀ chứa nhiều giá trị θ và do đó nhiều tỷ số likelihood.'), b('A test most powerful for one θ need not be most powerful for another; a UMP claim needs an additional argument covering every alternative point.', 'Kiểm định mạnh nhất cho một θ có thể không mạnh nhất cho θ khác; khẳng định UMP cần lập luận bổ sung bao quát mọi điểm đối thuyết.')]),
    t(b('Allocate the null-size budget to X=1 first because it has the larger likelihood ratio.', 'Phân bổ ngân sách mức dưới giả thuyết không cho X=1 trước vì kết quả này có tỷ số likelihood lớn hơn.'), f('size=.3r₁+.7r₀;  power=.6r₁+.4r₀', '0≤r₀,r₁≤1; null p₀=.3, alternative p₁=.6', '0≤r₀,r₁≤1; p₀=.3, p₁=.6'), [b('Size is .3r₁+.7r₀ and must not exceed .3.', 'Mức kiểm định là .3r₁+.7r₀ và phải không vượt .3.'), b('Power is .6r₁+.4r₀; per unit of size, rejecting at X=1 gives more power than rejecting at X=0.', 'Lực là .6r₁+.4r₀; trên mỗi đơn vị mức, bác bỏ tại X=1 cho lực lớn hơn tại X=0.'), b('Set r₁=1,r₀=0: size=.3 and power=.6, the maximum.', 'Đặt r₁=1,r₀=0: mức=.3 và lực=.6, là cực đại.')]),
  ],
  48: [
    t(b('Differentiate the Bernoulli log likelihood and use independence to add information across observations.', 'Lấy đạo hàm log likelihood Bernoulli rồi dùng độc lập để cộng thông tin qua các quan sát.'), f('S_p=Σᵢ(Xᵢ−p)/(p(1−p));  Iₙ(p)=n/[p(1−p)]', 'iid Bernoulli(p), 0<p<1', 'Bernoulli(p) iid, 0<p<1'), [b('The log likelihood is S log p+(n−S)log(1−p); its derivative simplifies to Σ(Xᵢ−p)/(p(1−p)).', 'Log likelihood là S log p+(n−S)log(1−p); đạo hàm rút gọn thành Σ(Xᵢ−p)/(p(1−p)).'), b('Each score term has mean zero because E[Xᵢ−p]=0.', 'Mỗi số hạng score có trung bình bằng không vì E[Xᵢ−p]=0.'), b('The variance of one score is p(1−p)/[p²(1−p)²]=1/[p(1−p)]; independence gives n/[p(1−p)].', 'Phương sai score một quan sát là p(1−p)/[p²(1−p)²]=1/[p(1−p)]; độc lập cho n/[p(1−p)].')]),
    t(b('Differentiate the unbiasedness identity, identify covariance with the score, then apply Cauchy–Schwarz.', 'Lấy đạo hàm đồng nhất thức không chệch, nhận diện hiệp phương sai với score rồi áp dụng Cauchy–Schwarz.'), f('Varθ(T)≥[τ′(θ)]²/I(θ)', 'common parameter-independent support; valid differentiation under integral; finite variance; 0<I<∞', 'giá đỡ chung không phụ thuộc tham số; đổi đạo hàm qua tích phân hợp lệ; phương sai hữu hạn; 0<I<∞'), [b('From EθT=τ(θ), differentiate under the integral: Eθ[T Sθ]=τ′(θ).', 'Từ EθT=τ(θ), lấy đạo hàm dưới dấu tích phân: Eθ[T Sθ]=τ′(θ).'), b('Since EθSθ=0, Covθ(T,Sθ)=τ′(θ).', 'Vì EθSθ=0, Covθ(T,Sθ)=τ′(θ).'), b('Cauchy–Schwarz gives τ′²≤Var(T)I(θ), yielding the bound; common support and domination justify both score identities.', 'Cauchy–Schwarz cho τ′²≤Var(T)I(θ), suy ra chặn; giá đỡ chung và hàm trội biện minh các đồng nhất thức score.')]),
    t(b('Compare the sample-proportion variance directly with the information lower bound.', 'So sánh trực tiếp phương sai tỷ lệ mẫu với chặn dưới từ thông tin.'), f('Var(S/n)=p(1−p)/n=[d p/dp]²/Iₙ(p)', 'iid Bernoulli(p); 0<p<1', 'Bernoulli(p) iid; 0<p<1'), [b('The estimator S/n has variance p(1−p)/n.', 'Ước lượng S/n có phương sai p(1−p)/n.'), b('For τ(p)=p, τ′(p)=1 and Iₙ(p)=n/[p(1−p)], so the CR bound is also p(1−p)/n.', 'Với τ(p)=p, τ′(p)=1 và Iₙ(p)=n/[p(1−p)], nên chặn CR cũng là p(1−p)/n.'), b('The score is a constant multiple of S−np, so the centered estimator is proportional to the score and Cauchy–Schwarz is attained.', 'Score tỷ lệ với S−np, nên ước lượng đã tâm hóa tỷ lệ với score và đạt đẳng thức Cauchy–Schwarz.')]),
    t(b('Compute the endpoint MLE, then locate the support dependence that invalidates the usual score differentiation.', 'Tính MLE tại đầu mút rồi xác định sự phụ thuộc giá đỡ làm phép đạo hàm score thông thường mất hiệu lực.'), f('θ̂_MLE=X_(n);  Var(X_(n))=nθ²/[(n+1)²(n+2)]', 'iid Uniform(0,θ); θ>0', 'Uniform(0,θ) iid; θ>0'), [b('The joint density is θ^(−n)1{0≤X_(1), X_(n)≤θ}; it is maximized at the smallest θ containing all observations, θ̂=X_(n).', 'Mật độ chung là θ^(−n)1{0≤X_(1), X_(n)≤θ}; nó cực đại tại θ nhỏ nhất chứa mọi quan sát, θ̂=X_(n).'), b('The maximum has CDF (x/θ)^n on 0≤x≤θ; its variance is nθ²/[(n+1)²(n+2)].', 'Giá trị lớn nhất có CDF (x/θ)^n trên 0≤x≤θ; phương sai là nθ²/[(n+1)²(n+2)].'), b('The support endpoint θ moves with the parameter, so differentiating the density under an integral over common support is invalid; the regular CR bound need not apply.', 'Đầu mút giá đỡ θ dịch theo tham số, nên không thể lấy đạo hàm mật độ dưới tích phân trên giá đỡ chung; chặn CR chính quy có thể không áp dụng.')]),
    t(b('Transform the score by the chain rule and transform information by the square of the derivative.', 'Biến đổi score bằng quy tắc dây chuyền và biến đổi thông tin bằng bình phương đạo hàm.'), f('S_η=S_θ(dθ/dη);  I_η=I_θ(dθ/dη)²;  Var(T)≥1/I_η', 'η=g(θ), g′(θ)≠0; T unbiased for η', 'η=g(θ), g′(θ)≠0; T không chệch cho η'), [b('The chain rule gives ∂η log f=(∂θ log f)(dθ/dη).', 'Quy tắc dây chuyền cho ∂η log f=(∂θ log f)(dθ/dη).'), b('Square and take expectation to get Iη=Iθ(dθ/dη)².', 'Bình phương và lấy kỳ vọng được Iη=Iθ(dθ/dη)².'), b('For estimating τ(η)=η, τ′=1, so the CR variance bound is 1/Iη= (dη/dθ)²/Iθ.', 'Với ước lượng τ(η)=η, τ′=1, nên chặn phương sai CR là 1/Iη=(dη/dθ)²/Iθ.')]),
  ],
  49: [
    t(b('Use the population separation gap outside an ε-neighborhood to contradict approximate maximization.', 'Dùng khoảng cách tách biệt của tiêu chuẩn quần thể ngoài lân cận ε để tạo mâu thuẫn với tính cực đại xấp xỉ.'), f('sup_{d(θ,θ₀)≥ε}M(θ)≤M(θ₀)−Δε', 'unique maximizer θ₀; uniform error and optimization error each <Δε/4', 'θ₀ là điểm cực đại duy nhất; sai số đều và sai số tối ưu đều <Δε/4'), [b('Outside the ε-ball, population values are at least Δε below M(θ₀).', 'Ngoài quả cầu ε, giá trị quần thể thấp hơn M(θ₀) ít nhất Δε.'), b('Uniform error below Δε/4 lowers the empirical criterion there by at most Δε/4 and raises it at θ₀ by at most Δε/4.', 'Sai số đều dưới Δε/4 làm tiêu chuẩn thực nghiệm bên ngoài giảm nhiều nhất Δε/4 và tại θ₀ tăng nhiều nhất Δε/4.'), b('An additional optimization error below Δε/4 still leaves θ̂ with a strictly smaller criterion outside the ball, a contradiction.', 'Sai số tối ưu bổ sung dưới Δε/4 vẫn khiến θ̂ có tiêu chuẩn thấp hơn nghiêm ngặt bên ngoài quả cầu, dẫn tới mâu thuẫn.')]),
    t(b('The maximizer of the Bernoulli average log likelihood is the sample proportion, which converges to the true interior parameter.', 'Điểm cực đại log likelihood trung bình Bernoulli là tỷ lệ mẫu, hội tụ về tham số thật bên trong.'), f('p̂=S/n→Pp₀', 'iid Bernoulli(p₀); p₀∈(a,1−a); maximize over [a,1−a]', 'Bernoulli(p₀) iid; p₀∈(a,1−a); cực đại trên [a,1−a]'), [b('The average log likelihood is p̂ log p+(1−p̂)log(1−p), maximized at p̂ before restricting the parameter interval.', 'Log likelihood trung bình là p̂ log p+(1−p̂)log(1−p), đạt cực đại tại p̂ trước khi giới hạn khoảng tham số.'), b('Since p₀ is interior, with probability tending to one p̂ lies inside [a,1−a]; there the constrained maximizer equals p̂.', 'Vì p₀ nằm trong khoảng trong, xác suất p̂ thuộc [a,1−a] tiến về một; khi đó nghiệm cực đại có ràng buộc bằng p̂.'), b('The law of large numbers gives p̂→Pp₀, hence the constrained estimator is consistent.', 'Luật số lớn cho p̂→Pp₀, nên ước lượng có ràng buộc nhất quán.')]),
    t(b('A shrinking spike can keep a high empirical peak at a parameter value far from the unique population maximizer.', 'Đỉnh nhọn co lại có thể giữ đỉnh thực nghiệm cao tại tham số xa điểm cực đại quần thể duy nhất.'), f('Mₙ(θ)=−θ²+2·1_{Iₙ}(θ),  θₙ=1−1/n', 'Iₙ shrinks to 1; each fixed θ is eventually outside Iₙ', 'Iₙ co về 1; mỗi θ cố định cuối cùng nằm ngoài Iₙ'), [b('For every fixed θ, θ eventually lies outside Iₙ, so Mₙ(θ)→−θ²=M(θ) pointwise.', 'Với mỗi θ cố định, cuối cùng θ nằm ngoài Iₙ, nên Mₙ(θ)→−θ²=M(θ) từng điểm.'), b('At θₙ the spike gives Mₙ(θₙ)=−θₙ²+2, approaching 1, while Mₙ(0)=0.', 'Tại θₙ, đỉnh nhọn cho Mₙ(θₙ)=−θₙ²+2, tiến tới 1, còn Mₙ(0)=0.'), b('Thus an argmax can stay near 1 rather than 0; pointwise convergence lacks the uniform control required by argmax consistency.', 'Vì vậy argmax có thể ở gần 1 thay vì 0; hội tụ từng điểm thiếu khống chế đều cần cho tính nhất quán argmax.')]),
    t(b('Cover compact parameter space by a finite net, control criterion error on the net, and extend by the random Lipschitz envelope.', 'Phủ không gian tham số compact bằng lưới hữu hạn, khống chế sai số tiêu chuẩn trên lưới rồi mở rộng bằng bao Lipschitz ngẫu nhiên.'), f('sup_θ|Pₙm_θ−Pm_θ|→P0', 'compact Θ; pointwise LLN; |mθ−mη|≤L d(θ,η), E L<∞', 'Θ compact; LLN từng điểm; |mθ−mη|≤L d(θ,η), E L<∞'), [b('Choose a finite ε-net of Θ; pointwise LLN gives convergence at every net point, hence uniformly over this finite set.', 'Chọn lưới ε hữu hạn của Θ; LLN từng điểm cho hội tụ tại mọi điểm lưới, do đó đều trên tập hữu hạn.'), b('For any θ choose nearby net point η; the empirical and population differences are each bounded by the corresponding averages of L times ε.', 'Với mỗi θ chọn điểm lưới η gần đó; chênh lệch thực nghiệm và quần thể đều bị chặn bởi trung bình tương ứng của L nhân ε.'), b('The LLN controls PₙL and PL, while ε can be arbitrarily small; therefore the supremum error tends to zero in probability.', 'LLN khống chế PₙL và PL, còn ε tùy ý nhỏ; do đó sai số supremum tiến về không theo xác suất.')]),
    t(b('Recognize the sample mean as both a direct method-of-moments estimator and the quadratic criterion maximizer.', 'Nhận ra trung bình mẫu vừa là ước lượng moment trực tiếp vừa là nghiệm cực đại tiêu chuẩn bậc hai.'), f('θ̂ₙ=Z̄ₙ;  argmax_θ −(Z̄ₙ−θ)²', 'iid finite-mean Z; compact Θ contains θ₀ in its interior', 'Z iid có kỳ vọng hữu hạn; Θ compact chứa θ₀ ở bên trong'), [b('The law of large numbers gives Z̄ₙ→Pθ₀ directly.', 'Luật số lớn cho Z̄ₙ→Pθ₀ trực tiếp.'), b('For each sample, −(Z̄ₙ−θ)² is uniquely maximized at θ=Z̄ₙ; with compact constraints, the solution is the projection onto Θ.', 'Với mỗi mẫu, −(Z̄ₙ−θ)² đạt cực đại duy nhất tại θ=Z̄ₙ; có ràng buộc compact, nghiệm là hình chiếu lên Θ.'), b('Since θ₀ belongs to Θ, consistency of Z̄ₙ makes its projection consistent too; the population criterion −(θ₀−θ)² has unique maximizer θ₀.', 'Vì θ₀ thuộc Θ, tính nhất quán của Z̄ₙ kéo theo hình chiếu nhất quán; tiêu chuẩn quần thể −(θ₀−θ)² có điểm cực đại duy nhất θ₀.')]),
  ],
  50: [
    t(b('Linearize the estimating equation around θ₀ and solve the first-order expansion for the estimator error.', 'Tuyến tính hóa phương trình ước lượng quanh θ₀ rồi giải khai triển bậc nhất theo sai số ước lượng.'), f('√n(θ̂ₙ−θ₀)=A⁻¹√nPₙψ(θ₀)+oP(1)', 'Pₙψ(θ̂ₙ)=oP(n⁻¹ᐟ²); derivative limit ∫Pₙ∂ψ→−A; A nonsingular', 'Pₙψ(θ̂ₙ)=oP(n⁻¹ᐟ²); giới hạn đạo hàm ∫Pₙ∂ψ→−A; A khả nghịch'), [b('A mean-value expansion gives 0≈Pₙψ(θ₀)−A(θ̂ₙ−θ₀), with the derivative averaged along the segment converging to −A.', 'Khai triển giá trị trung bình cho 0≈Pₙψ(θ₀)−A(θ̂ₙ−θ₀), với đạo hàm trung bình dọc đoạn hội tụ về −A.'), b('Rearrange: √n(θ̂ₙ−θ₀)=A⁻¹√nPₙψ(θ₀)+oP(1).', 'Chuyển vế: √n(θ̂ₙ−θ₀)=A⁻¹√nPₙψ(θ₀)+oP(1).'), b('The iid score CLT gives √nPₙψ(θ₀)⇒N(0,B), so the limit covariance is A⁻¹BA⁻ᵀ.', 'CLT iid cho √nPₙψ(θ₀)⇒N(0,B), nên hiệp phương sai giới hạn là A⁻¹BA⁻ᵀ.')]),
    t(b('Insert the scalar sensitivity A and score variance B into the sandwich covariance, then divide by n for estimator variance.', 'Thay độ nhạy A và phương sai score B dạng vô hướng vào hiệp phương sai sandwich rồi chia n để ra phương sai ước lượng.'), f('V=A⁻²B=18/4=4.5;  SE(θ̂ₙ)≈√(V/n)', 'A=2, B=18, n=200', 'A=2, B=18, n=200'), [b('The limiting variance of √n(θ̂ₙ−θ₀) is B/A²=18/4=4.5.', 'Phương sai giới hạn của √n(θ̂ₙ−θ₀) là B/A²=18/4=4.5.'), b('At n=200, Var(θ̂ₙ)≈4.5/200=0.0225.', 'Với n=200, Var(θ̂ₙ)≈4.5/200=0.0225.'), b('Thus the standard error is √0.0225=0.15.', 'Vì vậy sai số chuẩn là √0.0225=0.15.')]),
    t(b('Differentiate the normalized density identity twice and use the zero-mean score identity.', 'Lấy đạo hàm hai lần đồng nhất thức chuẩn hóa mật độ rồi dùng score có trung bình bằng không.'), f('−Eθ[ℓ″θ]=Eθ[(ℓ′θ)²]', 'regular correctly specified density; common support and valid differentiation under integral', 'mật độ đúng mô hình chính quy; giá đỡ chung và đổi đạo hàm qua tích phân hợp lệ'), [b('Let ℓ′=∂θ log f and ℓ″=∂²θ log f; then f″/f=ℓ″+(ℓ′)².', 'Đặt ℓ′=∂θ log f và ℓ″=∂²θ log f; khi đó f″/f=ℓ″+(ℓ′)².'), b('Twice differentiating ∫fθ=1 gives Eθ[ℓ″+(ℓ′)²]=0.', 'Lấy đạo hàm hai lần ∫fθ=1 cho Eθ[ℓ″+(ℓ′)²]=0.'), b('Rearrange to get information equality. Under misspecification the score mean or likelihood identity need not vanish at the pseudo-true value.', 'Chuyển vế được đẳng thức thông tin. Khi sai mô hình, trung bình score hoặc đồng nhất thức likelihood có thể không triệt tiêu tại giá trị giả đúng.')]),
    t(b('Name a separate failed assumption in each example before invoking the sandwich theorem.', 'Nêu một giả thiết thất bại riêng trong từng ví dụ trước khi áp dụng định lý sandwich.'), f('Asymptotic sandwich needs an interior root, finite score second moment, and nonsingular derivative limit', 'the theorem assumptions are not automatic', 'các giả thiết định lý không tự động đúng'), [b('For Bernoulli p∈[0,1], the true value p=0 is a boundary point, not an interior identified maximizer.', 'Với Bernoulli p∈[0,1], giá trị thật p=0 nằm ở biên, không phải cực đại nhận dạng bên trong.'), b('For a location score proportional to Z with finite E|Z| but infinite E[Z²], the score has infinite second moment, so the iid score CLT assumption fails.', 'Với score vị trí tỷ lệ Z có E|Z| hữu hạn nhưng E[Z²] vô hạn, score có moment bậc hai vô hạn nên giả thiết CLT iid cho score thất bại.'), b('These failures block the usual normal sandwich conclusion; consistency or another limit theorem must be studied separately.', 'Các thất bại này chặn kết luận chuẩn sandwich thông thường; cần xét riêng tính nhất quán hoặc định lý giới hạn khác.')]),
    t(b('Linearize the vector estimating equation and sandwich the score covariance between inverse Jacobians.', 'Tuyến tính hóa phương trình ước lượng vector và kẹp hiệp phương sai score giữa các Jacobian nghịch đảo.'), f('A=G;  √n(θ̂−θ₀)⇒N(0,G⁻¹ΩG⁻ᵀ)', 'G=E[∂θg] nonsingular; Ω=E[ggᵀ] finite; consistent root and regularity', 'G=E[∂θg] khả nghịch; Ω=E[ggᵀ] hữu hạn; nghiệm nhất quán và điều kiện chính quy'), [b('Expand Pₙg(θ̂)=0 around θ₀: 0≈Pₙg(θ₀)+G(θ̂−θ₀).', 'Khai triển Pₙg(θ̂)=0 quanh θ₀: 0≈Pₙg(θ₀)+G(θ̂−θ₀).'), b('Solve √n(θ̂−θ₀)≈−G⁻¹√nPₙg(θ₀); the score average has asymptotic covariance Ω.', 'Giải được √n(θ̂−θ₀)≈−G⁻¹√nPₙg(θ₀); trung bình score có hiệp phương sai tiệm cận Ω.'), b('The sandwich is G⁻¹ΩG⁻ᵀ; the minus sign does not affect covariance.', 'Sandwich là G⁻¹ΩG⁻ᵀ; dấu trừ không ảnh hưởng hiệp phương sai.')]),
  ],
  51: [
    t(b('Separate the Taylor linear term from its remainder and use Slutsky on the scaled statistic.', 'Tách số hạng tuyến tính Taylor khỏi phần dư rồi dùng Slutsky cho thống kê đã chuẩn hóa.'), f('√n[g(Tₙ)−g(θ₀)]⇒g′(θ₀)Z', '√n(Tₙ−θ₀)⇒Z; g differentiable at θ₀', '√n(Tₙ−θ₀)⇒Z; g khả vi tại θ₀'), [b('Differentiability gives g(Tₙ)−g(θ₀)=g′(θ₀)(Tₙ−θ₀)+rₙ with rₙ=oP(|Tₙ−θ₀|).', 'Tính khả vi cho g(Tₙ)−g(θ₀)=g′(θ₀)(Tₙ−θ₀)+rₙ với rₙ=oP(|Tₙ−θ₀|).'), b('Multiply by √n; the scaled remainder tends to zero in probability.', 'Nhân với √n; phần dư đã chuẩn hóa tiến về không theo xác suất.'), b('The leading term converges to g′(θ₀)Z, giving the first-order delta limit.', 'Số hạng chính hội tụ tới g′(θ₀)Z, cho giới hạn delta bậc nhất.')]),
    t(b('Use the derivative 1/μ of the logarithm to transform the sample-mean normal limit.', 'Dùng đạo hàm 1/μ của logarithm để biến đổi giới hạn chuẩn của trung bình mẫu.'), f('√n(log X̄ₙ−log μ)⇒N(0,σ²/μ²);  SE≈σ̂/(μ̂√n)', 'μ>0; √n(X̄ₙ−μ)⇒N(0,σ²); X̄ₙ>0 with high probability', 'μ>0; √n(X̄ₙ−μ)⇒N(0,σ²); X̄ₙ>0 với xác suất cao'), [b('For g(x)=log x, g′(μ)=1/μ.', 'Với g(x)=log x, g′(μ)=1/μ.'), b('The delta method multiplies the original variance σ² by 1/μ².', 'Phương pháp delta nhân phương sai ban đầu σ² với 1/μ².'), b('Estimate σ and μ with σ̂ and X̄ₙ to get approximate standard error σ̂/(X̄ₙ√n).', 'Ước lượng σ và μ bằng σ̂ và X̄ₙ để được sai số chuẩn xấp xỉ σ̂/(X̄ₙ√n).')]),
    t(b('When the first derivative vanishes, expand to second order and square the Gaussian limit.', 'Khi đạo hàm bậc nhất triệt tiêu, khai triển bậc hai rồi bình phương giới hạn Gaussian.'), f('n g(Tₙ)⇒Z²', 'θ₀ fixed; g(t)=(t−θ₀)²; √n(Tₙ−θ₀)⇒Z∼N(0,σ²)', 'θ₀ cố định; g(t)=(t−θ₀)²; √n(Tₙ−θ₀)⇒Z∼N(0,σ²)'), [b('Write n(Tₙ−θ₀)²=[√n(Tₙ−θ₀)]².', 'Viết n(Tₙ−θ₀)²=[√n(Tₙ−θ₀)]².'), b('The square map is continuous, so the continuous mapping theorem gives convergence to Z².', 'Phép bình phương liên tục, nên định lý ánh xạ liên tục cho hội tụ tới Z².'), b('The nondegenerate scaling is n, and the limit is σ²χ²₁ rather than a centered normal.', 'Chuẩn hóa không suy biến là n, giới hạn là σ²χ²₁ thay vì chuẩn tâm hóa.')]),
    t(b('Apply the absolute-value map to the weak limit; the kink makes the ordinary derivative-based formula unavailable.', 'Áp dụng hàm trị tuyệt đối lên giới hạn yếu; điểm gấp khúc khiến công thức khả vi thông thường không dùng được.'), f('√n|Tₙ|⇒|Z|', '√nTₙ⇒Z∼N(0,1); g(t)=|t| is not differentiable at 0', '√nTₙ⇒Z∼N(0,1); g(t)=|t| không khả vi tại 0'), [b('Rewrite √n|Tₙ|=|√nTₙ|.', 'Viết lại √n|Tₙ|=|√nTₙ|.'), b('Absolute value is continuous, so the continuous mapping theorem gives |Z|.', 'Trị tuyệt đối liên tục, nên định lý ánh xạ liên tục cho |Z|.'), b('The limit is half-normal, not centered Gaussian; the ordinary delta method cannot use g′(0) because it does not exist.', 'Giới hạn là nửa chuẩn, không phải Gaussian tâm hóa; delta thông thường không dùng được vì g′(0) không tồn tại.')]),
    t(b('Differentiate arcsin√p at an interior proportion and combine it with the Bernoulli variance.', 'Lấy đạo hàm arcsin√p tại tỷ lệ bên trong rồi kết hợp với phương sai Bernoulli.'), f('g′(p)=1/[2√(p(1−p))];  √n(g(p̂)−g(p))⇒N(0,1/4)', 'iid Bernoulli(p); 0<p<1', 'Bernoulli(p) iid; 0<p<1'), [b('For g(p)=arcsin√p, the chain rule gives g′(p)=1/[2√(p(1−p))].', 'Với g(p)=arcsin√p, quy tắc dây chuyền cho g′(p)=1/[2√(p(1−p))].'), b('The sample proportion has asymptotic variance p(1−p), so the transformed variance is g′(p)²p(1−p)=1/4.', 'Tỷ lệ mẫu có phương sai tiệm cận p(1−p), nên phương sai sau biến đổi là g′(p)²p(1−p)=1/4.'), b('At p=0 or 1 the derivative is unbounded and the regular first-order interior argument fails.', 'Tại p=0 hoặc 1, đạo hàm không bị chặn và lập luận bậc nhất chính quy bên trong thất bại.')]),
  ],
  52: [
    t(b('Condition on the observed sample; bootstrap draws are iid from its empirical distribution.', 'Điều kiện theo mẫu quan sát; các lần lấy bootstrap độc lập cùng phân phối thực nghiệm.'), f('Var*(X̄*)=sₙ²/n;  nVar*(X̄*)=sₙ²→Pσ²', 'iid sampling with finite variance; sₙ² is empirical variance', 'lấy mẫu iid có phương sai hữu hạn; sₙ² là phương sai thực nghiệm'), [b('Each bootstrap draw has conditional mean X̄ and variance sₙ², the empirical variance.', 'Mỗi lần lấy bootstrap có trung bình có điều kiện X̄ và phương sai sₙ², tức phương sai thực nghiệm.'), b('The n conditional iid draws have mean variance sₙ²/n.', 'n lần lấy iid có điều kiện cho phương sai trung bình sₙ²/n.'), b('The law of large numbers gives sₙ²→Pσ², so nVar*(X̄*)→Pσ².', 'Luật số lớn cho sₙ²→Pσ², nên nVar*(X̄*)→Pσ².')]),
    t(b('Randomly break ties before ranking, then use symmetry of the permutation orbit to determine the rank distribution.', 'Phá hòa ngẫu nhiên trước khi xếp hạng rồi dùng đối xứng của quỹ đạo hoán vị để xác định phân phối thứ hạng.'), f('R∼Unif{1,…,N};  p=(R−1+U)/N∼Unif(0,1)', 'sharp null and exchangeability over N positions; U independent uniform', 'giả thuyết không sắc và tính hoán đổi trên N vị trí; U độc lập phân phối đều'), [b('Under exchangeability, every one of the N tie-randomized ranks is equally likely, so P(R≤k)=k/N.', 'Dưới tính hoán đổi, mỗi thứ hạng phá hòa trong N vị trí đồng xác suất, nên P(R≤k)=k/N.'), b('R/N is discrete super-uniform because P(R/N≤u)=⌊Nu⌋/N≤u; conservative tie-counted p-values are also super-uniform by including all ties.', 'R/N siêu đều rời rạc vì P(R/N≤u)=⌊Nu⌋/N≤u; p-value đếm hòa bảo thủ cũng siêu đều vì tính mọi trường hợp hòa.'), b('For independent U∼Uniform(0,1), intervals ((r−1)/N,r/N) are chosen with equal probability and U fills each interval uniformly, giving a continuous uniform p-value.', 'Với U∼Uniform(0,1) độc lập, mỗi khoảng ((r−1)/N,r/N) được chọn với xác suất bằng nhau và U lấp đầy đều khoảng đó, cho p-value đều liên tục.')]),
    t(b('Enumerate all six treated pairs, compute their absolute mean differences, and count assignments at least as extreme as observed.', 'Liệt kê sáu cặp được điều trị, tính chênh lệch trị tuyệt đối giữa hai trung bình rồi đếm các phân công cực đoan ít nhất bằng quan sát.'), f('p_exact=#{assignments with |T|≥|T_obs|}/6', 'sharp randomization null; two treated among four', 'giả thuyết không ngẫu nhiên hóa sắc; hai trong bốn được điều trị'), [b('Observed {7,8} has treated mean 7.5, control mean 2.5, and |T_obs|=5.', 'Quan sát {7,8} có trung bình điều trị 7.5, đối chứng 2.5 và |T_obs|=5.'), b('The six treated pairs {2,3},{2,7},{2,8},{3,7},{3,8},{7,8} have absolute differences 5,1,0,0,1,5.', 'Sáu cặp {2,3},{2,7},{2,8},{3,7},{3,8},{7,8} có chênh lệch tuyệt đối lần lượt 5,1,0,0,1,5.'), b('Two of six assignments are at least as extreme as 5, so the two-sided exact p-value is 2/6=1/3.', 'Hai trong sáu phân công cực đoan ít nhất bằng 5, nên p-value hai phía chính xác là 2/6=1/3.')]),
    t(b('Compare the actual sampling law under perfect dependence with the empirical iid resampling law.', 'So sánh luật lấy mẫu thật dưới phụ thuộc hoàn toàn với luật lấy lại iid thực nghiệm.'), f('Xᵢ=Z ⇒ √n X̄=√nZ;  Var*(√n(X̄*−X̄))=sₙ²', 'Z has mean 0 and variance 1; observations are identical copies', 'Z có trung bình 0 và phương sai 1; các quan sát là bản sao giống nhau'), [b('The true sample mean equals Z, so √nX̄=√nZ; its spread grows and it is not an ordinary fixed-scale normal limit.', 'Trung bình mẫu thật bằng Z, nên √nX̄=√nZ; độ phân tán tăng và không có giới hạn chuẩn tỷ lệ cố định thông thường.'), b('The observed sample has all entries equal, so its empirical variance sₙ² is zero.', 'Mẫu quan sát có mọi giá trị bằng nhau, nên phương sai thực nghiệm sₙ² bằng không.'), b('The iid bootstrap therefore resamples a point mass and reports zero conditional spread, missing the true random common shock.', 'Vì vậy bootstrap iid lấy lại khối lượng tại một điểm và báo độ phân tán có điều kiện bằng không, bỏ sót cú sốc chung ngẫu nhiên thật.')]),
    t(b('Match the resampling method to the sampling design and null hypothesis, then state the premise that makes it valid.', 'Ghép phương pháp lấy mẫu lại với thiết kế lấy mẫu và giả thuyết không, rồi nêu tiền đề đảm bảo hợp lệ.'), f('iid mean → bootstrap; sharp randomized null → permutation; weak unequal-variance mean null → neither by default', 'method assumptions must match design', 'giả thiết phương pháp phải khớp thiết kế'), [b('For iid mean estimation with finite variance, the empirical bootstrap is a default asymptotic choice; dependence or heavy tails need separate justification.', 'Với ước lượng trung bình iid có phương sai hữu hạn, bootstrap thực nghiệm là lựa chọn tiệm cận mặc định; phụ thuộc hoặc đuôi nặng cần biện minh riêng.'), b('For a sharp randomized-treatment null, permutation is exact under the assignment mechanism and exchangeability of potential outcomes under the null.', 'Với giả thuyết không sắc trong thử nghiệm ngẫu nhiên, hoán vị chính xác theo cơ chế phân công và tính hoán đổi của kết quả tiềm năng dưới giả thuyết không.'), b('For equality of means with unequal variances, raw permutation can fail exchangeability; use a studentized method or a suitable bootstrap after verifying its assumptions.', 'Với bằng nhau của trung bình nhưng phương sai khác nhau, hoán vị thô có thể thiếu tính hoán đổi; dùng phương pháp studentized hoặc bootstrap phù hợp sau khi kiểm tra giả thiết.')]),
  ],
  53: [
    t(b('Write the expected kernel estimate as a convolution, then Taylor-expand the density around the interior target x.', 'Viết kỳ vọng của ước lượng kernel thành phép chập rồi khai triển Taylor mật độ quanh điểm x bên trong.'), f('E f̂_h(x)=∫K(u)f(x−hu)du;  Bias≈(h²/2)μ₂(K)f″(x)', 'd=1; symmetric kernel, ∫K=1, finite second moment; interior x and smooth f', 'd=1; kernel đối xứng, ∫K=1, moment bậc hai hữu hạn; x bên trong và f trơn'), [b('Substitute u=(x−y)/h into E f̂_h(x)=∫h⁻¹K((x−y)/h)f(y)dy.', 'Đặt u=(x−y)/h trong E f̂_h(x)=∫h⁻¹K((x−y)/h)f(y)dy.'), b('Taylor gives f(x−hu)=f(x)−hu f′(x)+(h²u²/2)f″(x)+o(h²u²).', 'Taylor cho f(x−hu)=f(x)−hu f′(x)+(h²u²/2)f″(x)+o(h²u²).'), b('Kernel symmetry makes ∫uK(u)du=0, so the leading bias is (h²/2)μ₂(K)f″(x).', 'Tính đối xứng làm ∫uK(u)du=0, nên độ chệch chính là (h²/2)μ₂(K)f″(x).')]),
    t(b('Count only observations within bandwidth h and balance the squared bias against sampling variance.', 'Chỉ đếm quan sát trong băng thông h rồi cân bằng bình phương độ chệch với phương sai lấy mẫu.'), f('Var f̂_h(x)≈f(x)R(K)/(nh);  h_opt∝n^(−1/5);  MSE_opt∝n^(−4/5)', 'd=1; leading squared bias C²h⁴ and variance D/(nh), C,D>0', 'd=1; bình phương độ chệch chính C²h⁴ và phương sai D/(nh), C,D>0'), [b('At a fixed interior x, the leading variance is f(x)R(K)/(nh).', 'Tại x bên trong cố định, phương sai chính là f(x)R(K)/(nh).'), b('Minimize C²h⁴+D/(nh): differentiation balances h³ with 1/(nh²), so h⁵ is proportional to 1/n.', 'Tối thiểu C²h⁴+D/(nh): đạo hàm cân bằng h³ với 1/(nh²), nên h⁵ tỷ lệ với 1/n.'), b('Thus h is order n^(−1/5), and both leading MSE terms are order n^(−4/5).', 'Do đó h có bậc n^(−1/5), và cả hai số hạng MSE chính có bậc n^(−4/5).')]),
    t(b('At the support boundary, half of a symmetric kernel window falls outside the density’s support.', 'Tại biên giá đỡ, một nửa cửa sổ kernel đối xứng nằm ngoài miền có mật độ.'), f('E f̂_h(0)≈f(0)∫₀∞K(u)du=f(0)/2', 'support [0,∞); symmetric unit-integral kernel; small h', 'giá đỡ [0,∞); kernel đối xứng tích phân một; h nhỏ'), [b('At x=0, only sample points y≥0 contribute to the kernel average.', 'Tại x=0, chỉ các điểm mẫu y≥0 đóng góp vào trung bình kernel.'), b('After scaling y=hu, the expectation integrates the kernel over only one half-line; symmetry assigns mass 1/2 there.', 'Sau khi đổi thang y=hu, kỳ vọng tích phân kernel trên một nửa trục; tính đối xứng cho khối lượng 1/2.'), b('The estimator is asymptotically near f(0)/2, not f(0); the interior Taylor expansion assumes a full neighborhood around x and fails at the boundary.', 'Ước lượng tiệm cận gần f(0)/2, không phải f(0); khai triển Taylor bên trong cần lân cận đầy đủ quanh x nên thất bại tại biên.')]),
    t(b('Balance the d-dimensional variance term against squared second-order bias and compare the resulting exponent with one dimension.', 'Cân bằng số hạng phương sai d chiều với bình phương độ chệch bậc hai rồi so sánh số mũ với một chiều.'), f('h⁴+(nh³)⁻¹;  h_opt∝n^(−1/7);  MSE_opt∝n^(−4/7)', 'd=3 and nonzero leading bias coefficient', 'd=3 và hệ số độ chệch chính khác không'), [b('For general d, the variance order is 1/(nhᵈ), while squared bias is h⁴.', 'Với d tổng quát, phương sai có bậc 1/(nhᵈ), còn bình phương độ chệch có bậc h⁴.'), b('Balance h⁴≈1/(nhᵈ), giving h^(d+4)≈1/n; at d=3, h≈n^(−1/7).', 'Cân bằng h⁴≈1/(nhᵈ), được h^(d+4)≈1/n; với d=3, h≈n^(−1/7).'), b('Substitution gives MSE order n^(−4/7). In d=1 the rate is n^(−4/5), so the dimension increase slows convergence.', 'Thay vào cho MSE bậc n^(−4/7). Với d=1 tốc độ là n^(−4/5), nên tăng chiều làm hội tụ chậm hơn.')]),
    t(b('Insert the Gaussian density and its curvature at zero into the one-dimensional bias-variance expansion.', 'Thay mật độ Gaussian và độ cong tại không vào khai triển chệch-phương sai một chiều.'), f('f(0)=1/√(2π);  f″(0)=−1/√(2π);  R(K)=1/(2√π);  h_opt∝n^(−1/5)', 'Xᵢ∼N(0,1), x=0; smooth interior density; Gaussian kernel needs tail domination', 'Xᵢ∼N(0,1), x=0; mật độ trơn ở điểm trong; kernel Gaussian cần khống chế đuôi'), [b('For the standard normal density, f(0)=1/√(2π) and f″(0)=−f(0).', 'Với mật độ chuẩn tắc, f(0)=1/√(2π) và f″(0)=−f(0).'), b('For Gaussian K, ∫K²=1/(2√π), and μ₂(K)=1; the leading MSE is h⁴f″(0)²/4 + f(0)/(2√π nh).', 'Với K Gaussian, ∫K²=1/(2√π) và μ₂(K)=1; MSE chính là h⁴f″(0)²/4 + f(0)/(2√π nh).'), b('Balancing h⁴ and 1/(nh) gives h of order n^(−1/5), with MSE order n^(−4/5); the noncompact Gaussian kernel needs a condition controlling Taylor tails.', 'Cân bằng h⁴ và 1/(nh) cho h bậc n^(−1/5), MSE bậc n^(−4/5); kernel Gaussian không compact cần điều kiện khống chế đuôi Taylor.')]),
  ],
  54: [
    t(b('Turn any estimator into a nearest-parameter test; a testing error forces the estimate to be at least half the parameter separation away.', 'Biến mọi ước lượng thành kiểm định chọn tham số gần nhất; lỗi kiểm định buộc ước lượng cách tham số ít nhất nửa khoảng cách.'), f('max_j E_j(δ−θⱼ)² ≥ (Δ²/8)(1−TV(P₀,P₁))', 'two parameter points distance Δ; squared-error loss', 'hai điểm tham số cách Δ; mất mát sai số bình phương'), [b('Define the test to choose the parameter point nearest δ. If it chooses the wrong point, |δ−θⱼ|≥Δ/2.', 'Định nghĩa kiểm định chọn điểm tham số gần δ nhất. Nếu chọn sai thì |δ−θⱼ|≥Δ/2.'), b('Average the two risks: the average is at least (Δ²/8) times the sum of the two testing error probabilities.', 'Lấy trung bình hai rủi ro: trung bình ít nhất bằng (Δ²/8) nhân tổng xác suất lỗi kiểm định.'), b('For any test that error sum is at least 1−TV(P₀,P₁); maximum risk dominates average risk, proving the bound.', 'Với mọi kiểm định, tổng lỗi ít nhất 1−TV(P₀,P₁); rủi ro cực đại trội hơn trung bình, chứng minh chặn.')]),
    t(b('Compute the product-sample Kullback–Leibler divergence, then use Pinsker to keep the two laws hard to distinguish.', 'Tính độ phân kỳ Kullback–Leibler của mẫu tích rồi dùng Pinsker để giữ hai luật khó phân biệt.'), f('KL(P₀ⁿ||P₁ⁿ)=−(n/2)log(1−4δ²);  δ=1/(4√n) ⇒ risk≥1/(192n)', 'Bernoulli p₀=1/2, p₁=1/2+δ; n observations', 'Bernoulli p₀=1/2, p₁=1/2+δ; n quan sát'), [b('For one observation, KL=−(1/2)log(1−4δ²); independence multiplies this by n.', 'Với một quan sát, KL=−(1/2)log(1−4δ²); độc lập nhân giá trị này với n.'), b('At δ=1/(4√n), −log(1−1/(4n))≤1/(4n−1), so KL≤n/[2(4n−1)]≤1/6; Pinsker gives TV≤1/√12<1/3.', 'Với δ=1/(4√n), −log(1−1/(4n))≤1/(4n−1), nên KL≤n/[2(4n−1)]≤1/6; Pinsker cho TV≤1/√12<1/3.'), b('The two-point bound is δ²(1−TV)/8 ≥ [1/(16n)]·(2/3)/8=1/(192n).', 'Chặn hai điểm là δ²(1−TV)/8 ≥ [1/(16n)]·(2/3)/8=1/(192n).')]),
    t(b('Evaluate the testing distinguishability factor when the two observation laws have disjoint supports.', 'Tính thừa số phân biệt khi hai luật quan sát có giá đỡ rời nhau.'), f('TV(P₀,P₁)=1 ⇒ (Δ²/8)(1−TV)=0', 'disjoint supports', 'giá đỡ rời nhau'), [b('Disjoint probability supports permit a test with zero error: identify which support contains the observation.', 'Hai giá đỡ xác suất rời nhau cho phép kiểm định không lỗi: xác định quan sát thuộc giá đỡ nào.'), b('Their total variation distance is one, so the Le Cam lower bound becomes zero.', 'Khoảng cách biến phân toàn phần bằng một, nên chặn dưới Le Cam bằng không.'), b('The bound is vacuous here; it neither proves positive risk nor rules out an estimator achieving zero error on this two-point experiment.', 'Chặn này vô hiệu ở đây; nó không chứng minh rủi ro dương cũng không loại trừ ước lượng sai số không trong thí nghiệm hai điểm.')]),
    t(b('Convert a low-error test into an estimator that selects one of the two parameter values.', 'Chuyển kiểm định có xác suất lỗi thấp thành ước lượng chọn một trong hai giá trị tham số.'), f('max_j E_j(δ−θⱼ)²≤Δ²α', 'test maximum error≤α; estimator reports the tested point', 'xác suất lỗi kiểm định cực đại≤α; ước lượng báo điểm được chọn'), [b('Let the estimator output θ₀ or θ₁ according to the test.', 'Cho ước lượng xuất θ₀ hoặc θ₁ theo kết quả kiểm định.'), b('When correct, squared error is zero; when wrong, the estimate is Δ away and loss is Δ².', 'Khi đúng, sai số bình phương bằng không; khi sai, ước lượng cách Δ và mất mát là Δ².'), b('Under either parameter, expected loss is Δ² times its error probability, at most Δ²α.', 'Dưới mỗi tham số, mất mát kỳ vọng bằng Δ² nhân xác suất lỗi, không quá Δ²α.')]),
    t(b('Apply the two-point bound at the n-dependent separation and the stated total-variation ceiling.', 'Áp dụng chặn hai điểm với khoảng cách phụ thuộc n và giới hạn biến phân toàn phần đã cho.'), f('max risk ≥ Δₙ²(1−TV)/8 ≥ c²/(16n)', 'Δₙ=c/√n and TV(P₀ⁿ,P₁ⁿ)≤1/2', 'Δₙ=c/√n và TV(P₀ⁿ,P₁ⁿ)≤1/2'), [b('Square the separation: Δₙ²=c²/n.', 'Bình phương khoảng cách: Δₙ²=c²/n.'), b('The testing factor is at least 1−1/2=1/2.', 'Thừa số kiểm định ít nhất là 1−1/2=1/2.'), b('Substitution yields a minimax squared-error lower bound c²/(16n); the constant scales quadratically with c.', 'Thay vào được chặn dưới minimax sai số bình phương c²/(16n); hằng số tăng theo bình phương c.')]),
  ],
  55: [
    t(b('Use Gaussian fourth moments to compute the variance of each covariance coordinate, then sum the squared coordinate errors.', 'Dùng moment bậc bốn Gaussian để tính phương sai từng tọa độ hiệp phương sai rồi cộng sai số bình phương.'), f('E||S−Σ||²_F=[tr(Σ²)+(trΣ)²]/n', 'S=n⁻¹ΣᵢXᵢXᵢᵀ; iid N_p(0,Σ)', 'S=n⁻¹ΣᵢXᵢXᵢᵀ; N_p(0,Σ) iid'), [b('For entries, Cov(S_jk,S_lm)=n⁻¹(Σ_jlΣ_km+Σ_jmΣ_kl) by the Gaussian fourth-moment identity.', 'Với các phần tử, Cov(S_jk,S_lm)=n⁻¹(Σ_jlΣ_km+Σ_jmΣ_kl) theo đồng nhất thức moment bậc bốn Gaussian.'), b('Set l=j,m=k to obtain Var(S_jk)=n⁻¹(Σ_jjΣ_kk+Σ_jk²).', 'Đặt l=j,m=k được Var(S_jk)=n⁻¹(Σ_jjΣ_kk+Σ_jk²).'), b('Summing over j,k gives ((trΣ)²+tr(Σ²))/n, the exact Frobenius risk.', 'Cộng theo j,k cho ((trΣ)²+tr(Σ²))/n, tức rủi ro Frobenius chính xác.')]),
    t(b('Expand the squared Frobenius norm of the convex combination and use unbiasedness to remove its cross term.', 'Khai triển chuẩn Frobenius bình phương của tổ hợp lồi rồi dùng tính không chệch để loại số hạng chéo.'), f('R(λ)=(1−λ)²V+λ²||T−Σ||²_F', 'S unbiased for Σ; T deterministic; 0≤λ≤1', 'S không chệch cho Σ; T xác định; 0≤λ≤1'), [b('Write S_λ−Σ=(1−λ)(S−Σ)+λ(T−Σ) and expand the squared norm.', 'Viết S_λ−Σ=(1−λ)(S−Σ)+λ(T−Σ) rồi khai triển chuẩn bình phương.'), b('The cross term has expectation proportional to ⟨E(S−Σ),T−Σ⟩=0 because E[S]=Σ.', 'Số hạng chéo có kỳ vọng tỷ lệ với ⟨E(S−Σ),T−Σ⟩=0 vì E[S]=Σ.'), b('The remaining terms give (1−λ)²V+λ²||T−Σ||²_F.', 'Các số hạng còn lại cho (1−λ)²V+λ²||T−Σ||²_F.')]),
    t(b('Specialize the exact Frobenius risk to an isotropic covariance and check the sample rank before inversion.', 'Rút gọn rủi ro Frobenius cho hiệp phương sai đẳng hướng rồi kiểm tra hạng mẫu trước khi nghịch đảo.'), f('Risk=p(p+1)σ⁴/n;  rank(S)=min(p,n) a.s.', 'Σ=σ²I_p; known zero mean; Gaussian samples', 'Σ=σ²I_p; trung bình không đã biết; mẫu Gaussian'), [b('Here tr(Σ²)=pσ⁴ and (trΣ)²=p²σ⁴, so risk is p(p+1)σ⁴/n.', 'Ở đây tr(Σ²)=pσ⁴ và (trΣ)²=p²σ⁴, nên rủi ro là p(p+1)σ⁴/n.'), b('The p×n data matrix has generic Gaussian rank min(p,n) almost surely.', 'Ma trận dữ liệu p×n có hạng Gaussian tổng quát min(p,n) hầu chắc chắn.'), b('If p>n, S is singular; if p=n, it is full rank almost surely under Σ≻0, although it may be poorly conditioned.', 'Nếu p>n thì S suy biến; nếu p=n thì S đủ hạng h.k.n. khi Σ≻0, dù có thể điều kiện xấu.')]),
    t(b('Compare shrinkage risk at a general λ with raw risk V to find when a large weight on a poor target hurts.', 'So sánh rủi ro co tại λ tổng quát với rủi ro thô V để tìm khi trọng số lớn vào đích kém gây hại.'), f('R(λ)−V=λ[λ(V+D²)−2V]', 'D²=||T−Σ||²_F; λ∈[0,1]', 'D²=||T−Σ||²_F; λ∈[0,1]'), [b('Use R(λ)=(1−λ)²V+λ²D².', 'Dùng R(λ)=(1−λ)²V+λ²D².'), b('Subtract V and factor: R(λ)−V=λ[λ(V+D²)−2V].', 'Trừ V và phân tích: R(λ)−V=λ[λ(V+D²)−2V].'), b('For V>0, shrinkage increases risk when λ>2V/(V+D²); for example, a very poor target with λ near one can make risk exceed raw S.', 'Khi V>0, co làm tăng rủi ro nếu λ>2V/(V+D²); chẳng hạn đích rất kém và λ gần một có thể làm rủi ro vượt S thô.')]),
    t(b('Minimize the quadratic shrinkage risk by differentiating and compare it with the two endpoints.', 'Tối thiểu hóa rủi ro co bậc hai bằng đạo hàm rồi so sánh với hai đầu mút.'), f('λ*=V/(V+D²)=12/16=3/4;  R*=VD²/(V+D²)=3', 'V=12; D²=||T−Σ||²_F=4', 'V=12; D²=||T−Σ||²_F=4'), [b('Differentiate R(λ)=(1−λ)²12+4λ²; setting −24(1−λ)+8λ=0 gives λ=3/4.', 'Lấy đạo hàm R(λ)=(1−λ)²12+4λ²; giải −24(1−λ)+8λ=0 được λ=3/4.'), b('The minimized risk is 12·4/(12+4)=3.', 'Rủi ro tối thiểu là 12·4/(12+4)=3.'), b('Raw S has risk 12 and target-only T has risk 4, so the oracle combination improves on both.', 'S thô có rủi ro 12 và chỉ dùng đích T có rủi ro 4, nên tổ hợp oracle cải thiện cả hai.')]),
  ],
  56: [
    t(b('Compare the lasso objective at β̂ and β*, then bound the noise inner product by its infinity norm.', 'So sánh mục tiêu lasso tại β̂ và β*, rồi chặn tích vô hướng nhiễu bằng chuẩn vô cùng.'), f('Q/2+(λ/2)||Δ_{Sᶜ}||₁≤(3λ/2)||Δ_S||₁', 'Δ=β̂−β*; λ≥2||Xᵀε/n||∞; β* supported on S', 'Δ=β̂−β*; λ≥2||Xᵀε/n||∞; β* có giá đỡ S'), [b('Optimality gives ||y−Xβ̂||²/(2n)+λ||β̂||₁≤||y−Xβ*||²/(2n)+λ||β*||₁.', 'Tính tối ưu cho ||y−Xβ̂||²/(2n)+λ||β̂||₁≤||y−Xβ*||²/(2n)+λ||β*||₁.'), b('Substitute y=Xβ*+ε and expand; the noise term is bounded by ||Xᵀε/n||∞||Δ||₁≤(λ/2)||Δ||₁.', 'Thay y=Xβ*+ε và khai triển; số hạng nhiễu bị chặn bởi ||Xᵀε/n||∞||Δ||₁≤(λ/2)||Δ||₁.'), b('Use ||β*||₁−||β*+Δ||₁≤||Δ_S||₁−||Δ_{Sᶜ}||₁, then rearrange to the stated basic inequality and cone.', 'Dùng ||β*||₁−||β*+Δ||₁≤||Δ_S||₁−||Δ_{Sᶜ}||₁, rồi chuyển vế được bất đẳng thức cơ bản và điều kiện hình nón.')]),
    t(b('Combine the basic inequality, cone condition, and restricted eigenvalue bound to control prediction and coefficient errors.', 'Kết hợp bất đẳng thức cơ bản, điều kiện hình nón và chặn eigenvalue hạn chế để khống chế sai số dự báo và hệ số.'), f('Q≤9λ²s/κ²;  ||Δ||₁≤12λs/κ²', 'Q=||XΔ||²₂/n; Δ in cone; ||XΔ||₂/√n≥κ||Δ_S||₂', 'Q=||XΔ||²₂/n; Δ trong hình nón; ||XΔ||₂/√n≥κ||Δ_S||₂'), [b('Cone membership gives ||Δ_{Sᶜ}||₁≤3||Δ_S||₁, hence ||Δ||₁≤4||Δ_S||₁.', 'Điều kiện hình nón cho ||Δ_{Sᶜ}||₁≤3||Δ_S||₁, nên ||Δ||₁≤4||Δ_S||₁.'), b('The basic inequality implies Q/2≤(3λ/2)||Δ_S||₁≤(3λ/2)√s||Δ_S||₂; RE gives ||Δ_S||₂≤√Q/κ.', 'Bất đẳng thức cơ bản suy ra Q/2≤(3λ/2)||Δ_S||₁≤(3λ/2)√s||Δ_S||₂; RE cho ||Δ_S||₂≤√Q/κ.'), b('Solve for √Q≤3λ√s/κ to get Q≤9λ²s/κ²; then ||Δ||₁≤4√s·3λ√s/κ²=12λs/κ².', 'Giải được √Q≤3λ√s/κ, suy ra Q≤9λ²s/κ²; tiếp đó ||Δ||₁≤4√s·3λ√s/κ²=12λs/κ².')]),
    t(b('For orthogonal columns, apply the soft-threshold function coordinatewise to Xᵀy/n.', 'Với các cột trực giao, áp dụng hàm ngưỡng mềm theo từng tọa độ của Xᵀy/n.'), f('β̂ⱼ=sign(zⱼ)(|zⱼ|−λ)₊', 'XᵀX/n=I; objective uses λ||β||₁', 'XᵀX/n=I; mục tiêu dùng λ||β||₁'), [b('For z₁=2.7, soft thresholding at .5 gives 2.2.', 'Với z₁=2.7, ngưỡng mềm .5 cho 2.2.'), b('For z₂=.4 the magnitude is below .5, so the coefficient is 0; for z₃=−1.2 the result is −(.7)=−.7.', 'Với z₂=.4 có độ lớn dưới .5 nên hệ số bằng 0; với z₃=−1.2 kết quả là −(.7)=−.7.'), b('Thus β̂=(2.2,0,−0.7) and the selected support is {1,3}.', 'Vậy β̂=(2.2,0,−0.7) và giá đỡ được chọn là {1,3}.')]),
    t(b('Identical design columns create multiple coefficient vectors with the same fitted values.', 'Các cột thiết kế giống nhau tạo nhiều vector hệ số có cùng giá trị khớp.'), f('X₁=X₂ ⇒ X(1,0)=X(0,1)', 'no additional identifiability restriction', 'không có ràng buộc nhận dạng bổ sung'), [b('If X₁=X₂, then Xβ for β=(1,0) equals X₁ and for β=(0,1) equals X₂.', 'Nếu X₁=X₂ thì Xβ với β=(1,0) bằng X₁, còn với β=(0,1) bằng X₂.'), b('The two distinct coefficient labels produce exactly the same mean vector and likelihood for every noise realization.', 'Hai nhãn hệ số khác nhau sinh cùng vector trung bình và likelihood với mọi nhiễu.'), b('No statistic of the data can distinguish them without extra design, sparsity-selection, or tie-breaking assumptions.', 'Không thống kê dữ liệu nào phân biệt được chúng nếu thiếu giả thiết thiết kế, chọn thưa hoặc phá hòa bổ sung.')]),
    t(b('Choose λ at least twice the supplied noise score bound, then substitute its order into the restricted-eigenvalue prediction rate.', 'Chọn λ ít nhất gấp đôi chặn score nhiễu đã cho rồi thay bậc của nó vào tốc độ dự báo eigenvalue hạn chế.'), f('λ≥2cσ√(log p/n);  Q=O(σ²s log p/n)', 'high-probability score bound; κ bounded below', 'chặn score đúng với xác suất cao; κ bị chặn dưới'), [b('A safe choice is λ=2cσ√(log p/n), or a larger constant multiple.', 'Lựa chọn an toàn là λ=2cσ√(log p/n), hoặc bội hằng số lớn hơn.'), b('The deterministic theorem gives Q≤9λ²s/κ².', 'Định lý xác định cho Q≤9λ²s/κ².'), b('If κ≥κ₀>0, substitution yields Q=O(σ²s log p/n) with the stated high probability.', 'Nếu κ≥κ₀>0, thay vào cho Q=O(σ²s log p/n) với xác suất cao như đã nêu.')]),
  ],
  57: [
    t(b('Multiply the prior density kernel by the Bernoulli likelihood and collect powers of p and 1−p.', 'Nhân nhân mật độ tiên nghiệm với likelihood Bernoulli rồi gom số mũ của p và 1−p.'), f('p|X∼Beta(a+S,b+n−S)', 'Beta(a,b) prior; iid Bernoulli observations with S successes', 'tiên nghiệm Beta(a,b); quan sát Bernoulli iid có S lần thành công'), [b('The prior kernel is p^(a−1)(1−p)^(b−1).', 'Nhân tiên nghiệm là p^(a−1)(1−p)^(b−1).'), b('The likelihood contributes p^S(1−p)^(n−S).', 'Likelihood đóng góp p^S(1−p)^(n−S).'), b('The posterior kernel is p^(a+S−1)(1−p)^(b+n−S−1), the Beta(a+S,b+n−S) family after normalization.', 'Nhân hậu nghiệm là p^(a+S−1)(1−p)^(b+n−S−1), thuộc họ Beta(a+S,b+n−S) sau chuẩn hóa.')]),
    t(b('Update the prior counts with observed successes and failures, then use the posterior mean for prediction.', 'Cập nhật số đếm tiên nghiệm bằng thành công và thất bại quan sát rồi dùng trung bình hậu nghiệm để dự báo.'), f('p|data∼Beta(9,5);  E[p|data]=P(X₁₁=1|data)=9/14', 'Beta(2,2) prior; S=7 successes in n=10', 'tiên nghiệm Beta(2,2); S=7 thành công trong n=10'), [b('Posterior parameters are a+S=2+7=9 and b+n−S=2+3=5.', 'Tham số hậu nghiệm là a+S=2+7=9 và b+n−S=2+3=5.'), b('The posterior is Beta(9,5), with mean 9/(9+5)=9/14.', 'Hậu nghiệm là Beta(9,5), có trung bình 9/(9+5)=9/14.'), b('The next Bernoulli success probability is E[p|data]=9/14 by posterior predictive averaging.', 'Xác suất lần Bernoulli tiếp theo thành công là E[p|data]=9/14 theo trung bình dự báo hậu nghiệm.')]),
    t(b('Rewrite the posterior mean by separating prior and sample contributions to expose shrinkage weights.', 'Viết lại trung bình hậu nghiệm bằng cách tách đóng góp tiên nghiệm và mẫu để thấy trọng số co.'), f('(a+S)/(a+b+n)=[(a+b)/(a+b+n)]·[a/(a+b)]+[n/(a+b+n)]·(S/n)', 'a,b>0; n>0', 'a,b>0; n>0'), [b('Multiply the prior mean by prior effective count a+b: (a+b)·a/(a+b)=a.', 'Nhân trung bình tiên nghiệm với cỡ mẫu hiệu dụng a+b được (a+b)·a/(a+b)=a.'), b('Multiply the sample proportion by n: n·S/n=S; divide their sum by a+b+n to recover the posterior mean.', 'Nhân tỷ lệ mẫu với n được n·S/n=S; chia tổng cho a+b+n để được trung bình hậu nghiệm.'), b('The prior weight is (a+b)/(a+b+n) and tends to zero as n grows; the data weight tends to one.', 'Trọng số tiên nghiệm là (a+b)/(a+b+n) và tiến về không khi n tăng; trọng số dữ liệu tiến về một.')]),
    t(b('A point-mass prior fixes the posterior parameter regardless of observations, even when the true data-generating value differs.', 'Tiên nghiệm khối lượng tại một điểm cố định tham số hậu nghiệm bất kể dữ liệu, kể cả khi giá trị sinh dữ liệu thật khác.'), f('Prior δ₀.₂ ⇒ posterior δ₀.₂ for every sample', 'prior assigns probability one to p=0.2; true p=0.8', 'tiên nghiệm gán xác suất một cho p=0.2; p thật là 0.8'), [b('Bayes’ rule can only reweight values with prior mass; the prior support contains only p=.2.', 'Quy tắc Bayes chỉ tái trọng số các giá trị có khối lượng tiên nghiệm; giá đỡ tiên nghiệm chỉ chứa p=.2.'), b('Therefore every posterior remains δ₀.₂ and a 95% credible set can be the singleton {.2}.', 'Vì vậy mọi hậu nghiệm vẫn là δ₀.₂ và tập credible 95% có thể là singleton {.2}.'), b('Under repeated samples at true p=.8, that set covers the true value with probability zero, showing posterior credibility is not automatic frequentist coverage.', 'Dưới các mẫu lặp lại với p thật=.8, tập này chứa giá trị thật với xác suất không, cho thấy credibility hậu nghiệm không tự động là độ phủ tần suất.')]),
    t(b('Update prior odds by multiplying by the likelihood ratio contributed by the observed success count.', 'Cập nhật odds tiên nghiệm bằng cách nhân với tỷ số likelihood do số thành công quan sát đóng góp.'), f('Posterior odds=(π₁/π₀)(p₁/p₀)^S((1−p₁)/(1−p₀))^(n−S)', 'two point hypotheses p₀,p₁; prior masses π₀,π₁', 'hai giả thuyết điểm p₀,p₁; khối lượng tiên nghiệm π₀,π₁'), [b('Under pⱼ, the likelihood for S successes is proportional to pⱼ^S(1−pⱼ)^(n−S).', 'Dưới pⱼ, likelihood của S thành công tỷ lệ với pⱼ^S(1−pⱼ)^(n−S).'), b('Bayes’ rule gives posterior odds equal prior odds times the ratio of those likelihoods.', 'Quy tắc Bayes cho odds hậu nghiệm bằng odds tiên nghiệm nhân tỷ số hai likelihood.'), b('More successes favor the larger p through (p₁/p₀)^S; the prior odds remain the starting weight.', 'Nhiều thành công ủng hộ p lớn hơn qua (p₁/p₀)^S; odds tiên nghiệm vẫn là trọng số xuất phát.')]),
  ],
  58: [
    t(b('Use a union bound for Bonferroni; for Holm, find the first true null in the ordered list that can survive step-down testing.', 'Dùng chặn hợp cho Bonferroni; với Holm, tìm giả thuyết không thật đầu tiên trong danh sách sắp xếp có thể vượt qua bước xuống.'), f('Bonferroni: pᵢ≤α/m;  Holm: p_(k)≤α/(m−k+1)', 'true-null p-values super-uniform; Holm valid under arbitrary dependence', 'p-value giả thuyết không thật siêu đều; Holm đúng dưới mọi phụ thuộc'), [b('Bonferroni rejects a true null with probability at most α/m; summing across at most m true nulls bounds FWER by α.', 'Bonferroni bác bỏ nhầm mỗi giả thuyết không thật với xác suất nhiều nhất α/m; cộng tối đa m giả thuyết thật chặn FWER bởi α.'), b('For Holm, let k be the first true null in sorted order. If it is rejected, its p-value is at most α/(m−k+1), which is no larger than α divided by the number of true nulls.', 'Với Holm, gọi k là giả thuyết không thật đầu tiên theo thứ tự tăng. Nếu bị bác bỏ, p-value không vượt α/(m−k+1), không lớn hơn α chia số giả thuyết không thật.'), b('Super-uniformity and a union bound over true nulls give probability at most α that this first true null is rejected; then no later true null can be rejected.', 'Tính siêu đều và chặn hợp trên các giả thuyết không thật cho xác suất không quá α để giả thuyết thật đầu tiên bị bác bỏ; khi đó không giả thuyết thật nào phía sau bị bác bỏ.')]),
    t(b('Apply each procedure’s ordered threshold to the four supplied p-values.', 'Áp dụng ngưỡng đã sắp xếp của từng thủ tục cho bốn p-value đã cho.'), f('Bonferroni α/m=.0125; Holm thresholds α/(m−k+1); BH thresholds kq/m', 'ordered p=(.004,.018,.041,.20), m=4, α=q=.05', 'p đã sắp=(.004,.018,.041,.20), m=4, α=q=.05'), [b('Bonferroni threshold is .05/4=.0125, so only .004 is rejected.', 'Ngưỡng Bonferroni là .05/4=.0125, nên chỉ bác bỏ .004.'), b('Holm passes .004≤.0125, then stops because .018>.05/3≈.0167; it rejects only the first.', 'Holm qua .004≤.0125 rồi dừng vì .018>.05/3≈.0167; chỉ bác bỏ p-value đầu.'), b('BH thresholds are .0125,.025,.0375,.05; the largest passing rank is 2, so reject .004 and .018.', 'Ngưỡng BH là .0125,.025,.0375,.05; hạng lớn nhất đạt là 2, nên bác bỏ .004 và .018.')]),
    t(b('Interpret FDR as an expectation of the false-discovery proportion under the theorem’s dependence conditions.', 'Diễn giải FDR là kỳ vọng tỷ lệ phát hiện sai theo điều kiện phụ thuộc của định lý.'), f('FDR≤q·m₀/m=.10·12/20=.06', 'm=20 tests; m₀=12 true nulls; independent p-values', 'm=20 kiểm định; m₀=12 giả thuyết không thật; p-value độc lập'), [b('Under independent p-values with super-uniform true-null p-values, BH guarantees FDR≤q m₀/m.', 'Với p-value độc lập và p-value giả thuyết không thật siêu đều, BH bảo đảm FDR≤q m₀/m.'), b('Substitute q=.10, m₀=12, m=20 to get a bound of .06.', 'Thay q=.10, m₀=12, m=20 được chặn .06.'), b('This is an expected fraction across repeated studies; it does not promise that every selected claim or realized dataset has at most 6% false discoveries.', 'Đây là tỷ lệ kỳ vọng qua các nghiên cứu lặp lại; nó không hứa mỗi tuyên bố được chọn hay mỗi dữ liệu thực tế có nhiều nhất 6% phát hiện sai.')]),
    t(b('Compute the realized false-discovery fraction and distinguish it from the event that FWER controls.', 'Tính tỷ lệ phát hiện sai thực tế và phân biệt với biến cố mà FWER khống chế.'), f('FDP=V/R=5/100=.05;  FWER=P(V≥1)', 'R=100, V=5 in the observed dataset', 'R=100, V=5 trong bộ dữ liệu quan sát'), [b('The realized FDP is 5/100=.05.', 'FDP thực tế là 5/100=.05.'), b('FWER concerns the probability that at least one true null is rejected, the event V≥1.', 'FWER liên quan xác suất có ít nhất một giả thuyết không thật bị bác bỏ, tức biến cố V≥1.'), b('A bound on E[FDP] does not bound every realized FDP; rare datasets can have a much larger false fraction.', 'Chặn E[FDP] không chặn mọi FDP thực tế; một số bộ dữ liệu hiếm có thể có tỷ lệ sai lớn hơn nhiều.')]),
    t(b('Match the safety-screen goal to familywise control and the exploratory goal to a false-discovery-rate procedure.', 'Ghép mục tiêu sàng lọc an toàn với kiểm soát familywise và mục tiêu khám phá với thủ tục tỷ lệ phát hiện sai.'), f('Confirmatory any-false goal → Holm/Bonferroni; exploratory expected-FDP goal → BH', 'super-uniform null p-values; BH independence or a justified dependence extension', 'p-value giả thuyết không thật siêu đều; BH cần độc lập hoặc mở rộng phụ thuộc được biện minh'), [b('For a confirmatory safety screen, use Holm or Bonferroni at α=.05; both control the chance of any false alarm under arbitrary dependence.', 'Với sàng lọc an toàn xác nhận, dùng Holm hoặc Bonferroni tại α=.05; cả hai kiểm soát xác suất có bất kỳ báo động giả nào dưới mọi phụ thuộc.'), b('For exploratory genomics at q=.10, use BH when its independence assumption is credible.', 'Với genomics khám phá ở q=.10, dùng BH khi giả thiết độc lập đáng tin.'), b('If tests are dependent, verify an appropriate dependence condition or choose a procedure with a guarantee for that dependence; the two error targets answer different questions.', 'Nếu các kiểm định phụ thuộc, xác minh điều kiện phụ thuộc phù hợp hoặc chọn thủ tục có bảo đảm cho phụ thuộc đó; hai mục tiêu sai số trả lời các câu hỏi khác nhau.')]),
  ],
  59: [
    t(b('Replace the unknown asymptotic variance by a consistent estimate and apply Slutsky to the standardized statistic.', 'Thay phương sai tiệm cận chưa biết bằng ước lượng nhất quán rồi áp dụng Slutsky cho thống kê chuẩn hóa.'), f('√n(Tₙ−θ₀)/√V̂ₙ⇒N(0,1);  Tₙ±z₁₋α/₂√(V̂ₙ/n)', '√n(Tₙ−θ₀)⇒N(0,V), V̂ₙ→PV>0', '√n(Tₙ−θ₀)⇒N(0,V), V̂ₙ→PV>0'), [b('Divide √n(Tₙ−θ₀) by √V̂ₙ; the numerator tends to N(0,V) and denominator to √V.', 'Chia √n(Tₙ−θ₀) cho √V̂ₙ; tử hội tụ tới N(0,V), mẫu tới √V.'), b('Slutsky gives a standard normal studentized limit.', 'Slutsky cho giới hạn studentized chuẩn tắc.'), b('Invert the limit quantiles to obtain Tₙ±z₁₋α/₂√(V̂ₙ/n), with asymptotic coverage 1−α.', 'Đảo các phân vị giới hạn được Tₙ±z₁₋α/₂√(V̂ₙ/n), có độ phủ tiệm cận 1−α.')]),
    t(b('Convert the estimated variance of the root-n error into a standard error for θ̂, then use the normal 1.96 multiplier.', 'Đổi phương sai ước lượng của sai số căn n thành sai số chuẩn cho θ̂ rồi dùng hệ số chuẩn 1.96.'), f('SE=√(V̂/n)=√(2.25/225)=0.1;  CI=1.4±1.96(0.1)', 'V̂ estimates variance of √n(θ̂−θ)', 'V̂ ước lượng phương sai của √n(θ̂−θ)'), [b('The standard error is √(2.25/225)=√.01=.1.', 'Sai số chuẩn là √(2.25/225)=√.01=.1.'), b('The margin is 1.96·.1=.196, giving interval [1.204,1.596].', 'Biên sai số là 1.96·.1=.196, cho khoảng [1.204,1.596].'), b('Evidence is still needed for the asymptotic normal limit, consistency of V̂, and valid post-model-selection calibration if selection occurred.', 'Vẫn cần bằng chứng cho giới hạn chuẩn tiệm cận, tính nhất quán của V̂ và hiệu chuẩn hợp lệ sau chọn mô hình nếu có lựa chọn.')]),
    t(b('Define posterior probability content and repeated-sampling coverage as different probability statements.', 'Định nghĩa khối lượng xác suất hậu nghiệm và độ phủ lấy mẫu lặp lại thành hai mệnh đề xác suất khác nhau.'), f('Posterior: P(p∈C(X)|X)=.95; frequentist: P_θ(θ∈C(X))≈.95', 'credible set conditions on observed data; confidence coverage repeats data at fixed θ', 'tập credible điều kiện theo dữ liệu quan sát; độ phủ tin cậy lặp dữ liệu tại θ cố định'), [b('A 95% posterior credible interval C(X) contains 95% of the posterior distribution after observing X.', 'Khoảng credible hậu nghiệm 95% C(X) chứa 95% phân phối hậu nghiệm sau khi quan sát X.'), b('A nominal 95% confidence interval is calibrated so that repeated samples at each fixed θ contain θ with probability about .95.', 'Khoảng tin cậy danh định 95% được hiệu chuẩn để qua các mẫu lặp tại mỗi θ cố định, nó chứa θ với xác suất khoảng .95.'), b('They coincide only under additional matching choices and a theorem or calibration argument; posterior probability alone does not establish frequentist coverage.', 'Chúng chỉ trùng khi có lựa chọn khớp và định lý hoặc lập luận hiệu chuẩn bổ sung; xác suất hậu nghiệm tự nó không chứng minh độ phủ tần suất.')]),
    t(b('Selection chooses the larger absolute normal statistic, so coverage requires both candidate estimates to fall inside the reported interval.', 'Thủ tục chọn thống kê chuẩn có trị tuyệt đối lớn hơn, nên có độ phủ khi cả hai ước lượng ứng viên nằm trong khoảng đã báo.'), f('P(|Z₁|≤1.96, |Z₂|≤1.96)=.95²=.9025', 'Z₁,Z₂ independent N(0,1); θ=0', 'Z₁,Z₂ độc lập N(0,1); θ=0'), [b('The selected estimate is Zⱼ with the larger |Zⱼ|.', 'Ước lượng được chọn là Zⱼ có |Zⱼ| lớn hơn.'), b('Its interval centered at Zⱼ covers zero exactly when |Zⱼ|≤1.96.', 'Khoảng tâm tại Zⱼ chứa không đúng khi |Zⱼ|≤1.96.'), b('Because the selected absolute value is the maximum, this event requires both |Z₁| and |Z₂|≤1.96; independence gives .95²=.9025.', 'Vì trị tuyệt đối được chọn là lớn nhất, biến cố đòi hỏi cả |Z₁|,|Z₂|≤1.96; độc lập cho .95²=.9025.')]),
    t(b('Audit the claim by checking selection, penalty bias, design assumptions, uncertainty estimation, and the scope of inference.', 'Kiểm tra tuyên bố bằng cách xét lựa chọn, độ chệch do phạt, giả thiết thiết kế, ước lượng bất định và phạm vi suy luận.'), f('Ordinary Wald validity needs a calibrated estimator, variance estimate, and prespecified inference target', 'post-selection inference can change the sampling law', 'suy luận sau lựa chọn có thể đổi luật lấy mẫu'), [b('Lasso selection is data-dependent and shrinks coefficients; an ordinary least-squares Wald interval for the selected coordinate is not automatically centered or calibrated.', 'Lựa chọn lasso phụ thuộc dữ liệu và co hệ số; khoảng Wald bình phương tối thiểu thông thường cho tọa độ được chọn không tự động được tâm hóa hay hiệu chuẩn.'), b('The report needs a valid variance model, sample-size/asymptotic regime, treatment of correlated predictors, and a method accounting for searching among coefficients.', 'Báo cáo cần mô hình phương sai hợp lệ, chế độ cỡ mẫu/tiệm cận, xử lý biến dự báo tương quan và phương pháp tính đến việc tìm kiếm giữa các hệ số.'), b('Without selective inference, sample splitting, or independent confirmation, the interval’s nominal coverage and exclusion of zero do not establish a confirmed effect.', 'Nếu thiếu suy luận chọn lọc, chia mẫu hoặc xác nhận độc lập, độ phủ danh định và việc loại số không không xác nhận được hiệu ứng.')]),
  ],
  60: [
    t(b('Derive the Bernoulli score and information, then use the regular Cramér–Rao argument for an unbiased estimator.', 'Suy ra score và thông tin Bernoulli rồi dùng lập luận Cramér–Rao chính quy cho ước lượng không chệch.'), f('Sₚ=(S−np)/[p(1−p)];  Iₙ(p)=n/[p(1−p)];  Var(T)≥p(1−p)/n', 'iid Bernoulli(p); 0<p<1; T unbiased for p', 'Bernoulli(p) iid; 0<p<1; T không chệch cho p'), [b('Differentiate S log p+(n−S)log(1−p) to obtain score (S−np)/[p(1−p)].', 'Lấy đạo hàm S log p+(n−S)log(1−p) được score (S−np)/[p(1−p)].'), b('The score mean is zero and its variance is n/[p(1−p)], so this is Fisher information.', 'Score có trung bình bằng không và phương sai n/[p(1−p)], tức thông tin Fisher.'), b('For τ(p)=p, the regular CR bound is 1/Iₙ=p(1−p)/n. Common support and valid differentiation fail in moving-support models such as Uniform(0,θ).', 'Với τ(p)=p, chặn CR chính quy là 1/Iₙ=p(1−p)/n. Giá đỡ chung và đổi đạo hàm hợp lệ thất bại trong mô hình giá đỡ dịch chuyển như Uniform(0,θ).')]),
    t(b('Complete the square in the empirical quadratic objective, then show its unique population target separates parameters away from θ₀.', 'Hoàn thành bình phương trong tiêu chuẩn bậc hai thực nghiệm rồi chỉ ra mục tiêu quần thể duy nhất tách khỏi θ₀.'), f('θ̂ₙ=clip(Z̄ₙ,[−1,1])→Pθ₀', 'iid finite second moment; θ₀∈(−1,1)', 'iid có moment bậc hai hữu hạn; θ₀∈(−1,1)'), [b('Expand Mₙ(θ)=−PₙZ²+2θZ̄ₙ−θ²; the θ-dependent part is −(θ−Z̄ₙ)².', 'Khai triển Mₙ(θ)=−PₙZ²+2θZ̄ₙ−θ²; phần phụ thuộc θ là −(θ−Z̄ₙ)².'), b('The maximizer over [−1,1] is the projection of Z̄ₙ onto that interval. Since θ₀ is interior and Z̄ₙ→Pθ₀, clipping changes it with probability tending to zero.', 'Điểm cực đại trên [−1,1] là hình chiếu của Z̄ₙ lên khoảng. Vì θ₀ ở trong và Z̄ₙ→Pθ₀, xác suất phép cắt đổi giá trị tiến về không.'), b('The population criterion differs by −(θ−θ₀)² from its maximum, giving positive separation outside every ε-neighborhood; hence the maximizer is consistent.', 'Tiêu chuẩn quần thể thấp hơn cực đại một lượng (θ−θ₀)², tạo khoảng cách dương ngoài mọi lân cận ε; do đó nghiệm cực đại nhất quán.')]),
    t(b('Balance h⁴ bias-squared with the d=2 variance term and check that the target is an interior point.', 'Cân bằng bình phương độ chệch h⁴ với phương sai d=2 rồi kiểm tra điểm mục tiêu nằm bên trong.'), f('h⁴+(nh²)⁻¹;  h_opt∝n^(−1/6);  MSE_opt∝n^(−2/3)', 'd=2; C₁,C₂>0; interior point with local smoothness', 'd=2; C₁,C₂>0; điểm bên trong có độ trơn cục bộ'), [b('Balance h⁴ and 1/(nh²): h⁶≈1/n, so h has order n^(−1/6).', 'Cân bằng h⁴ và 1/(nh²): h⁶≈1/n, nên h có bậc n^(−1/6).'), b('Substitution gives both leading terms order n^(−2/3).', 'Thay vào cho cả hai số hạng chính bậc n^(−2/3).'), b('At a support boundary, the kernel window is truncated and first-order mass imbalance may create O(h) bias; the symmetric interior Taylor expansion no longer applies.', 'Tại biên giá đỡ, cửa sổ kernel bị cắt và mất cân bằng khối lượng bậc nhất có thể tạo độ chệch O(h); khai triển Taylor nội bộ đối xứng không còn áp dụng.')]),
    t(b('Compare the lasso objective at β̂ and β*, obtain the cone, and invoke the restricted eigenvalue condition on that cone.', 'So sánh mục tiêu lasso tại β̂ và β*, suy ra hình nón rồi dùng điều kiện eigenvalue hạn chế trên hình nón.'), f('||Δ_{Sᶜ}||₁≤3||Δ_S||₁;  ||XΔ||²₂/n≤9λ²s/κ²', 'λ≥2||Xᵀε/n||∞; β* is s-sparse; RE constant κ>0', 'λ≥2||Xᵀε/n||∞; β* thưa s; hằng số RE κ>0'), [b('The basic inequality is Q/2+(λ/2)||Δ_{Sᶜ}||₁≤(3λ/2)||Δ_S||₁, so Δ lies in the lasso cone.', 'Bất đẳng thức cơ bản là Q/2+(λ/2)||Δ_{Sᶜ}||₁≤(3λ/2)||Δ_S||₁, nên Δ nằm trong hình nón lasso.'), b('Drop Q/2≥0 to get ||Δ_{Sᶜ}||₁≤3||Δ_S||₁; thus ||Δ||₁≤4√s||Δ_S||₂.', 'Bỏ Q/2≥0 được ||Δ_{Sᶜ}||₁≤3||Δ_S||₁; do đó ||Δ||₁≤4√s||Δ_S||₂.'), b('Use Q≥κ²||Δ_S||₂² and Q≤3λ√s||Δ_S||₂; combining yields √Q≤3λ√s/κ, hence Q≤9λ²s/κ².', 'Dùng Q≥κ²||Δ_S||₂² và Q≤3λ√s||Δ_S||₂; kết hợp cho √Q≤3λ√s/κ, suy ra Q≤9λ²s/κ².')]),
    t(b('Run the Holm step-down thresholds and the BH step-up thresholds on the same sorted list.', 'Chạy ngưỡng bước xuống Holm và ngưỡng bước lên BH trên cùng danh sách đã sắp.'), f('Holm: α/(m−k+1);  BH: kq/m', 'p=(.003,.011,.04,.07,.5); Holm α=.05; BH q=.10', 'p=(.003,.011,.04,.07,.5); Holm α=.05; BH q=.10'), [b('For Holm, thresholds are .01,.0125,.0167,.025,.05; the first two pass and .04 fails at rank 3, so reject two.', 'Với Holm, ngưỡng là .01,.0125,.0167,.025,.05; hai p đầu đạt và .04 trượt ở hạng 3, nên bác bỏ hai.'), b('For BH, thresholds are .02,.04,.06,.08,.10; ranks 1–4 pass and rank 5 fails, so reject the first four.', 'Với BH, ngưỡng là .02,.04,.06,.08,.10; hạng 1–4 đạt và hạng 5 trượt, nên bác bỏ bốn p đầu.'), b('Holm controls FWER under arbitrary dependence; BH controls FDR under independent tests with valid null p-values.', 'Holm kiểm soát FWER dưới mọi phụ thuộc; BH kiểm soát FDR khi các kiểm định độc lập và p-value không hợp lệ.')]),
    t(b('Use the sandwich covariance for the root-n limit, then divide by n to obtain the estimator standard error.', 'Dùng hiệp phương sai sandwich cho giới hạn căn n rồi chia n để được sai số chuẩn ước lượng.'), f('V=A⁻²B=12/9=4/3;  θ̂ₙ≈N(θ₀,V/n);  SE≈1/√108', 'A=3, B=12, n=144; regular score and derivative assumptions', 'A=3, B=12, n=144; giả thiết score và đạo hàm chính quy'), [b('The root-n limit is N(0,B/A²)=N(0,4/3).', 'Giới hạn căn n là N(0,B/A²)=N(0,4/3).'), b('The estimator variance is approximately V/n=(4/3)/144=1/108.', 'Phương sai ước lượng xấp xỉ V/n=(4/3)/144=1/108.'), b('Thus SE≈1/√108≈0.0962; the theorem also needs a consistent root, mean-zero finite-variance score, and derivative average tending to −A.', 'Vì vậy SE≈1/√108≈0.0962; định lý còn cần nghiệm nhất quán, score trung bình không có phương sai hữu hạn và đạo hàm trung bình hội tụ về −A.')]),
    t(b('Use continuous mapping for the squared limit and the absolute-value limit, then compare their shapes with a centered normal.', 'Dùng ánh xạ liên tục cho giới hạn bình phương và trị tuyệt đối rồi so hình dạng với chuẩn tâm hóa.'), f('nTₙ²⇒Z²∼9χ²₁;  √n|Tₙ|⇒|Z|', '√nTₙ⇒Z∼N(0,9)', '√nTₙ⇒Z∼N(0,9)'), [b('Square the first relation: nTₙ²=(√nTₙ)²⇒Z².', 'Bình phương quan hệ đầu: nTₙ²=(√nTₙ)²⇒Z².'), b('Take absolute values for the second: √n|Tₙ|=|√nTₙ|⇒|Z|.', 'Lấy trị tuyệt đối cho quan hệ hai: √n|Tₙ|=|√nTₙ|⇒|Z|.'), b('Z² is scaled chi-square and |Z| is half-normal; neither is a centered normal first-order delta limit at the nondifferentiable or zero-derivative point.', 'Z² là chi-bình phương tỷ lệ và |Z| là nửa chuẩn; không cái nào là giới hạn delta bậc nhất chuẩn tâm hóa tại điểm không hoặc đạo hàm bằng không.')]),
    t(b('Convert any estimator to a nearest-point test and apply the total-variation distinguishability bound.', 'Chuyển mọi ước lượng thành kiểm định điểm gần nhất rồi áp dụng chặn phân biệt biến phân toàn phần.'), f('max risk≥Δ²(1−TV)/8=.6²·.75/8=.03375', 'two points separated by Δ=.6; TV=.25', 'hai điểm cách Δ=.6; TV=.25'), [b('Classify the estimate according to which parameter point is nearer; a wrong classification incurs squared error at least Δ²/4.', 'Phân loại ước lượng theo điểm tham số nào gần hơn; phân loại sai chịu sai số bình phương ít nhất Δ²/4.'), b('The average testing error is at least 1−TV=.75; multiply by Δ²/8 as in the two-point reduction.', 'Tổng lỗi kiểm định trung bình ít nhất 1−TV=.75; nhân với Δ²/8 như trong phép rút gọn hai điểm.'), b('The risk lower bound is .36·.75/8=.03375, applying to every estimator on the two-point model.', 'Chặn dưới rủi ro là .36·.75/8=.03375, đúng với mọi ước lượng trong mô hình hai điểm.')]),
    t(b('Update the Beta prior by the observed count, then keep posterior probability statements separate from repeated-sample coverage.', 'Cập nhật tiên nghiệm Beta bằng số đếm quan sát rồi tách mệnh đề xác suất hậu nghiệm khỏi độ phủ lấy mẫu lặp.'), f('p|data∼Beta(7,3);  E[p|data]=P(X₇=1|data)=7/10', 'Beta(3,1) prior; 4 successes in 6 trials', 'tiên nghiệm Beta(3,1); 4 thành công trong 6 lần thử'), [b('Posterior parameters are (3+4,1+2)=(7,3).', 'Tham số hậu nghiệm là (3+4,1+2)=(7,3).'), b('The posterior mean and next-success predictive probability are both 7/(7+3)=.7.', 'Trung bình hậu nghiệm và xác suất dự báo thành công tiếp theo đều là 7/(7+3)=.7.'), b('A 95% credible interval contains posterior mass .95 after these data; a 95% confidence procedure targets 95% coverage over repeated samples at each fixed p.', 'Khoảng credible 95% chứa khối lượng hậu nghiệm .95 sau dữ liệu này; thủ tục tin cậy 95% nhắm độ phủ 95% qua các mẫu lặp tại mỗi p cố định.')]),
    t(b('Minimize the oracle quadratic risk and compare it with the risks at λ=0 and λ=1.', 'Tối thiểu hóa rủi ro oracle bậc hai rồi so sánh với rủi ro tại λ=0 và λ=1.'), f('λ*=V/(V+D²)=10/25=.4;  R*=VD²/(V+D²)=6', 'V=10; D²=||T−Σ||²=15; deterministic target', 'V=10; D²=||T−Σ||²=15; đích xác định'), [b('Set derivative of R(λ)=(1−λ)²10+15λ² to zero: −20(1−λ)+30λ=0, so λ=.4.', 'Cho đạo hàm R(λ)=(1−λ)²10+15λ² bằng không: −20(1−λ)+30λ=0, nên λ=.4.'), b('Substitution gives R(.4)=.6²·10+.4²·15=3.6+2.4=6.', 'Thay vào được R(.4)=.6²·10+.4²·15=3.6+2.4=6.'), b('Raw S has risk 10 and target-only T has risk 15; the oracle blend has smaller risk than both.', 'S thô có rủi ro 10 và chỉ dùng đích T có rủi ro 15; tổ hợp oracle có rủi ro nhỏ hơn cả hai.')]),
  ],
};

const teaching: Record<string, Teaching> = {};
for (const week of probabilityInference.weeks) {
  const rows = teachingByWeek[week.week];
  if (!rows || rows.length !== week.exercises.length) {
    throw new Error(`Probability teaching coverage mismatch in week ${week.week}`);
  }
  week.exercises.forEach((exercise, index) => {
    const row = rows[index];
    if (!row || row.steps.length < 3) throw new Error(`Incomplete teaching for ${exercise.id}`);
    teaching[exercise.id] = row;
  });
}

export default teaching;

